window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["3070977"]={"book":{"id":3070977,"title":"管理技能开发","author":"","translator":"王垒","publisher":"","pubdate":"2008-4","isbn":"9787302170938","tags":["管理","领导力","培训","营销","经管营销","经济学","组织与管理心理学","管理与经济学"],"memCount":23},"np":1,"pb":[34],"idx":[{"i":19613,"t":"从行为到感受：三步构建无冲突沟通","l":"TF1-2","c":"小玲(Mia)","g":1,"p":1},{"i":16660,"t":"何为XYZ法以及如何采用XYZ法来有效阐述问题","l":"TF1-2","c":"万娟","g":1,"p":1},{"i":15882,"t":"XYZ模型-一分钟学会表达不满情绪","l":"TF2-2","c":"Shirleyxueli","g":1,"p":1},{"i":12817,"t":"建立最佳的SMART目标","l":"TF1-1","c":"子小木","g":1,"p":1},{"i":9501,"t":"XYZ问题陈述法","l":"TF2-3","c":"梁峻","g":1,"p":1},{"i":9266,"t":"XYZ表达","l":"TF1-2","c":"秦小旺","g":0,"p":1},{"i":8948,"t":"表达不满的正确方式——XYZ表达法","l":"TF1-2","c":"聚宝盆","g":1,"p":1},{"i":8897,"t":"运用“XYZ表达法”使你的意见问题平稳表达","l":"TF2-3","c":"淡然","g":1,"p":1},{"i":8661,"t":"XYZ沟通法","l":"TF1-2","c":"秦小旺","g":0,"p":1},{"i":8575,"t":"XYZ 高效沟通法","l":"TF1-2","c":"秦小旺","g":0,"p":1},{"i":7793,"t":"XYZ高效沟通法","l":"TF1-2","c":"秦小旺","g":0,"p":1},{"i":7540,"t":"XYZ表达抱怨法","l":"TF2-1","c":"Lotus","g":1,"p":1},{"i":6996,"t":"如何表达抱怨1","l":"TF1-1","c":"熊书容","g":1,"p":1},{"i":6958,"t":"如何正确表达抱怨@","l":"TF2-2","c":"王小七","g":1,"p":1},{"i":6915,"t":"得体的抱怨二","l":"TF1-1","c":"野子","g":1,"p":1},{"i":6877,"t":"如何正确表达抱怨","l":"TF2-1","c":"王小七","g":1,"p":1},{"i":6252,"t":"XYZ表达法帮您轻松实现建设性反馈","l":"TF2-3","c":"职场姜文","g":1,"p":1},{"i":6130,"t":"用xyz法表达感受","l":"TF1-1","c":"刘犇","g":1,"p":1},{"i":6048,"t":"如何清晰表达抱怨","l":"TF2-1","c":"七月","g":1,"p":1},{"i":6013,"t":"得体表达抱怨或意见","l":"TF1-2","c":"苏武林","g":1,"p":1},{"i":5813,"t":"如何表达","l":"TF1-1","c":"方凯","g":1,"p":1},{"i":5484,"t":"如何有效表达抱怨","l":"TF1-1","c":"风清扬S","g":1,"p":1},{"i":5483,"t":"如何有效表达抱怨（郭峰）","l":"TF1-1","c":"风清扬S","g":1,"p":1},{"i":5068,"t":"如何有效阐述你的问题","l":"TF1-1","c":"十八","g":1,"p":1},{"i":5063,"t":"运用XYZ模型快速有效沟通","l":"TF1-1","c":"唐思","g":1,"p":1},{"i":4916,"t":"  如何做才能让忠言不再逆耳","l":"TF2-3","c":"宋福珍（豆豆）","g":1,"p":1},{"i":4457,"t":"有效阐述问题的XYZ模型","l":"TF1-1","c":"彭丽娟","g":1,"p":1},{"i":4219,"t":"XYZ模型减少沟通冲突","l":"TF1-2","c":"张文静（天后）","g":1,"p":1},{"i":3704,"t":"通过拆书家，学习者将了解如何使用有效的问题阐述模","l":"TF1-1","c":"微粒","g":1,"p":1},{"i":2975,"t":"树安二次拆书","l":"TF1-2","c":"谦谦有理","g":1,"p":1},{"i":2897,"t":"小量成功策略减轻压力","l":"TF3-1","c":"norman","g":1,"p":1},{"i":2246,"t":"得体表达问题","l":"TF2-1","c":"封超","g":1,"p":1},{"i":1555,"t":"如何结构化表达自己的意见和不满，改变对方的行为？","l":"TF1-2","c":"丁华平","g":1,"p":1},{"i":1053,"t":"· 这样抱怨就对了","l":"TF2-3","c":"八爪鱼","g":1,"p":1}],"ms":[{"id":19613,"topic":"从行为到感受：三步构建无冲突沟通","learn_goal":"","remark":"适合初入管理岗，想提升沟通效率的管理者。","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"小玲(Mia)","city":"东莞"},"club":{"name":"东莞乐享分舵","city":"东莞"},"prologue":"\u003cp>大家好，我是小玲，微信名Mia！今天是2025年的收官之夜，谢谢大家陪我一起过级。祝大家把所有不开心留在旧年，新的一年有钱有闲，万事顺遂！先用三个标签来介绍一下我自己:\u003c/p>\u003cp> 1. 跨界玩家（设计转数据）：以前是做室内软装设计和产品色彩研发的工作，现在转行在外企做数据分析，在理性和感性之间切换得不亦乐乎；\u003c/p>\u003cp>2. 不设限的终身成长玩家：我一直觉得，人生就应该不断尝试新事物、坚持学习、勇敢挑战未知，才不算辜负时光；\u003c/p>\u003cp>3. 用成长陪伴成长的妈妈：很赞同一句话“先让自己变好，才有机会让孩子更好”，所以我也希望能用自己的成长脚步，给孩子做好榜样、做好引导。\u003c/p>\u003cp>分组指令:因为今天有互动分享环节，所以在开始我的分享之前，为了大家更好的互动，咱们先来分一下组,今天人不多，那我们就直接分成一个组吧。\u003c/p>\u003cp>图书介绍:\u003c/p>\u003cp>我今天分享的主题是《从行为到感受：三步构建无冲突沟通》，来自于书籍《管理技能开发（第8版）》，是大卫·A.惠顿和金·S.卡梅伦两位管理学的权威著作的，这本书主要讲十大核心管理技能，搭配“X-Y-Z沟通模型”等实操工具，用“评估—练习—应用”模式帮助我们快速解决职场沟通、团队管理等问题，这是一本能让理论直接落地的书。\u003c/p>\u003cp>引导语:大家回想一下在平时的工作中，是不是也常遇到沟通说不清楚、团队难推进的情况？今天我们就来学习这本书介绍的其中一个简单有效的反馈模型，它能帮我们把问题说清楚，同时又让对方更容易接受。\u003c/p>","ratings_count":3,"texts":[{"id":24018,"quote":"\u003cp>接下来请大家花1-2分钟的时间阅读下原文，请阅读完的小伙伴在聊天区扣个1或者是开麦示意我一下，谢谢。\u003c/p>\u003cp>选自《管理技能开发（第8版）》429~430页\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉Z。”\u003c/p>\u003cp>第一,描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二,列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三,描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>好的，时间到，那接下来请大家跟随我一起来解读这个片段:\u003c/p>\u003cp>Why:大家不妨回想一下在我们日常生活、工作当中,当我们遇到问题跟别人进行沟通或者发生冲突的时候,是不是会经常出现这样的场景对话:“谁知道你怎么想的,我不管了你爱怎么样就怎么样.或者是“都怪你,要不是你,也不会变成这样.”等诸如此类满腹抱怨的对话,其实这样做不仅不能解决问题,反而会让双方关系变得更加的紧张甚至是把局面弄得很僵,严重点的话还可能会发展到一发不可收拾的地步（坏处）。那如果在即将要发生语言冲突、矛盾的时候，运用XYZ表达法去沟通，不仅能避免矛盾，还可以让沟通更有效，更快达到自己的目的（好处））\u003c/p>\u003cp>说到这里大家可能会产生一个疑问，那就是什么是XYZ表达法?它具体该怎么做呢?接下来我们就一起来揭晓看看吧~首先~(what)\u003c/p>\u003cp>ⅩYZ表达法是通过说出具体的事件、所导致的后果、给我们所造成的感受这三步清晰简洁地表达出我们的想法,并让对方清楚明白的了解我们的感受和需求。\u003c/p>\u003cp>它的具体操作步骤如下:(How)\u003c/p>\u003cp>1. 说行为 (X)：只描述具体、客观的行为，不带任何评价。\u003c/p>\u003cp>例如：&quot;当你在会议上打断我发言时...&quot;\u003c/p>\u003cp>2. 说影响 (Y)：说明这个行为带来的具体、可见的后果。\u003c/p>\u003cp>例如：&quot;...导致我没能完整表达观点，大家也没听全我的方案...&quot;\u003c/p>\u003cp>3. 说感受 (Z)：表达你因此产生的真实感受。\u003c/p>\u003cp>例如：&quot;...这让我感到很挫败和不被尊重。\u003c/p>\u003cp> Where：这个方法适用于跟家人、朋友、同事在某些问题上发生争执的时候根据以事实为基础的方面展开有效的沟通,运用此方法将会减少因模糊事实与评价性反馈所带来的激烈情绪。\u003c/p>\u003cp>不适用于：无理取闹、找茬、不讲理、不跟人沟通的情况。\u003c/p>\u003cp>下面我再举一个我自己的例子来帮助大家学习理解。\u003c/p>\u003cp>起因:\u003c/p>\u003cp> 上个月我跟同事小张一块负责一个项目，按理来说项目是两个人负责的,方案要改的话，是需要两个人提前沟通的，这样大家都心理有数，也不容易出现问题。可他总喜欢直接在项目群里提修改建议，不商量、也不打招呼。\u003c/p>\u003cp>刚开始项目不赶的时候我就算了，后面项目正赶进度呢，他又在群里突然说方案有3处要改，还@了领导和其他同事。结果好几个人私聊问我“怎么突然要改啊”“后续工作要不要调整”，我压根不知道这事儿，当场就懵了，手忙脚乱翻资料应付。后面我找他说这事儿，越说越气，后面没忍住语气有点冲：“你怎么总不跟我商量就发群里啊？”他还觉得委屈，说自己是提合理建议，俩人越吵越凶，后面领导来了，周围的同事也都看着，就特别的尴尬。\u003c/p>\u003cp> 之后几天，我跟小张在公司碰见跟没看见似的，谁也不搭理谁。项目上的配合也断了，他不跟我同步进展，我也不想主动找他，导致项目推进慢了不少。其实当时我心里也挺不是滋味的，懊恼当时没好好说话，既影响了工作，又觉得为了工作上的事情跟同事闹成这样没必要，就觉得是不是自己太过于较真了。\u003c/p>\u003cp>在学了XYZ表达法以后我反思了一下:\u003c/p>\u003cp>要是当时我用XYZ表达法跟他说，情况肯定不一样，比如说：“小张，咱们聊两句吧。就是最近几次你都是直接在项目群里提方案修改建议，没提前跟我沟通（X 行为）。其他同事看到后都来问我怎么回事，我没准备好，又得临时核对，不仅打乱了我的工作节奏，还让我有点措手不及（Y 影响）。说实话，这样我感觉有点不被尊重，然后也挺担心咱们的后续合作（Z 感受）。”先说了他的行为然后说了影响，再说感受；换位思考下，如果是我，别人这样跟我沟通，我也更能接受，也能明白其中的顾虑，不会跟之前一样让人觉得是在指责。\u003c/p>\u003cp>小张也会跟我解释没提前沟通的原因，之后再提修改建议时，会先私下跟我沟通，这样既解决了问题，又没伤和气，也不影响后续的合作，项目推进也不会受影响。\u003c/p>","interaction":"\u003cp>A1:我相信，在坐的每一位都或多或少有过类似的经历：想给别人提意见，结果话一出口就变了味；或者被别人的反馈刺到，心里很不舒服。\u003c/p>\u003cp> 现在，我想邀请大家花3-5分钟时间，一起分享一个你印象最深的沟通场景。可以是一次成功的沟通，也可以是一次失败的争吵。可以说说当时发生了什么，你是怎么沟通的，以及如果现在用我们刚学的XYZ模型，你会怎么做。\u003c/p>\u003cp> 时间到了，看到大家都在很热情的互相分享，现在我们请每个小组派一个代表来分享一下自己在过往处理人际冲突时是怎样阐述问题的。\u003c/p>\u003cp>学习者案例记录（木门）：我分享一个今天晚上发生的事情，今天我在上班，昨晚上面的领导就跟我说要协助一个任务，说:“明天你们协助对口协作单位，然后他们说让我们提供中午的15份午餐，这个午餐到时提供给他们”，我说没问题，我中午就打了15个饭给他们。但是到了晚上六点多的时候，突然间那个领导又打电话来说:“协作单位说你们的15个快餐怎么还没到，什么时候到?”我说啥玩意，我说你不是说只买中午的吗？怎么晚上还要买？他说我说了啊，然后后来他就在那里一直说，后面就~反正他大我小，他说有那我也不想跟他争了，后来我就想赶紧想办法解决吧，就先在群里面跟他说一下，说塞车要等一下，然后就赶紧找人自己掏腰包打了15份饭给他们。当时我就觉得特别憋屈，就跟领导各执一词，然后最后不得不自己那个牙齿咬碎往里吞。那如果用这个方法，我接收到的信息是什么，造成了什么样的后果，现在我的感受是怎么样？我的感受就是感觉很委屈，因为我没有接收到明确的信息，不管是我理解不到，还是领导当时的指令没说清楚，最后的结果就是我现在要赶紧去处理，但是觉得有点委屈。我觉得这样子，说完之后会比我跟他各执一词，然后我说好了，现在不要争这个了，我赶紧去处理，可能会更有余地一点。\u003c/p>\u003cp>学习者案例记录（楚瑜）：事情是我跟我青春期的孩子:前阵子她刚刚考完试，结果不是很理想，她那会心里正难受的时候，我就追着她问:怎么回事怎么考得那么差？然后她就跟我怼起来，怼起来以后我们俩就会很难受，彼此情绪都起来了，然后她啪把门一甩，我就更气了，然后冲突就升级了，把她骂了一顿，后面就吵了一架，导致母女关系变僵。就特别的难受，原本只是一件很小的一件事情，结果因为沟通的方法不对，把它演变成了一种冲突，从而导致双方关系恶化。\u003c/p>\u003cp>A2:作为成年人，学习的核心是解决现实问题——而拆书法之所以高效，关键就在于能落地，现在，邀请在场所有伙伴亲身实践，试着写下自己的A2计划！\u003c/p>\u003cp>学习了XYZ表达法后，你打算如何把它用在实际场景中？怎样让计划不流于形式、真正落地？请大家把实施细节写得越具体越好：明确具体时间、目标、触发场景，具体怎么做?你的行动步骤是什么?\u003c/p>\u003cp>现在，就请大家动笔，把方法变成行动；由于时间关系，我就不现场找小伙伴分享了，结束之后可以发到我们的群里:\u003c/p>\u003cp>学习者分享:\u003c/p>\u003cp>关于家庭成员事务分工\u003c/p>\u003cp>1,、时间：2023年1月1日家庭会议后正式执行\u003c/p>\u003cp>2、目标：家庭事务分工明确，减少推诿，提升家庭协作效率\u003c/p>\u003cp>3、家庭成员:我和队友、还有父母\u003c/p>\u003cp>4、具体行动步骤:\u003c/p>\u003cp>每周日晚20:00召开家庭会议，按X（行为）+Y（影响）+Z（感受）框架梳理下周家庭事务:\u003c/p>\u003cp>比如队友负责每天下班回家后主动倒垃圾、整理玄（X），能让家里保持整洁，减轻家人家务负担（Y），我们都会感到轻松且温暖（Z）\u003c/p>\u003cp>如果遇到加班或者其他特殊情况，也用XYZ表达法进行沟通，比如：如果你因为加班20:00前无法到家（X），会导致负责的家务无人承接（Y），家人会感到手忙脚乱（Z），需要提前微信告知并协调替代人。\u003c/p>\u003cp>5、每周六晚19:00，家庭共同复盘XYZ表述执行效果，调整不合理的行为、影响或感受描述\u003c/p>\u003cp>6、制作家庭事务XYZ分工表，贴于冰箱门作为可视化提醒\u003c/p>\u003cp>结束语:相信每一次思维的碰撞，都让知识多了一份落地的可能。\u003c/p>\u003cp>那到此，今天的拆书分享到这里就圆满结束了！感谢大家全程的投入与真诚交流，愿大家带着今天的收获，把方法变成行动，在解决实际问题中持续成长，咱们下次再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1767490154000,"updated_at":1767516212000,"ria":true},{"id":16660,"topic":"何为XYZ法以及如何采用XYZ法来有效阐述问题","learn_goal":"","remark":"解决人际冲突的关键在于保持整个过程集中于共同的问题和共同的解决方案来鼓励协作，如何可以准确的阐述问题是迈向成功的第一步","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"万娟","city":"太原市"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"\u003cp>【分组】1分钟\u003c/p>\u003cp>大家好，我是李万娟。木子李，前程万里的万，美人娟娟的娟。这是一个再普通不过的名字，却寄托着长辈们对我满满的爱意与美好期待。我是今天的领拆人。\u003c/p>\u003cp>我给大家准备了好吃的无糖糖果，让我们一起在甜甜蜜蜜中开始今天的学习之旅。糖果放在这个口袋里，请大家每人随意抓一颗，糖果一共有两种口味，抽到橘子口味的伙伴就是橘子组的成员，抽到奶油口味的伙伴就是奶油组的成员，我们开始吧！\u003c/p>\u003cp>好，大家都拿到糖果了，在享受美味的时候我们来调整一下座位，请橘子组的伙伴坐在一起、奶油组的伙伴坐在一起，这样方便我们后面的分组讨论。\u003c/p>\u003cp>【图书介绍】1分钟\u003c/p>\u003cp>今天我们要拆的书目是《管理技能开发》，这本书的特别之处在于它提供了大量的实践练习、案例以及最新的方法，帮我们架起了学习管理技能与应用管理技能之间的桥梁，具有特别强的实操性。书中着重讲解了开发自我意识、个人压力管理、创造性和分析性地解决问题、通过支持性沟通建立关系等等十个方面的管理技能，特别适合需要提升管理技能的相关人士反复学习，不断体会，从而熟练应用于日常的工作当中。我发现其中的一些技能对于提升宝爸宝妈的养育技能也特别好用。我们可以通本学习，也可以针对目前我们遇到的问题找到相应的技能来学习。今天我选择了---有效阐述问题的XYZ表达法，这是一个有效阐述问题的模型。这个部分的内容来源于书中---冲突管理的章节，解决问题首要条件是怎样通过保持整个过程集中于共同的问题和共同的解决方案来鼓励协作。那么第一步如何准确的阐述问题就特别关键，现在就让我们一起来阅读一下今天的拆页。\u003c/p>","ratings_count":1,"texts":[{"id":20773,"quote":"\u003cp>我们用1-2分钟的时间看一下原文片段，看完后请抬头示意我一下。\u003c/p>","explains":"\u003cp>【I重述知识点】5分钟\u003c/p>\u003cp>这个片段介绍了何为XYZ法以及如何采用XYZ法来有效阐述问题。\u003c/p>\u003cp>当我们阐述一个问题时并不止是为了指出问题，更重要的是想要解决相应的问题。当我们泛泛的谈感受、谈过程、谈结果的时候，沟通往往是无效的，甚至还可能引起一些误会与负面对抗的情绪。\u003c/p>\u003cp>如果采用XYZ法，用“行为+结果+感受”的表述模式就可以通过阐述来达到解决问题的效果。\u003c/p>\u003cp>X部分：描述引起结果的他人的具体行为；\u003c/p>\u003cp>Y部分：详细列举X部分行为对与自己造成了怎样的影响，引发了什么问题；\u003c/p>\u003cp>Z部分：描述感受及由此对自己形成了怎样的干扰。\u003c/p>\u003cp>如何完成一次有效XYZ阐述，主要要完成以下三个部分的内容：\u003c/p>\u003cp>第一：精准描述他人的具体行为，一句话、一个眼神、一个动作，越具体越客观越有效；\u003c/p>\u003cp>第二：直述结果与引发的问题，这一部分要详细、要是对方可以看到或者感受到的后果，比如错过了演出、情绪失控等等；\u003c/p>\u003cp>第三：谈感受，谈影响，这一部分一定不能抱怨，要通过对自己情绪和干扰的描述来引起对方的情感共鸣，以触动对方愿意配合解决问题或做出改变。\u003c/p>\u003cp>在使用时，三个部分的先后顺序可以根据表达需要进行灵活调整。\u003c/p>\u003cp>采用XYZ问题描述法，需要满足以下几个条件：\u003c/p>\u003cp>1、 谈话对象具有改变的能力与主动权；\u003c/p>\u003cp>2、 能够梳理出符合逻辑的因果关系；\u003c/p>\u003cp>3、 谈话双方情绪稳定，出于理性的状态。\u003c/p>\u003cp>其实在生活中，我们也是需要这个技能来解决和伴侣、孩子的冲突的，最近我的日程特别紧张，一方面要带着孩子参加训练、比赛，一方面要工作、学习，经常在几个城市之间穿梭，一些写作的内容通常会放在晚上来完成。这个时候儿子常常会跑来要求我陪他玩儿，开始时我比较有耐心，会说：“宝贝，妈妈正在完成作业，你自己先玩一会儿，妈妈完成就来陪你”，不一会儿，儿子又来了，被打扰的次数一多难免烦躁，口吻就变的严厉、急躁起来，儿子很委屈，我也不痛快，事后免不了后悔。\u003c/p>\u003cp>对照XYZ模型，我在阐述问题时只是说了自己的状态和对儿子的要求，小朋友并没有完全领会，他的打扰对于我造成了怎样的影响和可能会导致的结果，只是希望妈妈能早些陪伴他，被妈妈凶过后难免委屈，下一次还是会重新上演这样的情景。\u003c/p>","interaction":"\u003cp>【A1】激活经验 5分钟\u003c/p>\u003cp>在我们日常的工作、生活中难免遇到类似的人际冲突，通过阅读今天的拆页，希望大家再次遇到问题时，可以更加清晰、准确的描述问题从而减少误会和对抗情绪，可以与对方更好的协作来解决问题。那么，现在请大家想想自己有没有经历过类似情境、有没有过相关的经验，请在小组内分享。\u003c/p>\u003cp>我们有3分钟的分享时间，请大家开始吧！\u003c/p>\u003cp>3分钟的时间到了，看到大家还在热烈的讨论，都有些不忍心打断。现在我们请每个小组排一个代表来分享一下自己在过往处理人际冲突时是怎样阐述问题的，好吗？\u003c/p>\u003cp>-接下来我们有请现场的伙伴来分享一下自己的相关经验。\u003c/p>\u003cp> -非常感谢伙伴们的分享。\u003c/p>\u003cp>【A2催化应用】1分钟\u003c/p>\u003cp>做为成年人的我们，学习更多的是为了解决现实中遇到的问题，拆书法作为特别有效的一种读书方法，还有一个步骤起到了至关重要的作用，那就是我们的A2便签。现在请在场的所有伙伴一起来感受一下，来试着写一写。在学习过XYZ表述法后，您计划如何去应用它。那么如何才可以让这个计划有很好的落地呢，我们需要对于如何去实施写的越详细越好，其中必不可少的内容有在什么时间、遇到什么样的情况、会采取具体那几个步骤来完成，如果能够写下更多的对话的细节就更棒了。现在就请大家开始吧！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1695257424000,"updated_at":1696839112000,"ria":true},{"id":15882,"topic":"XYZ模型-一分钟学会表达不满情绪","learn_goal":"","remark":"很多人认为日常生活中要尽量压制自己的不满，要能“吃得眼前亏”，因为“忍一时风平浪静”。其实，长期持有这种想法的人，要么忍气吞声自己难受，要么被周围的人视为是没有边界的老好人，甚至忍到最后一刻，表达冲突的时候，有可能会玉石俱焚。\n其实，恰当的表达情绪不仅有利于身心健康，还可以提高工作效率改善人际关系。合理的表达不满对亲密关系也是有促进作用的。\n那么，日常生活中，该如何合理表达不满情绪呢？希望本次分享带给大家启发。\n","level":"TF2-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"Shirleyxueli","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>各位小伙伴你们好，我是今天的拆书家薛丽，首先用三个标签来介绍下我自己，我是一个互联网行业打工人，目前在一家世界500强公司的跨境电商部门做运营，第二个标签是一位宝妈，第三个标签是一个新手一级拆书家。今天我要拆书的片段来源于《管理技能开发》这本书。\u003c/p>\u003cp>F:这本书分十个章节介绍了管理成功的十大关键技能，它们分别是：言语沟通（包括倾听），时间和压力管理，个体决策管理，发现、界定和解决问题，激励和影响他人，授权，目标设置和阐明愿景，自我意识，团队建设，冲突管理。 在每章中，作者都是提供了一个五步骤的学习模型，帮助读者进行管理/领导技能的评估、学习、分析、练习与应用。\u003c/p>\u003cp>A:这本书的作者是来自于康奈尔大学的大卫惠顿博士和耶鲁大学的金卡梅伦博士。此书的豆瓣评分也高达9.4分。相比其他的管理主题的书籍，本书提供了大量的实践练习，案例和致用的方法，相对于纯理论的探讨，它更多的在学习管理技能和运用这些技能之间搭建了桥梁，学完即可上手练习。\u003c/p>\u003cp>B:如果你像我一样，是一名新晋管理者，不懂怎么给下属分配工作；新建的团队不知如何打造部门凝聚力；有一个不服你管的下属不知如何沟通；抑或者你是一名工商管理专业的学生，在学习和研究适用于各类企业的有效管理方法，那么这本书非常适合你去阅读。\u003c/p>\u003cp>B+：今天分享的片段是与沟通有关的，这个片段向大家介绍了一个表达不满情绪的公式，听完我的分享之后，大家可以在遇到不满的情绪时，用正确的方式进行沟通使得问题得到解决。\u003c/p>\u003cp>首先我给大家一分钟的时间，阅读手中的拆页。\u003c/p>","ratings_count":1,"texts":[{"id":19964,"quote":"\u003cp>拆页内容：\u003c/p>\u003cp>R XYZ表达法 片段来源 《管理技能开发》\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一、描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二、列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三、描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个散布模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>\u003cstrong>逐字稿：\u003c/strong>\u003c/p>\u003cp>好的，我看小伙伴都已经陆续读完了。\u003c/p>\u003cp>\u003cstrong>What:\u003c/strong> 这个拆页给了我们一个表达负面情绪的公式，即XYZ表达法。\u003c/p>\u003cp>X指的是具体的行为，Y即这些行为所带来的结果，Z表达这些结果是如何让你产生负面情绪的。我们在表达不满时，按照这个顺序来组织语言，可以使问题得到解决。\u003c/p>\u003cp>\u003cstrong>Why:\u003c/strong>为什么推荐XYZ表达法呢？按照XYZ的顺序，我们先列出具体的行为X，这样使得对方清楚做了什么才导致现在的状况，相对于直接给出评价或者感受，会显得更加清楚，不至于一头雾水。\u003cbr>其次我们简单明了地列出这些行为所带来的结果，正是由于这些结果，我们才有相应情绪，以此可以刺激对方做出行为的改变。\u003cbr>最后针对结果表达我们的感受Z，让对方明白这些感受带来了什么影响。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>如何使用XYZ表达法？\u003c/p>\u003cp>在表达不满时，我们可以按照这样的模板描述，\u003cbr>你好，我现在有个事情要和你商量/有个问题要和你探讨\u003cbr>你做了如下X，\u003cstrong>（描述行为X）\u003c/strong>\u003cbr>这些X分别导致了如下后果Y\u003cstrong>（描述后果Y）\u003c/strong>\u003cbr>\u003cstrong>（描述感受Z）\u003c/strong>针对这些Y，我出现了这些感受Z，感受Z对我造成了干扰。希望能与你商量后得到解决。\u003c/p>\u003cp>\u003cstrong>Where:\u003c/strong> 在对别人有不满或者其他负面情绪尝试沟通解决时\u003cbr>不适用于日常工作汇报或者简短发言，此时我们应该先直接表明观点再进行阐述。\u003c/p>\u003cp>下面我举个职场上很常见的例子大家一起来看看XYZ的实际运用：\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>一个风和日丽的中午，我像平时一样结束了一上午的工作，美美的吃了一顿午餐后铺开工位边的简易小床，找了个舒服的姿势在靠窗的位置躺了下来，阳光透过窗户打在身上，气温刚刚好，再舒服不过了，可正当我迷迷糊糊要进入梦乡时，一阵“叮叮叮”的噪音打断了这份宁静，仔细一听，是隔壁工位的老余吃饭时钢勺碰到玻璃碗发出的声音，这个时间点大家都午休了，办公室的安静更显出了这个声音的刺耳，我越想忽略却愈发的烦躁不安……\u003c/p>\u003cp>我忍无可忍，烦躁不安的走到老余身边，质问到：你怎么趁大家都午睡的时间吃饭呀，声音好大，吵的人烦死了。\u003c/p>\u003cp>忙碌了一个早上水都没顾得上喝的老余，听到我这劈头盖脸的指责，也是火冒三丈，跟我理论起来“我戴着耳机吃我的饭，管你什么事情，谁规定午休时间只能睡觉了。。。”\u003c/p>\u003cp>最后的后果可想而知，你们吵了起来，整个办公室的其他小伙伴也遭殃了，大家都没办法好好休息，\u003c/p>\u003cp>问题不仅没有解决，反而更加严重。\u003c/p>\u003cp>如果用XYZ表达法，我可以这样做，\u003c/p>\u003cp>\u003cstrong>（描述行为X）\u003c/strong>：你好呀老余，都一点多了才吃午饭呢，早上忙坏了吧。\u003c/p>\u003cp>\u003cstrong>（描述后果Y）\u003c/strong>: 这个点大家都睡觉了，办公室特别安静，所以你吃饭的声音显得很大。\u003c/p>\u003cp>\u003cstrong>（描述感受Z）\u003c/strong>：我离你很近，这个声音吵醒了我，并且很难再入睡了。我希望跟你商量下你方便去休息区用餐吗？\u003c/p>\u003cp>我相信这样短短五分钟的沟通完毕之后呢，老余会友好的跟你商量解决办法，要么去休息区吃饭，要么换个不那么大声音的木质餐具，很快美好的午睡时间又可以开始了，并且不会吵到任何第三个人。。。\u003c/p>\u003cp>由此可见，同样的事情，换个沟通方式结果会大相径庭！\u003c/p>\u003cp>\u003cstrong>异议\u003c/strong>：\u003c/p>\u003cp>异议一：说到这里，我知道很多小伙伴会说：“一般遇到这种事请，我都是忍一忍就过去了，中国人有句古话，叫做忍一时风平浪静，退一步海阔天空，何苦要这么大动周折找不痛快呢。”\u003c/p>\u003cp>大家想一想，如果一味的对自己的不满情绪保持沉默和忍受的态度，看似是大事化小，小事化了，其实你的不满诉求真正得到解决了吗？它们只是暂时的积攒起来，因为没有合理的宣泄掉，只会越攒越多，等到情绪的小宇宙爆发的那一天，所带来的后果将是更加可怕甚至会伤害到自己和别人。\u003c/p>\u003cp>异议二：还有的小伙伴会想，这样多憋屈呀，还不如大吵一架来的痛快。\u003c/p>\u003cp>其实我们所有的沟通都是为了使问题得到解决，像我前面举的午睡的例子一样，一吐为快的抱怨固然爽，但是最终不但问题得不到解决，反而会使冲突激化，惹来更多的麻烦～\u003c/p>\u003cp>所以，我们要学习如何让这些不满情绪合理的宣泄掉，学会表达不满的正确方式，将每一个不满的小情绪用XYZ表达法各个击破。\u003c/p>","interaction":"\u003cp>咱们日常生活中发生不满情绪的场景其实非常常见：\u003c/p>\u003cp>比如节假日总是躺沙发翻手机的另一半，公交车上手机声音特别大的陌生人，楼上一大早就蹦蹦跳跳影响睡眠的邻居，总是临时拉你开会的上级领导，遇到项目变化从不主动同步的客户。。。。\u003c/p>\u003cp>下面我将现场学习的小伙伴们随机分成两组，请想一个未来一周内会产生抱怨的具体情境，分享给同组的伙伴，注意：只需要想出不满的具体场景就可以了，大家可以按照在纸上写一下人物和不满的具体事情。讨论时间是每组2分钟。之后我将邀请小伙伴进行分享。现在开始！\u003c/p>\u003cp>拆苏家：好的，2分钟时间到了，下面请一位小伙伴来分享下刚刚想到的场景，我看很多小伙伴都示意已经完成，我们请兴霞老师来分享下\u003c/p>\u003cp>兴霞：好的，我刚刚想到的是我老公的不满，他总是下班后躺在沙发上玩手机，并且声音开的特别大，影响到我的学习了。\u003c/p>\u003cp>拆书家：刚才小伙伴兴霞老师做了很棒的分享。她分享的是家庭场景下与老公之前的不满场景。那么现在请大家运用今天所学的“xyz”模型，设想一下遇到你刚才记录下的场景时，你会怎样利用XYZ表达法表达抱怨？给大家2分钟的时间，稍后我们请一位小伙伴分享一下。\u003c/p>\u003cp>好的，时间到，我们请一位小伙伴分享一下。还是请兴霞老师吧，假如应用XYZ表达法，你会怎么跟你老公沟通不满呢？\u003c/p>\u003cp>学习者：我会告诉他躺在沙发这一行为会对他身体不好，并且声音特别大影响到我了，会让我觉得很烦躁，这样是不对的，希望看他能有什么办法解决下\u003c/p>\u003cp>拆书家：好的，兴霞老师，你刚刚分享中XYZ三个步骤都有用到，但是我建议你在跟他沟通时不要带着情绪，要更客观的去表达行为动作及带来的客观后果，否则你的情绪可能会使对方也产生抵触，你可以着眼点不要在自己感受身上，甚至带着对对方的理解再试着用XYZ的沟通步骤跟他聊聊，看看结果跟之前有什么不同。\u003c/p>\u003cp>好了，谢谢大家的倾听，今天的分享到这里啦。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684899319000,"updated_at":1685245009000,"ria":true},{"id":12817,"topic":"建立最佳的SMART目标","learn_goal":"","remark":"你是否碰到过以下几种情况：当公司制定了年度KPI绩效考核目标之后，员工的积极性不仅没有提高，反而更加并消极怠工了。计划今年要考取的证书，执行起来却一拖再拖，不知道从哪里开始。那么如何科学的制定切实可行的目标才能持续性的将任务落实下来，我们可以采用建立最佳的SMART目标原则。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"子小木","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003ch2>\u003cstrong>【自我介绍】\u003c/strong>\u003c/h2>\u003cp>大家好，我是胡蓉，我有三个标签：高级家庭教育指导师，绘本讲师，新晋管理层小白。\u003c/p>\u003cp>●作为新时代的父母，我深知育儿道阻且长，通过不断学习，我得到了家庭教育指导师的称号，志在帮助自己和正在迷惘期的家长们走出育儿困境。\u003c/p>\u003cp>●图画和文字是人类文明得以传承的重要媒介，也是父母与孩子沟通的桥梁。在绘本中，文字与图画的交织让我们感受到更加璀璨的世界，而我和我的孩子更愿意将阅读的美好传播开来。通过阅读，我们筛选图书，捐赠图书，同时提高阅读技能，考取绘本讲师资格。\u003c/p>\u003cp>●在工作中，我是新晋的收费站副站长，听取前辈的故事，承续传统，开拓创新，在学习和实践中打造扎实肯干、勇敢创新的工作风格，需要更多专业的知识技能做支撑，而为更好的帮助自己建立行之有效的工作与生活方式，也就是我加入拆书帮的述求。\u003c/p>\u003cp>【介绍拆书帮】\u003c/p>\u003cp>“拆书”为何物，简而言之便是成人学习方法论，强调学习者为中心，通过拆解方法步骤，达到提升能力、解决问题的目标，将学习的知识融汇贯通至切实可行的操作中去，即学以致用。\u003c/p>\u003cp>“拆书”可以分为两种拆书法，即个人学习和组织学习。\u003c/p>\u003cp>▶个人学习法是运用RIA便签法，通过R即阅读原文，I用自己的理解将原文片段进行梳理再重述出来，帮助完成A便签A1部分对自己过去的经历过的事情进行回忆和复述，将好的方面或者是需要改进的方面进行反思；然后A2部分通过设想未来片段中适用边界的场景，将行动步骤进行应用的方法，即“拆为己用”。\u003c/p>\u003cp>▶组织学习法就是由一名拆书家，将书本内容应用RIA的拆解方法 ，将拆解的某个原文片段进行加工并呈现于现场，引导学习者阅读，帮助学习者理解并联系自身；再由拆书家催化促动，促进学习者反思经验、规范行动和反思演练的学习方法。\u003c/p>\u003cp>▶拆书帮”是基于以上学习方法而组建的学习爱好者社群，拆书帮在全国各地都设有分舵，是一种非营利性的“青年自组织”，其使命是“释放学习促进者的能量”，帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>▶欢迎大家来到拆书帮麓山分舵拆书现场，麓山分舵于2017年7月10日正式成立，至今分舵已有超800 位爱好者、82位会员、14位三级拆书家，分舵秉承“同好、赋能、交付”的价值理念，以“致力于培养拆书家，释放拆书家的能量，相互陪伴，助人达己”为使命，希望帮助更多人“将知识拆解成自己的能力”，提高工作学习效率，学以致用。\u003c/p>\u003ch2>\u003c/h2>","ratings_count":1,"texts":[{"id":16771,"quote":"\u003cp>明确所要实现的目标，最佳的目标可以用简写为SMART的五个著名属性来描述：\u003c/p>\u003cp>S=具体（不可过于笼统）\u003c/p>\u003cp>M=可度量（不可过于主观）\u003c/p>\u003cp>A=保持一致（不要偏离目标）\u003c/p>\u003cp>R=现实（不要异想天开）\u003c/p>\u003cp>T=时间约束（不能是无限制的）\u003c/p>","explains":"\u003cp>【Why】：是否碰到过制定了年度目标之后，并没有提升员工的积极性，接到KPI的考核目标后，员工反而更加消极怠工了的情况？是否遇到过制定了自己的计划之后，实施起来确步步维艰，不知从何下手？如何科学的制定切实可行的目标才能持续性的激发我们主观能动性，我们可以采用建立最佳的SMART目标方法。\u003c/p>\u003cp>【What】：SMART原则(S=Specific、M=Measurable、A=Attainable、R=Relevant、T=Time-bound)是为了制定公司及个人的明确目标，一方面他利于\u003ca href=\"https://baike.so.com/doc/6467004-6680699.html\">员工更加高效地\u003ca href=\"https://baike.so.com/doc/133744-141299.html\">工作，更是为了\u003ca href=\"https://baike.so.com/doc/2961885-3124696.html\">管理者将来对员工实施\u003ca href=\"https://baike.so.com/doc/5368761-5604590.html\">绩效考核提供了考核目标和考核标准，使考核更加科学化、规范化，更能保证考核的\u003ca href=\"https://baike.so.com/doc/10036603-10541046.html\">公正、\u003ca href=\"https://baike.so.com/doc/6966623-7189278.html\">公开与公平；另一方面，也帮助个人细化总体的目标任务，具化分项目标，提高完成效率、完成度，帮助总体任务的实现。\u003c/p>\u003cp>【How】：\u003c/p>\u003cp>下面以企业设置绩效考核目标为例：\u003c/p>\u003cp>S代表具体(Specific)，指绩效考核要有量化工作指标，不能笼统。\u003c/p>\u003cp>例如：我们会要求我们的服务人员，一定要采用文明优质服务。什么是文明优质服务？很模糊。要具体点：我们需要用文明用语、得体的手势，微笑服务，给我们的顾客提供良好的服务。\u003c/p>\u003cp>M代表可度量(Measurable)，验证这些绩效指标的数据或者信息是可以获得的。\u003c/p>\u003cp>A=保持一致(Attainable)，设立的绩效指标是可以在付出努力的情况下能实现，避免设立过高或过低的目标；\u003c/p>\u003cp>R代表现实(Relevant)，设立的绩效指标是与本职工作相关联的；\u003c/p>\u003cp>T代表有时限(Time-bound)，设立的绩效指标需要注明完成绩效指标的期限。\u003c/p>\u003cp>【Where】：SMART目标设立法不仅适用于企业的绩效考核目标确立，也适用于个人的工作生活目标确立。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>\u003cstrong>●事件：\u003c/strong>今年的10月初，我们接到了年度工作检查的通知，在组织完人员之后，就人员分工进行了讨论。在和组长就这次的任务进行拆分之后，做为副组长的我，并没有对人员的分工以及每日工作进度安排进行细分，所以在整理资料时，我们发现，人员分工混乱，每人每日完成的任务成绩不明显，导致了内页资料整理工作严重滞后。\u003c/p>\u003cp>\u003cstrong>●反思：\u003c/strong>在与组长梳理好主线思路后，我应该做好后续的任务安排和人员分工工作，主要表现为以下几点：\u003c/p>\u003cp>1.没有及时的确立总目标和每日计划目标，指标模糊。\u003c/p>\u003cp>2.所有人员分工混乱或重复，组员不知道自己要做什么，负责哪一块。\u003c/p>\u003cp>3.无分日计划安排，故组员不知道怎么才算是完成了这项工作。\u003c/p>\u003cp>4.无相应的激励制度，促进整体工作的完成。\u003c/p>\u003cp>5.完成工作时间节点模糊。\u003c/p>\u003cp>【A2】：\u003c/p>\u003cp>\u003cstrong>●目标：\u003c/strong>在11月的月初计划中，用SMART目标设立法，梳理个人在今年的总目标的缺失项，帮助还未达成的目标稳步进行。\u003c/p>\u003cp>\u003cstrong>●行动：\u003c/strong>明年已经达到了初级工程师晋级中级工程师的时限要求，为了迎接10月份的考试，要做好学习目标，根据章节和课程的设置，拆分成每日的行动目标，已达成5月份之前的学习计划：\u003c/p>\u003cp>\u003cstrong>S=具体（不可过于笼统）：\u003c/strong>确立每日9:00-10:00一小时的学习时间，完成书本的新课程，并在片段时间（例如午睡前和晚上睡觉前的半个小时）刷题，巩固前一天的学习内容。\u003c/p>\u003cp>\u003cstrong>M=可度量（不可过于主观）：\u003c/strong>能记得当日学习的章节涉及的内容，并能根据章节结构画出思维导图，片段刷题能达到70分，方能达成每日的学习目标。\u003c/p>\u003cp>\u003cstrong>A=保持一致（不要偏离目标）：\u003c/strong>5月份之前完成章节学习的目标，确保能预留充足的时间进行错题分析，以及给还未能学扎实的章节进行二次巩固，从而保证10月份的考试能顺利过关。\u003c/p>\u003cp>\u003cstrong>R=现实（不要异想天开）：\u003c/strong>考取人力资源科目，提升管理技能，合理配置部门的人工结构及工作安排，不仅仅是对现在工作的技能提升，也帮助我能适应公司改革发展，企业不留闲人的前进步伐。\u003c/p>\u003cp>\u003cstrong>T=时间约束（不能是无限制的）：\u003c/strong>在2022年5月份之前完成第一轮章节的学习，综合评分达60分。\u003c/p>\u003cp>\u003cstrong>奖励机制：\u003c/strong>如果能按照每日计划进行学习，获得的中级职称当然倍感骄傲，持续性学习的坚持而得到的认可就是得到的最大奖励！\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>感谢小伙伴们的耐心倾听和指导，让我流畅的输出了《管理技能开发》一书中管理目标设立的SMART原则，确定设立阶段性目标的具体、可度量、保持一致、现实及时间约束的五个关键点，让我们的目标、计划甚至是公司的绩效考核指标能更加科学、规范并持续性进行。期待大家在今后的工作或者是生活中也能多多把今天原文中的关键点运用起来。我今天的拆书到这里就结束了，再次感谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1639798211000,"updated_at":1640258067000,"ria":true},{"id":9501,"topic":"XYZ问题陈述法","learn_goal":"运用XYZ问题陈述法，正确表达不同意见","remark":"","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"梁峻","city":"珠海"},"club":{"name":"珠海百岛分舵","city":"珠海"},"prologue":"\u003cp>【自我介绍】\r\n大家好，我是梁俊。我的三个标签是：理工男，一个小微企业的管理者，一级拆书家。我今天拆练TF2-3，和大家一起学习《管理技能开发》这本书中的一个片段。\r\n【FAB图书介绍】\r\n【F】首先呢，我先给大家介绍一下《管理技能开发》这本书。\r\n它的作者有两个，一个是大卫•A.惠顿, 一个是金•S.卡梅伦。其中，惠顿是杨百翰大学教授、康奈尔大学博士。卡梅伦是密歇根大学商学院教授、耶鲁大学博士，他发表过100多篇文章，并出版过10本专著。\r\n这本书提供了大量的实践案例以及最新的方法，在管理技能的学习与应用之间搭建了桥梁。从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n【A】和一般图书不同，这是一本清华管理学教材。能够成为教材，而且是清华大学的教材，这本书肯定有它特别牛逼的地方。\r\n【B1】在现实生活中，你是否有过这样的经历：听到别人批评或指责（注：表达不同意见的一种方式）自己时，总感觉特别刺耳、觉得别人在针对你，觉得特别反感，不由自主地想反击回去；而你批评或指正别人时，又觉得别人不愿聆听你的说话、接受你的意见，导致沟通/谈话效果极差、导致问题得不到有效解决……。你想不想在和别人沟通、谈话、要表达不同意见的时候，能够获得比较满意结果呢？今天学习的拆页就可以告诉你怎么做到精准表达、获得满意的沟通或谈话效果。\r\n【B2】包括冲突管理，这本书总共有十大管理技能。学习之后，不仅可以解决工作、生活中遇到的实际问题，还可以帮助你实现个人的全面成长。\r\n（观察点：在FAB介绍法中，能够清晰辨别出F、A、B） \r\n【学习目标】好，我们现在就开始今天的学习。希望大家在跟随我完成这次现场学习以后，在与他人沟通或谈话、要表达不同意见的时候，能运用“XYZ问题陈述法”清楚地说出（表达）自己的观点、态度和感受，让对方意识到问题所在并配合解决。在“解决问题”的同时又避免“伤了和气导致关系恶化”……。\r\n（观察点：学习目标包含学习者可被观察到/被测量到的行为或动作，现场学习者设计清晰体现了该学习目标）\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":13318,"quote":"\u003cp>\u003cem>（首先请大家用\u003c/em>\u003cem>2\u003c/em>\u003cem>分钟左右的时间，阅读一下我刚刚发给大家的原文片段，看完之后举手示意一下。）\u003c/em>\u003c/p>\u003cp>&nbsp;\u003cstrong>《管理技能开发（第\u003c/strong>\u003cstrong>8\u003c/strong>\u003cstrong>版）》\u003c/strong>\u003cstrong>P429~430\u003c/strong>\u003cstrong>拆页片段\u003c/strong>\u003c/p>\u003cp>\u003cem>（选自第7\u003c/em>\u003cem>章《冲突管理》：通过协作方式解决人际冲突/\u003c/em>\u003cem>协作型问题解决的四个阶段/\u003c/em>\u003cem>…）\u003c/em>\u003c/p>\u003cp>\u003cstrong>1-2 \u003c/strong>\u003cstrong>从行为、结果和感觉的角度简单描述问题\u003c/strong>\u003c/p>\u003cp>戈登（Gordon，2000）描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”尽管我们不提倡使用记忆公式来改善沟通技能，但是记住这个模型有助于你理解“问题陈述”中的三个重要元素。\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或泛泛的回答的倾向。一种可行的方式是，明确被违反的期望或标准。例如，下属可能没有在截止期限前完成指定的任务，你的老板对交给你的任务越俎代庖，或者会计部门总是没有及时向你提供重要会议要用的数据。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉他人其行为给你带来的问题，通常是使他们发生改变的有效刺激。在快速变化的工作环境中，人们通常对自已行为的后果感觉迟钝。他们不想引起不快，但是他们整天忙碌，被迫应付“推出产品”的最后期限，还要从他人那里接受各种负面反馈。此时提醒他们注意其行为的结果，常常能促使他们改变。\u003c/p>\u003cp>不幸的是, 不是所有问题都能被这样简单地解决。经常是，冒犯者意识到了他们的行为的消极结果，但仍然坚持不改。这时，这种方法对引发问题解决的讨论仍是有效的，因为它以无威胁的方式触及问题。很有可能，回应人的行为受到了他老板的影响，或者他所处的部门当前刚好人手不足。回应人自身可能无法改变这些限制，但是这种方法会鼓励他和你讨论这些问题，从而一起解决问题。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z），重要的是不仅要使回应人了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。它们可能使你难以集中注意力，或难以和消费者打成一片，或无法与你的老板通力合作，或者不再愿意为了赶时间而作出个人牺牲。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有所变化，而且你不要总是使用相同的词语。显然，如果工作中毎个人在讨论人与人之间的事情的时候，都从“我有问题”开始，将会十分单调。观察表7-5中“XYZ”模型中的关键元素是怎样以不同的方式被使用的。\u003c/p>\u003cp>表7-5&nbsp;&nbsp;&nbsp;&nbsp; 采用“XYZ”方法陈述问题的实例\u003c/p>\u003cp>\u003cstrong>模型：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“我有一个问题，当你做X\u003c/strong>\u003cstrong>时（行为），导致了Y\u003c/strong>\u003cstrong>的结果（结果），而使我感到Z\u003c/strong>\u003cstrong>。”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>实例：\u003c/strong>\u003c/p>\u003cp>我必须告诉你，当你在别人面前拿我的坏记性开玩笑时【行为】，我是多么难堪【感觉】。事实上，我气愤极了，甚至想要把你的缺点也摆出来作为报复【结果】。\u003c/p>\u003cp>我有一个问题，你说6点钟到这里，却7点以后才来【行为】，晚餐泡汤了。我们看演出也迟到了【结果】，我感觉受到了伤害，因为看上去我对你来说并不重要【感觉】。\u003c/p>\u003cp>雇员想让管理层知道，不事先通知就要求我们加班，我们的工作一直很辛苦【行为】，这大概就是你提到的怨言和缺乏合作的原因【结果】。无论如何，我们希望让你知道这一政策已引起许多工人的憎恨【感觉】。\u003c/p>\u003cp>……………\u003c/p>\u003cp>\u003cem>（观察点：选择图书是实用或理论类图书）&nbsp;\u003c/em>\u003c/p>\u003cp>\u003cem>（观察点：【R】所选拆页，包括How的内容；且总内容未超过2页图书内页）\u003c/em>\u003c/p>","explains":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>I&nbsp;\u003c/strong>\u003cstrong>】拆书家讲解引导\u003c/strong>\u003c/p>\u003cp>\u003cem>（好，大家都读完了。下面，我来给大家解读一下这个拆页。）\u003c/em>\u003c/p>\u003cp>【What】这个拆页，讲是一个“涉及并可能会引起人际冲突”的问题的描述方法，这就是XYZ问题陈述法。\u003cem>（通俗一点说，就是改变“表达方式”的方法。有些书中把它称为“XYZ表达法”。）\u003c/em>\u003c/p>\u003cp>【Why—不这么做的坏处】为什么要学习这个知识呢？举一个我的例子，我们家的衣柜门不是太好，自动回弹时关得不是很严，需要用手推一下。昨天我开柜拿一件衣服穿，心想等下还要将衣架放回去，就没有去推。结果太太过来看到门没关好，突然就来了一句：你总是这样，门都不关好！……我当时一听就来气了：是这样吗？我总是这样吗？我天天开柜拿衣服穿，都是你关的门？！……\u003c/p>\u003cp>很多冲突，其实都是由一些很小的事情、由于“心直口快”和表述不当而引起的。“你总是XXX、你老是XXX、你从来都XXX”。很熟悉吧，这正是多数人通常的做法。这些表述，不但“内容宽泛”，而且带有“评价性”、“攻击性”。那么，结果是什么呢？——让人听了很不舒服、难以接受，容易引发“自我防御”反应，要么反击回去、要么自生闷气消极对待……，不管怎么样，“冲突”都不可避免。很多情况，事件本身不是问题，“表述不当”才是根源所在！\u003c/p>\u003cp>【How—细化行动步骤】那么，怎样才能避免这种情况呢？——学习和运用“XYZ问题陈述法”，准确描述你的问题、巧妙说出你的想法和意见。这才是正确的做法。根据拆页，我们可以用以下五个步骤明确地告诉对方：\u003c/p>\u003cp>第1，我有一个问题（引起对方的注意和重视）\u003c/p>\u003cp>第2，这个问题，是因为你的X行为（描述对方给你带来问题的具体行为，比如说的某些话，或者做的某些事，或者忽略的某些细节……）\u003c/p>\u003cp>第3，导致了Y的结果（列出这些行为导致的详细、可见的后果，比如A同事伤心哭了，B顾客不再购买我们的产品，C项目的实验失败了……）\u003c/p>\u003cp>第4，我感到Z（描述你对问题结果的感受，比如非常生气，非常失望……）\u003c/p>\u003cp>第5，如果再这样的话，我就……（描述可能要采取的行动，让对方对他的行为导致的后果负责。希望他认真面对这个问题，并加以改善……）。\u003c/p>\u003cp>【异议预防】这“五个步骤”中，第1步是引子，主要起“引起注意和重视”作用。第234步是重点，一定要表述清楚（注意：只是表述，不带评价。要记住：我们的目的是指出并解决问题，不是吵架或贬损别人。要让对方积极配合使问题得到有效解决，相互尊重和基于事实的坦诚对话，是很有必要的）。至于第5步，要根据情况——如果只是对别人的轻微报怨或指责，前面几步已经能够把问题表述清楚并达到\u003cem>（提醒对方加以注意和改进的）\u003c/em>目的，可以“省略不说”; 但如果涉及到重大问题，需要加深印象或加强“批评”效果，以强调的方式说出来，则是可以加分的。\u003c/p>\u003cp>【Where—适用边界】“XYZ表达法”的适用范围其实是比较广的。但这一次的学习，为了让大家能够更好地理解和掌握这个知识，我们暂时把它限定在一个小的\u003cem>（“可能会引起人际冲突的不同意见的表述”）\u003c/em> 范围内\u003cem>（熟练掌握以后，大家可以试着加以拓展）\u003c/em>。通俗地说，就是我们在 “报怨、批评、指责”别人的时候……。\u003c/p>\u003cp>【例子】举个例子，我有一个侄女，她有一个2岁的小孩，吃饭时常常把饭粒撩出来掉到地板上。于是她经常地吼她的小孩：你总是把饭粒撩到地板上，搞得地板脏死了！……她一次次地吼，但小孩一点都没有改变。【反例】\u003c/p>\u003cp>后来，我给她介绍了“XYZ表达法”，建议她试一试。她还真试了，说：【1】弟弟，我有一个问题，【2】你吃饭的时候，把饭粒撩到地板上（X），【3】弄得地板脏脏的（Y），【4】我感到非常生气（Z），【5】你再这样的话我就要打你屁股了。希望你能记住，以后不要再这样了！……\u003c/p>\u003cp>开始几天，小朋友还有控制不住自己的情况，但一周之后，事情有了很大的改观，地板上现在已经看不到有饭粒了……【变成正例】\u003c/p>\u003cp>\u003cem>（观察点：【I】环节给出了比原书更加细化的行动步骤，或者将书中的案例进行了意译。有举例说明）\u003c/em>\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】\u003c/strong>\u003cstrong>场景设计\u003c/strong>\u003cstrong>/\u003c/strong>拆书家提问设计\u003c/p>\u003cp>好，刚才我们一起学习了“XYZ问题陈述法”。接下来，让我们一起来做个演练。请大家认真听一下要演练的场景——\u003c/p>\u003cp>张先生是一个设计部的主管，他观察到部门同事小王已经连续迟到3天了。虽然公司实行人性化管理，不会扣发工资和奖金，但有员工连续多天迟到，如果不加管束，对公司管理造成的影响肯定是不好的。因此，他决定和小王谈一谈关于他“连续多天迟到”的问题。\u003c/p>\u003cp>而小王呢，更是一肚子怨言。从上星期三开始，主管交给他的任务由于上游部门人手不够部分工作需要他一起来做，又没有帮手协助工作。他已经连续7天加班加点没有休息了。他也正想找主管说这个事情呢！……\u003c/p>\u003cp>根据今天参加活动的人员情况，我们按现场就坐情况坐位相临的2个人组成1个小组进行演练。\u003c/p>\u003cp>演练的方法和内容是：一个人扮演张主管，要和小王谈关于他“连续数天迟到”的问题；另外一个人扮演小王，要和主管报怨“工作安排不当导致他连续加班加点”的事情。\u003c/p>\u003cp>在这里，请注意——我们演练的目的，不是为故事中的问题找到解决方案，而是通过演练学习和掌握我们今天所学的“XYZ问题陈述法”，也就是怎样把你的问题、按照五个步骤的方法和要求进行拆分并清晰地表述出来。\u003c/p>\u003cp>这个表述，有一个要求，就是你说出来的话对方愿意听，你所指出来的问题对方愿意配合、一起解决。\u003c/p>\u003cp>在确定好角色之后，大家可以各自在便签纸上按照五个步骤的方法和要求、先把你要说的内容列举出来，然后再双双对话演练。\u003c/p>\u003cp>好，现在就开始吧。大家有7～8分钟的时间来准备和演练。之后，我们请一个小组来当众呈现一下他们的表演。\u003c/p>\u003cp>…………&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>\u003cem>（观察点：【A3】环节给出了一个非常具体、确定的场景。学习者可以在此场景中演练或讨论或应用新学技能。）\u003c/em>\u003c/p>\u003cp>\u003cem>（观察点：使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。）\u003c/em>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【角色扮演案例实录】\u003c/strong>\u003c/p>\u003cp>好！小组内部演练时间到，下面我们请一个小组用2分钟左右的时间来当众呈现一下他们的表演。哪个小组来？……好，我们掌声欢迎这边这个小组来为我们呈现他们的表演！\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>【学习者A（扮演张主管）】\u003c/p>\u003cp>1、小王啊，跟你说个事\u003c/p>\u003cp>2、我看到你周一到周三每天都有迟到几分钟。你“迟到”的这个行为\u003c/p>\u003cp>3、在同事当中已经引起了一些反响，有同事已经开始在背后议论这个事了。这在部门当中已经造成了比较负面的影响。再这样下去，其他的同事也会去模仿，也会迟到……\u003c/p>\u003cp>4、作为部门的主管，我感到非常的为难\u003c/p>\u003cp>5、如果再这样下去，我可能就要采取一定的措施来加强管理了，希望你能按时来上班……\u003c/p>\u003cp>【学习者B（扮演小王）】\u003c/p>\u003cp>1、领导，我也正想跟你说个事呢\u003c/p>\u003cp>2、就是最近一个星期，由于项目任务大量增加，而部门安排人手严重不足\u003c/p>\u003cp>3、我手头积累了一大堆事情无法完成，我已经一个星期都在加班加点没得好好休息了\u003c/p>\u003cp>4、我现在整个人都处于一个疲惫不堪的状态\u003c/p>\u003cp>5、再这样子下去，不单是迟到，我还担心会影响到项目的进度呢。希望领导能加派一些人手帮我分担一下工作，以保证项目工作的正常进行……\u003c/p>\u003cp>\u003cstrong>【总结】\u003c/strong>\u003c/p>\u003cp>好，谢谢这个小组的表演。非常好的表演。\u003c/p>\u003cp>我们今天一起学习了“XYZ问题陈述法”，让我们知道：在与他人沟通或谈话、要表达不同意见的时候，可以运用这个方法清楚地说出自己的观点、态度和感受，让对方意识到问题所在并配合解决。“解决问题”同时又避免“伤及和气导致关系恶化”。\u003c/p>\u003cp>在现实当中，不论是工作还是生活，“意见不同”的情况总是难免的。当碰到类似情况的时候，希望大家能够想起我们今天一起学习的这个方法并灵活运用，借以避免人际冲突、保持和谐友好关系。\u003c/p>\u003cp>今天的学习就到这里。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1576718387000,"updated_at":1576718495000,"ria":true},{"id":9266,"topic":"XYZ表达","learn_goal":"学习者学完后，可以运用XYZ表达法来沟通","remark":"人际沟通当中，双方之间经常会有一些冲突发生，这时，人们通常喜欢用职责或批评的方式来表达自己的感受和情绪，来让对方做出改变，但是，人对于指责或批评的本能反应就是自我防御：“我没错，你猜错了，你们全家都错了”。所以每当这种冲突发生的时候，我们可以用一个方法来沟通（xyz表达法），它的具体的表达方式是这样的，看到文中的粗体字，我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。今晚我们一起来学习XYZ表达法。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"秦小旺","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"开场： TF1-2 拆书预备表\r\n一、自我介绍、分组\r\n各位小伙伴，大家晚上好！\r\n大家好，我是秦小旺，是一名超级阅读爱好者、中国武术传承者、七年教育从业者。通过阅读《这样读书就够了》这本书，我找到了长沙橘洲分舵的春哥，参加第一次线下活动就彻底爱上这种一群人坐在一起拆同一本书的感觉。今天进行1-2的拆书认证。带拆时长10-15分钟。\r\n便于等会的学习，我们现在以就近的桌子来分一下组，xx组。\r\n二、图书介绍\r\n我今天带拆的书籍是《管理技能开发》，是这本书的第8版。\r\n市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：\r\n第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。今天我将和大家一起探讨其中非常核心的一项技能。\r\n三、【R•阅读原文片段】\r\n戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\r\n第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\r\n  第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\r\n  第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\r\n  我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\r\n四、【I】拆书家讲解引导\r\n人际沟通当中，双方之间经常会有一些冲突发生，这时，人们通常喜欢用职责或批评的方式来表达自己的感受和情绪，来让对方做出改变，但是，人对于指责或批评的本能反应就是自我防御：“我没错，你猜错了，你们全家都错了”。所以每当这种冲突发生的时候，我们可以用一个方法来沟通（xyz表达法），它的具体的表达方式是这样的，看到文中的粗体字，我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。X-行为，Y-后果，Z-感受【黑板】\r\n举例1：“你说六点钟到这里，却七点多才起来【行为】，晚饭泡汤了，我们看演出也迟到了【后果】，我感觉受到了伤害，觉得你不在乎我的感受【感受】”\r\n举例2：那如果我们不这么做会怎样呢？\r\n分享一个自己的故事：\r\n有一次在公司我值日，我知道有一个同事经常睡懒觉，所以提前一个小时提醒她，并且中途还提醒了5次，到最后依然迟到2分钟，最后我看到他迟到了却毫不在意、磨磨蹭蹭的样子，所以当时我就火了，冲上去一顿乱怼，她一大清早被人怼也很不爽，所以两人开始互怼……各位这是一个不成功的案例\r\n 所以现在回忆起来我的沟通模式确实需要改进，如果用上XYZ沟通法的话，我应该会这样：“老陶啊，我发现你今天迟到了2分钟，并且是我在旁边提醒了5次的情况下迟到了【X-行为】，这样的现象会让我感觉你无视规则，并且让我很伤心，也很有挫败感【Z-感受】。这个问题虽然不大，但如果继续这样下去，有可能会导致团队出现拖延、力量不集中、凝聚力下降等一堆的坏毛病【Y-后果】。”\r\n注意点——XYZ/XZY;Y（已/将）\r\n五、【A1】激活经验\r\n拆书家提问设计\r\n（逐字稿）：“ok，现在大家围圈坐好，在以往经历当中，找一个你与对方之间出现了一些冲突的故事，三步（当时什么情景，说了什么话，什么感受），请在小组内分享。每人1分钟！”\r\n学习者案例记录：（邀请一位代表做一下分享……）\r\n文姐：“我和我弟弟从小打闹长大，最近他是叛逆期，所以脾气有点倔强，那一次在家里由于一个很小的事情我们发生了冲突，然后我很生气地对他喊了一句：滚！他也很生气就不理我了……”\r\n六、【A2】催化运用\r\n拆书家提问设计\r\n（逐字稿）：“好，如果未来你再会遇到类似的冲突，让你运用XYZ沟通法去沟通的话，你会如何表达，（把之前小案例快速提一下，便于大家书写），请大家在便签上明确写出XYZ三步模型的沟通方式，一共1分钟的时间，开始吧”\r\n学习者案例记录：\r\n黄小鸭：“X：老公，我们一起来买车，你坚持要买贵的那一台。Y：我不同意，所以今天车没买成。Z：我感觉很不开心，你太关注你自己了。”\r\n芳姐：“X：我们之前说好了一起坚持练习瑜伽，你现在放我鸽子没有过来。Y：现在导致我一个人在这儿练习。Z：我感觉很孤单、瞬间没有了心情。”\r\n七、结束语\r\nOk，回顾一下今天的学习，当身边人做了让自己不满甚至愤怒的事情时，我们可以用XYZ沟通法，第一，描述给你带来问题的具体行为（X），第二，列出这些行为详细的、可见的后果（Y），第三，描述你对问题结果的感受（Z）。希望大家多多使用，谢谢大家！","ratings_count":1,"texts":[],"created_at":1573654262000,"updated_at":1573654262000},{"id":8948,"topic":"表达不满的正确方式——XYZ表达法","learn_goal":"学习者能够在表达不满时，运用XYZ表达法，有效避免冲突","remark":"书中提供了大量的案例和练习，理论联系实践，方便我们快速地掌握管理技能。作者对各类企业中的管理人员进行深入研究，从个人、团队、人际关系三个方面介绍具体的管理技能。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"聚宝盆","city":"常州"},"club":{"name":"常州龙城分舵","city":"常州"},"prologue":"各位小伙伴，大家晚上好！我是今晚TF1-2的拆书家王小芳，昵称聚宝盆。三个标签介绍下我自己：企业HRM、高考志愿规划师、拆书帮会员长老。\r\n【分组】在活动开始之前，我们先进行一个简单的分组，前两桌两两一组，后面一桌3个人一组。","ratings_count":2,"texts":[{"id":12680,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>&nbsp; 第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>&nbsp; 第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>What:&nbsp; 表达不满的正确方式——XYZ表达法，就是描述对方的事实行为、产生的后果、你的感受，通过表达让对方改变，同时避免那些常犯的错误。\u003c/p>\u003cp>Why: 很多时候，我们表达不满、批评或抱怨，往往会指责、揣测对方，或夸大严重性。对方不但没有发生改变，反而容易激化矛盾。走心的表达，可以在不伤害对方的基础上，让对方发生改变。\u003c/p>\u003cp>How: &nbsp;XYZ表达法，具体怎么用呢?可以使用以下3个步骤:\u003c/p>\u003cp>第一步：X-对方行为，描述对方的事实行为；\u003c/p>\u003cp>第二步：Y-产生的后果，描述行为产生的详细后果；\u003c/p>\u003cp>第三步：Z-你的感受，描述你对这件事的感受。\u003c/p>\u003cp>Where: &nbsp;XYZ表达法，适用于阐述问题或自己有情绪波动的场景。\u003c/p>\u003cp>【举个例子】\u003c/p>\u003cp>今年暑假，儿子在家，用奶奶的手机玩游戏，刷掉奶奶2300块钱，奶奶发现了，又急又气。我知道以后，更是火冒三丈，刚想发作，脑子里冒出“XYZ表达法”。于是，我深呼吸，平静下来这样对儿子说：\u003c/p>\u003cp>“第一步：【行为】你玩“和平精英”游戏，刷掉奶奶2300块钱。\u003c/p>\u003cp>第二步：【结果】奶奶又急又气，一个月的生活费没有了。\u003c/p>\u003cp>第三步：【感受】我很生气，但更担心你对游戏上瘾，担心游戏影响你的学业。”\u003c/p>\u003cp>&nbsp;&nbsp; 儿子低头不语，接下来的几个月就再也没有玩游戏了。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>我们刚才学习了表达不满的正确方式——XYZ表达法。那么，请想一想：最近一周，你有没有经历过不满、批评或抱怨的情境、有没有过相关的经验？\u003c/p>\u003cp>请每人想一个类似的案例，在小组内分享。请详细描述故事6要素，即事情发生的时间、地点、人物，起因、经过和结果？\u003c/p>\u003cp>时间2分钟，结束后，我们请一位小伙伴分享。\u003c/p>\u003cp>现在开始............\u003c/p>\u003cp>好，时间到。我们请陈燕给大家分享下，时间1分钟：\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>我女儿今年读小学五年级，功课比以前紧了，需要在学习上花更多的时间。我认为功课是放在第一位的，要把功课做到位，有时间再去运动。可她却认为作业做完了，就可以运动了。\u003c/p>\u003cp>最近几天，她在家做完作业就去骑自行车了。而我希望他作业全部做完，复习下当天的功课，再预习下第二天的功课，全部完成后有时间的情况下，再骑自行车。她不乐意，我也很不满。我想和她好好地表达下我的不满。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>现在，我们来设想一下，未来一周，面对朋友、同事、家人，你在出现不满、抱怨或批评时，会怎样运用XYZ表达法？\u003c/p>\u003cp>接一下，请大家拿出便笺纸，写下未来一周，你计划在什么情境下应用XYZ表达法？如何用？\u003c/p>\u003cp>【建议用以下结构来规划:\u003c/p>\u003cp>时间： &nbsp;\u003c/p>\u003cp>地点：\u003c/p>\u003cp>人物：\u003c/p>\u003cp>运用步骤: 1. 对方的事实行为； 2.产生的后果； 3.你的感受。&nbsp;&nbsp; 】\u003c/p>\u003cp>时间2分钟，结束后，我们请1位小伙伴做分享。\u003c/p>\u003cp>现在开始.................\u003c/p>\u003cp>好，时间到。我们请蒋老师给大家分享下，时间1分钟：\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>时间：下周国庆期间；\u003c/p>\u003cp>地点：新家；\u003c/p>\u003cp>人物：我和老公；\u003c/p>\u003cp>具体事情：我希望把原来家里的东西搬到新家。但老公做事比较拖延可能不会按时搬运物品，而且平时对家里的事也不上心，所以我将运用XYZ表达法与他沟通：\u003c/p>\u003cp>运用步骤：\u003c/p>\u003cp>&nbsp;1.对方的事实行为:&nbsp;老公，你如果拖延，没有按时搬运一些物品去新家；\u003cbr>\u003c/p>\u003cp>&nbsp;2. 产生的后果：会导致我不能在指定时间整理物品并入住新家；\u003c/p>\u003cp>&nbsp;3. 你的感受：我本来很期盼、激动，就会变得伤心难过、又失望。\u003c/p>\u003cp>现在，我们来回顾一下：\u003c/p>\u003cp>今天我们学习了表达不满的正确方式——XYZ表达法，就是通过描述对方的具体行为、后果、你的感受。学以致用，方能致远！\u003c/p>\u003cp>今天我的TF1-2分享就到这，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1569531227000,"updated_at":1569531227000,"ria":true},{"id":8897,"topic":"运用“XYZ表达法”使你的意见问题平稳表达","learn_goal":"通过学习“XYZ表达法”，能现场说出“事件、结果和感受”三段","remark":"有意见出现问题怎么办？抱怨、指责很容易激化矛盾，憋着、忍住不说自己容易造成内伤，“XYZ表达法”让你平稳落地，高情商的避免争吵的局面！","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"淡然","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好！我是淡然，我的三个标签是：看书，分享和心理学。\r\n分组\r\n一、学习目标：：通过“XYZ”表达式拆页学习，使学习者现场说出“行为、结果以及自己的感受”表达问题的三段式。\r\n二、图书介绍（1-2分钟）\r\nF 特征（核心是“书”，用于满足好奇心）：今天拆的这本书叫《管理技能开发》，作者是美国两位作家：大卫·A·惠顿、金·S卡梅伦。\r\nA 优势（重点是“比较”，用于建立安全感）：本书的二位作者通过对400多位有经验的高效管理者，开展精心设计的问卷和调查，提取了管理成功的十大关键技能。这本书与其他管理类书籍相比，特点是提供了大量的实践练习、案例以及最新的方法，在学习管理技能与应用这些技能之间搭建了桥梁。\r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）\r\nB1:如果你对开发自我意识、个人压力管理、创造性和分析性地解决问题等方面感兴趣，这本书会提供给你包含以上三个，共计十大管理技能的自我评估、能力培育以及运用的方法。\r\nB2:：今天，希望通过对“XYZ”表达法拆页的学习，掌握表达批评和指责的方法，从而避免冲突的发生。使我们的人际关系更加和谐，职场生涯更加顺利。","ratings_count":1,"texts":[{"id":12623,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型:“我有一个问题,当你做X时,导致了结果Y,而我的感觉是Z。”\u003c/p>\u003cp>第一,描述给你带来问题的具体行为这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二,列出这些行为详细的、可见的后果(Y)。简单明白地告诉对方,其行为给你带来的问题,通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三,描述你对问题结果的感受(Z)。重要的是不仅要使对方了解哪些行为妨碍了你,而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的.\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化,而且一你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我想问一下大家：当我们对他人有意见时，我们一般会怎样表达呢？\u003c/p>\u003cp>对，指责、抱怨。\u003c/p>\u003cp>但是这种表达方式对方会高兴的接受吗？\u003c/p>\u003cp>对，不会。因为当我们遇到指责的时候，本能的反应都是自我防御：“我没错，你才错了呢”对吧。\u003c/p>\u003cp>那么正确的表达问题的方式是怎样的呢？今天我们就来学习“X Y Z表达法”，它通过表述行为、结果以及你的感受这三段式来表达意见，从而避免冲突的发生。\u003c/p>\u003cp>我有一位闺蜜，总是有意无意的把别人小失误拿来开玩笑。记得有一次，她又在朋友聚会时拿我的坏记性开玩笑，我很不开心。当时真想指责她，但想到场面会很不愉快，为了我们的“革命友谊”我又一次忍住了。但这种情况如果不解决的话，我感觉会气成内伤的。\u003c/p>\u003cp>那么，现在，我用“X Y Z表达法”可以很好地来解决这个问题。\u003c/p>\u003cp>第一步，讲行为。用“当你………的时候”的句式简单明了的表达对方具体的行为。\u003c/p>\u003cp>我会说：“当你在别人面前拿我的坏记性开玩笑时”（行为）\u003c/p>\u003cp>第二步，讲结果。用“我………”句式简单直白的说出行为造成的结果。\u003c/p>\u003cp>我会说：“我不想和你呆在一起了，想借故离开。”（结果）\u003c/p>\u003cp>第三步，讲感受。用“我觉得……”的句式，用不开心、愤怒、气愤、伤心等形容词表达自己内心的感受，不加任何评价和分析。\u003c/p>\u003cp>我会这样说：“我觉得自己很难堪，我很不开心。”（感受）\u003c/p>\u003cp>大家看，我这样的表达，是不是可以很好的替代了批评和指责，避免出现争执、冲突等不愉快的情况了呢。\u003c/p>\u003cp>【可能有的质疑】有人可能会说，如果我用X Y Z方法表达了，没有效果怎么办呢？那就重复使用这种方法直到对方理解。当然，不是说一样的话，而是用不同的X Y Z来表达同一个意思。\u003c/p>\u003cp>也有人会问，“XYZ”顺序可以颠倒一下吗？可以的。根据我们的思路可以先说行为，然后是感受，最后说结果，顺序根据自己的需要调整。\u003c/p>\u003cp>【适用边界】当双方交流出现了问题，我们希望避免冲突时使用。\u003c/p>","interaction":"\u003cp>：我们学习了X Y Z表达法来替代批评或指责。现在一起做一个演练。\u003c/p>\u003cp>大家认真听一下要演练的场景，小王和小芳，同一时间进入到公司，两个人对工作都非常的认真努力，一年后，小红被提升到主管，小王没有得到提升，心里有情绪，对部门经理李经理交代的工作总是推三阻四，不按时完成。\u003c/p>\u003cp>现在,请每两人一组,进行演练。一个人扮演李经理,你主动找小王谈话,如何用XYZ表达法来表达你对小王最近工作态度的不满；另一个扮演小王,你在听完李经理的话后,用XYZ表达对公司这次人事任命的不满。\u003c/p>\u003cp>在分组演练之前，请大家用5分钟思考，写下自己的这二个角色的XYZ表达方式。\u003c/p>\u003cp>好，大家都写的差不多，请大家在组里进行一个分享，选择大家认为最适合的表达方式在组里进行角色扮演的演练。\u003c/p>\u003cp>然后,我会选一位“李经理”和一位“小王”，大家一起听听他们的xyz是怎么说的。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>（扮演李经理）当我交代工作，你总是推三阻四的时候，（行为）非常影响团队工作氛围以及工作的进度，（结果）我感觉很生气。（感受）\u003c/p>\u003cp>（扮演小王）：当晋升了小红而没有晋升我的时候，（行为）我感觉非常的失落，（感受）所以工作都没有热情了。（结果）\u003c/p>\u003cp>我们今天学习了用XYZ方法表达自己的指责和抱怨，感受到它的魅力，\u003c/p>\u003cp>不会伤害到对方，不会伤害到关系。希望大家以后多多用起来。时刻提醒自己“表达愤怒而不是愤怒的表达”。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1568878686000,"updated_at":1568878686000,"ria":true},{"id":8661,"topic":"XYZ沟通法","learn_goal":"学完后，学习者可以运用XYZ沟通法化解生活中遇到的冲突","remark":"《管理技能开发》，是这本书的第8版。\r\n市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：\r\n第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"秦小旺","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"开场： TF1-2 拆书预备表\r\n一、自我介绍、分组\r\n各位小伙伴，大家晚上好！\r\n大家好，我是秦小旺，是一名超级阅读爱好者、中国武术传承者、七年教育从业者。通过阅读《这样读书就够了》这本书，我找到了长沙橘洲分舵的春哥，参加第一次线下活动就彻底爱上这种一群人坐在一起拆同一本书的感觉。今天进行1-2的拆书认证。带拆时长10-15分钟。\r\n便于等会的学习，我们现在以就近的桌子来分一下组，xx组。\r\n二、图书介绍\r\n我今天带拆的书籍是《管理技能开发》，是这本书的第8版。\r\n市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：\r\n第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。今天我将和大家一起探讨其中非常核心的一项技能。\r\n三、【R•阅读原文片段】\r\n戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\r\n第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\r\n  第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\r\n  第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\r\n  我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\r\n四、【I】拆书家讲解引导\r\n人际沟通当中，双方之间经常会有一些冲突发生，这时，人们通常喜欢用职责或批评的方式来表达自己的感受和情绪，来让对方做出改变，但是，人对于指责或批评的本能反应就是自我防御：“我没错，你猜错了，你们全家都错了”。所以每当这种冲突发生的时候，我们可以用一个方法来沟通（xyz表达法），它的具体的表达方式是这样的，看到文中的粗体字，我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。X-行为，Y-后果，Z-感受【黑板】\r\n举例1：“你说六点钟到这里，却七点多才起来【行为】，晚饭泡汤了，我们看演出也迟到了【后果】，我感觉受到了伤害，觉得你不在乎我的感受【感受】”\r\n举例2：那如果我们不这么做会怎样呢？\r\n分享一个自己的故事：\r\n有一次在公司我值日，我知道有一个同事经常睡懒觉，所以提前一个小时提醒她，并且中途还提醒了5次，到最后依然迟到2分钟，最后我看到他迟到了却毫不在意、磨磨蹭蹭的样子，所以当时我就火了，冲上去一顿乱怼，她一大清早被人怼也很不爽，所以两人开始互怼……各位这是一个不成功的案例\r\n 所以现在回忆起来我的沟通模式确实需要改进，如果用上XYZ沟通法的话，我应该会这样：“老陶啊，我发现你今天迟到了2分钟，并且是我在旁边提醒了5次的情况下迟到了【X-行为】，这样的现象会让我感觉你无视规则，并且让我很伤心，也很有挫败感【Z-感受】。这个问题虽然不大，但如果继续这样下去，有可能会导致团队出现拖延、力量不集中、凝聚力下降等一堆的坏毛病【Y-后果】。”\r\n注意点——XYZ/XZY;Y（已/将）\r\n五、【A1】激活经验\r\n拆书家提问设计\r\n（逐字稿）：“ok，现在大家围圈坐好，在以往经历当中，找一个你与对方之间出现了一些冲突的故事，三步（当时什么情景，说了什么话，什么感受），请在小组内分享。每人1分钟！”\r\n学习者案例记录：（邀请一位代表做一下分享……）\r\n文姐：“我和我弟弟从小打闹长大，最近他是叛逆期，所以脾气有点倔强，那一次在家里由于一个很小的事情我们发生了冲突，然后我很生气地对他喊了一句：滚！他也很生气就不理我了……”\r\n六、【A2】催化运用\r\n拆书家提问设计\r\n（逐字稿）：“好，如果未来你再会遇到类似的冲突，让你运用XYZ沟通法去沟通的话，你会如何表达，（把之前小案例快速提一下，便于大家书写），请大家在便签上明确写出XYZ三步模型的沟通方式，一共1分钟的时间，开始吧”\r\n学习者案例记录：\r\n黄小鸭：“X：老公，我们一起来买车，你坚持要买贵的那一台。Y：我不同意，所以今天车没买成。Z：我感觉很不开心，你太关注你自己了。”\r\n芳姐：“X：我们之前说好了一起坚持练习瑜伽，你现在放我鸽子没有过来。Y：现在导致我一个人在这儿练习。Z：我感觉很孤单、瞬间没有了心情。”\r\n七、结束语\r\nOk，回顾一下今天的学习，当身边人做了让自己不满甚至愤怒的事情时，我们可以用XYZ沟通法，第一，描述给你带来问题的具体行为（X），第二，列出这些行为详细的、可见的后果（Y），第三，描述你对问题结果的感受（Z）。希望大家多多使用，谢谢大家！","ratings_count":0,"texts":[],"created_at":1566179725000,"updated_at":1566179725000},{"id":8575,"topic":"XYZ 高效沟通法","learn_goal":"学习者学完后，可以运用xyz沟通法解决生活中的冲突","remark":"《管理技能开发》是这本书的第8版。市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。今天我将和大家一起探讨其中非常核心的一项技能。","level":"TF1-2","duration":13,"status":0,"type":0,"chaishujia":{"username":"秦小旺","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"TF1-2 拆书预备表\r\n一、自我介绍、分组\r\n各位小伙伴，大家晚上好！\r\n大家好，我是秦小旺，是一名超级阅读爱好者、中国武术传承者、七年教育从业者。通过阅读《这样读书就够了》这本书，我找到了长沙橘洲分舵的春哥，参加第一次线下活动就彻底爱上这种一群人坐在一起拆同一本书的感觉。今天进行1-2的拆书认证。带拆时长10-15分钟。\r\n便于等会的学习，我们现在以就近的桌子来分一下组，xx组。\r\n二、图书介绍\r\n我今天带拆的书籍是《管理技能开发》，是这本书的第8版。\r\n市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：\r\n第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。今天我将和大家一起探讨其中非常核心的一项技能。\r\n三、【R•阅读原文片段】\r\n戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\r\n第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\r\n  第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\r\n  第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\r\n  我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\r\n四、【I】拆书家讲解引导\r\n人际沟通当中，双方之间经常会有一些冲突发生，这时，人们通常喜欢用职责或批评的方式来表达自己的感受和情绪，来让对方做出改变，但是，人对于指责或批评的本能反应就是自我防御：“我没错，你猜错了，你们全家都错了”。所以每当这种冲突发生的时候，我们可以用一个方法来沟通（xyz表达法），它的具体的表达方式是这样的，看到文中的粗体字，我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。X-行为，Y-后果，Z-感受【黑板】\r\n举例1：“你说六点钟到这里，却七点多才起来【行为】，晚饭泡汤了，我们看演出也迟到了【后果】，我感觉受到了伤害，觉得你不在乎我的感受【感受】”\r\n举例2：那如果我们不这么做会怎样呢？\r\n分享一个自己的故事：\r\n有一次在公司我值日，我知道有一个同事经常睡懒觉，所以提前一个小时提醒她，并且中途还提醒了5次，到最后依然迟到2分钟，最后我看到他迟到了却毫不在意、磨磨蹭蹭的样子，所以当时我就火了，冲上去一顿乱怼，她一大清早被人怼也很不爽，所以两人开始互怼……各位这是一个不成功的案例\r\n 所以现在回忆起来我的沟通模式确实需要改进，如果用上XYZ沟通法的话，我应该会这样：“老陶啊，我发现你今天迟到了2分钟，并且是我在旁边提醒了5次的情况下迟到了【X-行为】，这样的现象会让我感觉你无视规则，并且让我很伤心，也很有挫败感【Z-感受】。这个问题虽然不大，但如果继续这样下去，有可能会导致团队出现拖延、力量不集中、凝聚力下降等一堆的坏毛病【Y-后果】。”\r\n注意点——XYZ/XZY;Y（已/将）\r\n五、【A1】激活经验\r\n拆书家提问设计\r\n（逐字稿）：“ok，现在大家围圈坐好，在以往经历当中，找一个你与对方之间出现了一些冲突的故事，三步（当时什么情景，说了什么话，什么感受），请在小组内分享。每人1分钟！”\r\n学习者案例记录：（邀请一位代表做一下分享……）\r\n文姐：“我和我弟弟从小打闹长大，最近他是叛逆期，所以脾气有点倔强，那一次在家里由于一个很小的事情我们发生了冲突，然后我很生气地对他喊了一句：滚！他也很生气就不理我了……”\r\n六、【A2】催化运用\r\n拆书家提问设计\r\n（逐字稿）：“好，如果未来你再会遇到类似的冲突，让你运用XYZ沟通法去沟通的话，你会如何表达，（把之前小案例快速提一下，便于大家书写），请大家在便签上明确写出XYZ三步模型的沟通方式，一共1分钟的时间，开始吧”\r\n学习者案例记录：\r\n黄小鸭：“X：老公，我们一起来买车，你坚持要买贵的那一台。Y：我不同意，所以今天车没买成。Z：我感觉很不开心，你太关注你自己了。”\r\n芳姐：“X：我们之前说好了一起坚持练习瑜伽，你现在放我鸽子没有过来。Y：现在导致我一个人在这儿练习。Z：我感觉很孤单、瞬间没有了心情。”\r\n七、结束语\r\nOk，回顾一下今天的学习，当身边人做了让自己不满甚至愤怒的事情时，我们可以用XYZ沟通法，第一，描述给你带来问题的具体行为（X），第二，列出这些行为详细的、可见的后果（Y），第三，描述你对问题结果的感受（Z）。希望大家多多使用，谢谢大家！","ratings_count":0,"texts":[],"created_at":1565091478000,"updated_at":1565091478000},{"id":7793,"topic":"XYZ高效沟通法","learn_goal":"现场伙伴跟随学习之后，可以运用XYZ高效沟通法来解决冲突","remark":"我们在日常沟通当中，难免会发生冲突甚至愤怒的场景，那如何用沟通的方法解决冲突呢，你可以尝试XYZ沟通法，注重彼此的感受，沟通会有完全不同的结果。","level":"TF1-2","duration":10,"status":29,"type":0,"chaishujia":{"username":"秦小旺","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"TF1-2 拆书预备表\r\n认证人员：秦旺 认证级别：TF1-2 认证时间：2018/9/20\r\n环节 时间 准备内容\r\n分组 30秒 各位小伙伴，大家晚上好！\r\n我是秦小旺，今天进行1-2的拆书认证。\r\n便于等会的学习，我们现在以就近的桌子来分一下组，xx组。\r\n图书介绍 40秒 我今天带拆的书籍是《管理技能开发》，是这本书的第8版。\r\n市面上关于管理类的书其实不少，而这本书有几个不一样的亮点：\r\n第一，别的书更多是研究团队整体的管理方向，而这本书是从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n第二，作者是通过精心设计的问卷调查，来提取的有关管理成功的关键技能，鉴别了十大管理技能干货。今天我将和大家一起探讨其中非常核心的一项技能。\r\n【R】阅读原文拆页 2分钟 【R•阅读原文片段】\r\n戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\r\n 第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\r\n  第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\r\n  第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\r\n  我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\r\n【I】\r\n拆书家讲解引导 3分钟 【I：拆书家讲解引导】\r\n人际沟通当中，当对方做了一些令自己不满甚至愤怒的事情时，可以用一个方法来沟通（xyz表达法），它的具体的表达方式是这样的，看到文中的粗体字，我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。X-行为，Y-后果，Z-感受【黑板】\r\n举例1：“你说六点钟到这里，却七点多才起来【行为】，晚饭泡汤了，我们看演出也迟到了【后果】，我感觉受到了伤害，觉得你不在乎我的感受【感受】”\r\n举例2：那如果我们不这么做会怎样呢？\r\n分享一个自己的故事：\r\n有一次在公司我值日，我知道有一个同事经常睡懒觉，所以提前一个小时提醒她，并且中途还提醒了5次，到最后依然迟到2分钟，最后我看到他迟到了却毫不在意、磨磨蹭蹭的样子，所以当时我就火了，冲上去一顿乱怼，她一大清早被人怼也很不爽，所以两人开始互怼……各位这是一个不成功的案例\r\n 所以现在回忆起来我的沟通模式确实需要改进，如果用上XYZ沟通法的话，我应该会这样：“老陶啊，我发现你今天迟到了2分钟，并且是我在旁边提醒了5次的情况下迟到了【X-行为】，这样的现象会让我感觉你无视规则，并且让我很伤心，也很有挫败感【Z-感受】。这个问题虽然不大，但如果继续这样下去，有可能会导致团队出现拖延、力量不集中、凝聚力下降等一堆的坏毛病【Y-后果】。”\r\n注意点——XYZ/XZY;Y（已/将）\r\n【A1】\r\n激活经验 5-6分钟 拆书家提问设计\r\n（逐字稿）：“ok，现在大家围圈坐好，在以往经历当中，当身边朋友做了让你感到不满甚至愤怒的事情时，你有没有处理失败的一个案例，当时你说了什么话，双方什么感受，请在小组内分享。每人1分钟！”\r\n 学习者案例记录：（邀请一位代表做一下分享……）\r\n【A2】\r\n催化运用 1分钟 拆书家提问设计\r\n（逐字稿）：“好，现在针对刚刚的案例，请大家在便签上明确写出XYZ三步模型的沟通方式，一共1分钟的时间，开始吧”\r\n 学习者案例记录：（有时间的话，邀请一位代表做一下分享……）\r\n结束语 30秒 Ok，回顾一下今天的学习，当身边人做了让自己不满甚至愤怒的事情时，我们可以用XYZ沟通法，第一，描述给你带来问题的具体行为（X），第二，列出这些行为详细的、可见的后果（Y），第三，描述你对问题结果的感受（Z）。希望大家多多使用，谢谢大家！","ratings_count":1,"texts":[],"created_at":1556765011000,"updated_at":1556765011000},{"id":7540,"topic":"XYZ表达抱怨法","learn_goal":"通过拆解XYZ法，让学习者学会得体表达不满和抱怨。 ","remark":"XYZ法简介如下： 第一，描述给你带来问题的具体行为（X）\r\n第二，列出这些行为详细的、可见的后果（Y）。\r\n第三，描述你对问题结果的感受（Z）    这个XYZ法好在说话者是就事论事，没有妄加猜测，或者直接评论，这样可以避免听的一方戒备和反击，完全听不进去你说的。另外一方面XYZ法可操作性很强，X-行为，Y-后果，Z-感受，三者互为相关，逻辑性很强。 这样的表达相较于我们平常的一般做法更容易让听者接受并愿意做出改变，这样你表达抱怨的目的就达到了。另外，根据不同情况任意排序XYZ的表达顺序。","level":"TF2-1","duration":18,"status":30,"type":0,"chaishujia":{"username":"Lotus","city":"武汉"},"club":{"name":"武汉古琴台分舵","city":"武汉"},"prologue":"大家好，我是Lotus,全国第227位一级拆书家。同时我也是长期卧底外企的正在进阶2级的路上的拆书家，在企业社会责任这个圈子混了10年，最近两年接触面料去毒项目，欢迎行内行外朋友来交流。\r\n（F）今天我带领大家拆解的片段来自《管理技能开发》这本书，从书名就知道，它是一本管理类别的书籍。 \r\n（A）这本书提供了大量的练习，实践案例，边阅读边应用，可以快速落地，它通过精心设计的问卷和调查提取有关管理成功的关键技能，以大样本实证分析鉴别了十大管理技能：开发自我意识、个人压力管理、创造性和分析性地解决问题等等。对于工商管理类专业学生特别推荐使用，对于公司管理者也有很强的参考价值。\r\n（B） 如果你是公司的管理者希望提高公司或部门的管理能力，创造紧密的团队合作关系，这本书能为你提供诸多指引，如果你只是对管理有兴趣，通过学习这本书来提升自我管理能力和加强人际关系，那么这本书可以让你避免陷入盲目行动的误区。如果你是正在学习管理专业的学生，它将是一本不可多得的从理论到实践巧妙结合的桥梁书。","ratings_count":1,"texts":[{"id":11014,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>《管理技能开发（第8版）》，摘录自429～430页\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cem>举例+\u003c/em>\u003cem>不那么做的坏处：\u003c/em>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 今天我要给大家分享的拆页跟表达不满和抱怨有关，我想问问在座的大家平时有没有对某些人某件事不满并向对方抱怨的时候？… &nbsp; 谢谢你们的反馈。我们在心里回忆一下我们是如何表达抱怨的呢？ 我今天带这大家一起来学习一种有效的表达抱怨的方法-是XYZ法，我现在把拆页发给大家，请花两分钟阅读拆页，阅读完的伙伴举手示意我一下…\u003c/p>\u003cp>大家看完拆页内容会想用XYZ法表达抱怨或不满到底有多好呢？请容我先在这里解释咱们的一般做法有什么不好。 我们表达不满是希望对方知道我们不满和听进去我们的建议并愿意做出改变。平时我经历得比较多的表达不满或抱怨是这样子的， 你看看你，玩你的期货比跟老婆聊天还重要。”这是我前几天才跟我们家先生说的话，我也听到我先生经常这样抱怨我：“你每次炒完菜之后总是不记得洗锅” 听出来了吗话里头都是指责对方、揣测对方动机、夸大严重性。很明显这些表达方式都很难达到目的，甚至起到反作用，引发对方的戒备和反击。我听到我先生说我炒菜不洗锅的时候，我心里全是窝火，我反击他说“我洗的时候你都没看见，你就喜欢这样评判别人…”所以我能想象我的先生听到我抱怨他炒期货时那种表达时，他的内心有多么不快。\u003c/p>\u003cp>这个XYZ法好在说话者是就事论事，没有妄加猜测，或者直接评论，这样可以避免听的一方戒备和反击，完全听不进去你说的。另外一方面XYZ法可操作性很强，X-行为，Y-后果，Z-感受，三者互为相关，逻辑性很强。 这样的表达相较于我们平常的一般做法更容易让听者接受并愿意做出改变，这样你表达抱怨的目的就达到了。另外，根据不同情况任意排序XYZ的表达顺序。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我现在就用XYZ表达法来表达对先生很晚了还在玩期货的不满这件事：“我看到你这几天晚上10点多了还在看期货行情 （X-先生具体的行为），一直想跟你聊聊最近家里和孩子的事情都没有机会（Y-后果），我感觉很生气，觉得你好像不在乎我和孩子了 。（Z-感受）\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;大家请认真回想一下你们最近有没有向家人、朋友表达过自己的不满，抱怨他们的时候？ 是什么时候，什么事情呢？ 请想一想，请在小组内分享。\u003c/p>\u003cp>（分组）我们来做个分组，从我旁边这位伙伴算跟正对面的伙伴成为一组，以此类推，请大家讲自己的这个经历在小组里面进行分享。&nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学习者思思的分享：我前几天得知我妹又换了一台手机，她本来刚工作，收入也不高，我这当姐看她这样花钱真是看不下去了，我当时就这样说她的：“怎么又换手机了，刚刚参加工作就这么花钱。”她听了之后没搭理我，低着头看她的手机，但是我能感觉出来我这么说她，她心里很有意见。\u003c/p>\u003cp>&nbsp; &nbsp;拆书家提问设计（逐字稿）：基于刚刚大家分享的经历，如果你再有机会回到原来的情景，请运用我们今天拆解的XYZ表达法表达你的不满/抱怨。&nbsp;\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003cp>&nbsp; &nbsp; 今天学习力XYZ法之后，我觉得如果我按照这个方法跟我妹沟通应该会效果好很多，她也会愿意听取我的意见。 再遇到这个情况，我会这么说：“\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>我看到你换了一部新手机（行为），然后这个月手头吃紧你来找我支助一下（后果），我感觉很恼火，觉着你在消费方面不成熟。（感受）\u003c/p>\u003cp>&nbsp; &nbsp;非常感谢现场伙伴们的分享，看到大家这么激烈的演练，大家对这个方法很多感触，很多分享。从今天开始我们就用XYZ法去表达我们的不满和抱怨吧，回去一定要多多练习。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554773911000,"updated_at":1554773911000,"ria":true},{"id":6996,"topic":"如何表达抱怨1","learn_goal":"学会表达自己的不满","remark":"表达自己的不满是一种典型的情况，教育儿女，指导需要改进的下属，开导沉侵在某些事情中无法自拔的朋友.……都是如此。\r\n然而你真的会表达好自己的感受和意见吗？你想知道表达抱怨的正确方法吗？","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"熊书容","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"大家好！我叫熊书容，用三个标签来介绍我自己分别是：新妈妈，金融工作者，学习爱好者。\r\n接下来我介绍一下拆书帮，’拆书，拆书家分别是什么，拆书帮是由赵周老师创立的，在很多城市有分舵，是基于拆书法的学习爱好者社群，是非盈利性的公益性组织。\r\n拆书是一种学习方法论，适用于成人学习，强调以学习者为中心而不是以知识为中心，以提升能力解决问题为目标。\r\n拆书家就是运用ria便签读书法，通过升级打怪把书本上的知识拆为已用，是高级的学习促进者。\r\n我今天要讲解的内容来自图书（管理技能开发）第429页至430页即“如何表达抱怨”这本书是由美国著名学者大卫.A和金.S卡梅伦撰写，本书从个人·，人际关系和团体三个方面对管理技能进行了全面探讨","ratings_count":1,"texts":[{"id":10374,"quote":"\u003cp>主题】：如何表达抱怨\u003c/p>\u003cp>片段来源】：《管理技能开发》P．429～430\u003c/p>\u003cp>R：\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第一，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三步模型作为一般性的指导来使用。\u003c/p>\u003cp>每个部分的顺序可能会有变化，而且你不要总是使用\u003c/p>\u003cp>相同的词语。\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>：\u003c/strong>很多时候，我们都希望通过表达意见或建议使他人发生改变。表达自己的不满是一种典型的情況，教育儿女、指导需要改进的下属、开导沉浸在某些事情中无法自拔的朋友．都是如此。而当我们抱怨或提意见的时候，往往会指责对方、揣测对方动机、夸大严重性。这些表达方式都很难达到目的，甚至起到反作用，引发对方的戒备和反击。因为人在遇到指责的时候，本能反应通常都是自我防御“我没错，你才错了，你们全家都错了”．\u003c/p>\u003cp>所以也有人因为害怕惹怒对方而不敢表达自己的不满，XYZ表达法是非常清晰可操作的方法，能够较好地达到通过表达让对方改变的目的，同时避免那些常犯的错误的方法：也就是片段提出的XYZ模型，首先指出对方做的什么事情，导致了什么样的后果，以及说出我们有什么样的感受。\u003c/p>\u003cp>具体的步骤：\u003c/p>\u003cp>\u003cstrong>第一步、举事件。\u003c/strong>举出对应的事件让对方意识到自己的不当行为；\u003c/p>\u003cp>\u003cstrong>第二步、说后果\u003c/strong>。说明这个事件帯来了什么后果\u003c/p>\u003cp>\u003cstrong>第三步、表感受\u003c/strong>。表达自己内心的不满感受。（多为生气、沮丧、失望等）\u003c/p>\u003cp>书中紧接着还给了两个XYZ表达的例子：\u003c/p>\u003cp>&nbsp; &nbsp;例1： 我必须告诉你，当你在别人面前拿我的坏记性开玩笑时［行为］，我是多么难堪［感受］，我都想把你的缺点也说出来报复你［后果」。\u003c/p>\u003cp>&nbsp; &nbsp; 例2：你约了朋友6点钟去吃饭然后去看电影，结果朋友没有履约。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;你说6点钟到这里，却7点多钟才来［行为］，晚饭泡汤了，我们看电影也迟到了［后果］，我很不开心，觉得你不在乎我［感受】\u003c/p>","interaction":"\u003cp>\u003cstrong>A1:\u003c/strong>今天早上，跟同事小娟约好了中午一起去吃饭 然后去逛街，小娟说马上会有一个客户过来可能会晚一点才能去吃饭，我说没事，我等你，小娟也说好的。等到了1点钟我好饿了，看他也忙完了，他却突然说中午不能跟我一起去吃饭了，他刚让别的同事带了饭，我说，你怎么这个样子啊，一点信用都没有，害我等你等了这么久，你就一句不去了，你早干嘛去了，这个时候才说\u003c/p>\u003cp>反思：我当时只表现出了自己很生气，但是没有说出具体事件，也没有说出这个事情会带来什么后果\u003c/p>\u003cp>\u003cstrong>A2:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：下一个月，如果我遇到让自己很生气或者有抱怨的时候，我会这么做：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>1，\u003cstrong>把手机桌面设置成写有具体步骤\u003c/strong>\u003cstrong>x【具体行为】，y【行为后果】，z【我的感受】的图片，每当自己情绪激动或者愤怒的时候就看看手机\u003c/strong>\u003c/p>\u003cp>2，\u003cstrong>把这个方法告诉我的下属，每当我在公司对员工工作有不满的时候就让他们提醒我看看手机，并提醒我要按这三个步骤x【具体行为】y【我的感受】z【行为后果】来做\u003c/strong>\u003c/p>\u003cp>3，\u003cstrong>如果当天成功运用了一次，就记录在笔记本上，攒够3次就奖励自己一个小礼物\u003c/strong>\u003c/p>\u003cp>4，\u003cstrong>到了月底30号的时候和同事做一个复盘，让他们来对我这一个月的抱怨表达方式做一个评价，直到自己能养成一个好的习惯\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1546866213000,"updated_at":1546866213000,"ria":true},{"id":6958,"topic":"如何正确表达抱怨@","learn_goal":"通过本次学习，在抱怨他人时候，利用XYZ模型表达自己的不满。","remark":"在跟随我完成本次RIA现场学习后，学习者在抱怨他人的时候，利用XYZ模型表达自己的不满，避免错误的方式造成双方矛盾激化，造成隔阂，从而使双方理解彼此感受和需要，更好的解决问题。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"王小七","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"拆动乾坤，赋能你我！大家好，我是小七，用3个标签来介绍一下我自己：一级拆书家、记者、思维导图讲师。很高兴有机会和大家共同学习，共同成长。在开始学习之前，我们先来分一下组。左右两边各一组。\r\n我今天拆解的主题——如何用正确句式表达抱怨。\r\n我先简单的介绍一下今天要拆的书——经典管理能力书籍《管理技能开发》。\r\n【F（特征）】:\r\n书名：《管理技能开发》\r\n作者：美国著名学者大卫.A.惠顿和金.S.卡梅伦共同撰写，惠顿是杨百翰大学教授，康奈尔大学博士，卡梅伦是密歇根大学商学院教授，耶鲁大学博士。\r\n这本书并不是传统的管理理论或者是成功者和管理者的经验总结，是侧重于帮助学习者提高自己的个人管理能力，关注的是优秀的管理者如何去“做”。\r\n【A（优势）】：\r\n和同类管理书籍相比，这本书最大的特色在于其编排设计，兼顾了概念学习和行为练习，将重点放在了实践管理技能而不是阅读上。本书行文生动，可以让学习者一边学习一边拿来用，一点也不枯燥。作为经典书籍，《管理技能开发》多次被拆书帮的资深拆书家进行拆解和应用。\r\n【B（利益）：】\r\n你了解自己的个性吗？在面对恼人的冲突时，你能用正确的控制情绪的方式吗？面对别人给你的负面反馈时，你能否平心静气的正确交流沟通？作为管理者，你在团队中能建立别人对你的信任，从而提高士气，增加效率吗？通过阅读这本《管理技能开发》，帮助你管理自己的生活和人际关系的很多方面，通过改变行为，从而提高能力。","ratings_count":1,"texts":[{"id":10331,"quote":"\u003cp>请大家先用2分钟时间快速阅读完片段。阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>【原文片段】拆解片段来自《管理技能开发》;P.282\u003c/p>\u003cp>戈登（Gordon，２０００）描述了一个帮助你有效陈述你的问题的有用模型：”我有一个问题，当你做X时，Y为结果，并且我感觉到了Z。”虽然我们不提议通过记忆公式来高内通技能，但是在你脑子里记住这个模型有助于你理解“问题陈述中的三个重要元素。\u003c/p>\u003cp>　　首先，描述给你带来特定问题的具体行为（X），这有助于你在急于给出反馈时给出一种评价性的或泛泛回答的倾向。一种方式是去违背具体化的期望和标准。例如，由于担心你可能在截止期限前不能完成指定的任务。你的老板将会慢慢地把工作交给别人去做而不通知你。\u003c/p>\u003cp>　　其次，强调这些行为详细的、可见的后果（Y），简单明自地叙述别人的行为给你带来了麻烦，通常是使他们作出改变的有效刺激。在快节秦的工作环境中，人们通常会意识不到自已行为的后果。他们并不想冒犯他人，但是他们经常要忙于应对有关“新产品推出”的截止日期，并且还要接收来自各方的负面反馈，当这种情况发生时，别人的注意力和他们行为的结果将会促使他们去改变。\u003c/p>\u003cp>　　不幸的是，不是所有的问题都能被这样简单地解决。经常是，冒犯者意识到了他们行为的消极结果，但仍然不改，在这种情况下，这种方法对引发问题解决的讨论时仍是有效的，因为它展示了一个在无威胁情况下的关注。很有可能，回应人的行为受到了他老板期望的影响，或者受到他所处的部门当前刚好人手不足的现实问题的影响。回应人可能无法改变这些情况，但是这种方法会鼓励他们和你讨论这些问题，从而你们可以一起解决问题。\u003c/p>\u003cp>　　最后，描述你对问题结果的感受（Z），重要的是要使回应人了解他的这些行为不仅仅是为你带来了不便，而且你需要向他们解释它如何通过带你挫折、愤怒或不安全等感受来影响你，解释这些感受是怎样干扰你的工作，这些行为可能使你更加难于集中注意力，或难于和消费者融洽相处，或无法获得老板的支待。或者不再愿意为了赶时间而做出个人牺牲。\u003c/p>","explains":"\u003cp>【what】很多时候，我们都会遇到这样的问题，对方教育孩子的方式让你感觉很不爽，朋友不考虑你的感受擅自做了主张，你的同事不了解的意图，做了错误决定。……这时候我们感觉很不满，很容易就出现“你怎么这么笨，这点事你还做不好。”、“你这么做会有很严重的后果，你不知道吗？”、“你为什么不听听我的意见就决定？”这样的话语很容易引起对方的不满。我们本来是希望通过表达意见或者建议促使他人发生改变，但是结果却经常适得其反。而在这个片段中，给出了一个有效陈述陈述问题的有效模型“XYZ”模型，”我有一个问题，当你做X时，Y为结果，并且我感觉到了Z。”这个模型是非常清晰可操作的方法，能够较好的达到通过表达让对方改变的目的，避免常犯错误。\u003c/p>\u003cp>【why】当我们明明是提意见或者表达感受时，往往语气中透漏出指责、埋怨，猜测对方，甚至会夸大严重性。这样的方式，很容易引起对方的防卫甚至攻击，我们收到的反馈很可能是：“你才笨！”“明明是你自己说不清楚！”“你怀疑我！”\u003c/p>\u003cp>长此以往，人际关系会受到破坏，当我们再遇到不满的情况时，还没等我们开口呢，对方一看到我们皱眉、瞪眼、抱胳膊，对方就逃之夭夭，拒绝和我们沟通了。\u003c/p>\u003cp>【how】那我们一起看看原文给的“XYZ模型”表达抱怨的步骤。\u003c/p>\u003cp>1.说行为。描述给你带来特定问题的具体行为（X）\u003c/p>\u003cp>2.说后果。强调这些行为带来的后果（Y）\u003c/p>\u003cp>3.说感受。描述你对问题结果的感受（Z），（例如生气、郁闷、伤心、委屈等）\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>不这么做的坏处\u003c/strong>\u003cstrong>]\u003c/strong>如果不这么做的话，我们的表达很容易让对方误认为我们是在指责他，控诉他，从而扭曲了我们原本想表达的意见和建议，造成双方的隔阂，使矛盾激化。问题没解决还破坏了关系，得不偿失。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>听完后，有没有人觉得这么做太麻烦了，之前虽然会吵架，但是把怨气说出来，一吐为快多舒服啊。事实上，不这么做，更麻烦。因为在类似情况下没用XYZ模型带来的问题更多，包括争吵、误解、冷战、憋屈……总之，“XYZ”模型虽然需要我们做些功课，但是值得。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>就比如说我和我老公吧。\u003c/p>\u003cp>这周一下午三点多，我临时接到一个紧急采访任务，晚上7点之前要交给市领导审稿。我给幼儿园老师发了信息，说晚半个小时去接孩子，随后我给我老公发信息，想让他4点30分去接孩子，结果他的电话一直无人接听，直到下午5点半才给我回消息。这期间，老师多次给我发信息催促我。\u003c/p>\u003cp>当他终于给我回电话的时候，我开始气急败坏了。我说，你这个人怎么这个样，发信息不回，电话给你打了800个了！你这是有多忙啊！你是不是故意的！我下午接到采访，要马上写稿子！孩子没人接！一个多小时了，孩子自己在幼儿园呢！老师总找我！你个破手机能不能调出声音。\u003c/p>\u003cp>听到我说了这些话，老公气急败坏，他说，你这个人真有意思了，你找不到我，不会找别人接孩子啊。你打不通我电话，不知道找我同事吗？你是不是死脑袋，不转个啊。我忙的提溜转，手机一直在办公室没拿出来，你都不听我说话，你凶什么凶！\u003c/p>\u003cp>结果我们闹的挂了对方电话，冷战到晚上。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>经过这个片段的学习，我在周五的时候遇到这样的情况时，利用了“XYZ”模型进行了表达，我说，亲爱的，下午我因为接不上孩子的事，给你发了信息，想问问你能否接孩子，结果一个多小时你都没有联系我（行为），我和老师商量，在幼儿园多等半个小时，到最后让老师等了一个小时，导致老师加班了。（后果）我感觉非常担心和着急（感受）。\u003c/p>\u003cp>当我说完这段话后，我老公说，奇，我今天下午很忙，我们单位水管破裂，我一直指挥工人在维修，手机在办公室充电没顾得上给你回消息。下次在遇到这样的事，你给维丽发信息，她一般都在。让她告诉我。\u003c/p>\u003cp>这样的沟通方式，不但没有引起矛盾，反而促进了我们相互的理解，增进了感情。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>在现代快节奏的社会中，很多人意识不到自己的行为，给对方造成了什么后果。所以，当一些人行为给我们造成不好后果，带来了不便，都可以尝试运用“XYZ”模型，和对方沟通，促使对方去改变。就算对方有自己的难言之隐，改变不了，但是这种不带负面情绪的表达，也可以促使双方找到 解决问题的办法。\u003c/p>","interaction":"\u003cp>下面把时间交给大家，设想未来已来。\u003c/p>\u003cp>未来一周，在自己的工作和生活中哪些情境会遇到想要抱怨？可以从家庭、工作、朋友交流等多个角度设想。比如，回家以后，想吃个热乎饭，却看到洗碗池里，堆满了脏碗；周末带孩子去商场，本来想有个和睦的亲子时光，结果孩子却满商场乱跑；上班时，各种工作忙不过来，好不容易歇一会，领导却把一个重任给了你，让你去做……\u003c/p>\u003cp>请想一个未来一周会向别人表达抱怨的具体情境，分享给同组的伙伴，注意：只需要想出那个场景就可以了。讨论时间2分钟。之后我将邀请小伙伴进行分享。现在开始！\u003c/p>\u003cp>&nbsp;好的，时间到，现在请一位小伙伴儿分享你的案例：\u003c/p>\u003cp>************************************************************\u003c/p>\u003cp>学习者分享记录：\u003c/p>\u003cp>时间：&nbsp; &nbsp; 寒假 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp;地点：在家里\u003c/p>\u003cp>人物： &nbsp; 芒果与老公 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>经过：一起规划利用假期出去“自由行”的计划，因为每次规划都是我来做，他就只管负责玩，每次我都很生气，有时候旅行的并不愉快，但是我从来没有因为这件事抱怨过。而今年我特别忙，没有时间规划路线，也没有时间订机票，所以我准备1月23日开始买机票和订房间，我觉得未来肯定会因为这件事埋怨他抱怨他。\u003c/p>\u003cp>结果：所以我选择今年假期和老公旅行出去玩，都是我来订机票、订房间、规划路线，而他只是等着玩这件事，作为具体情境。\u003c/p>\u003cp>刚才小伙伴芒果做了很棒的分享，你的参与带给了我动力。那么现在请大家运用今天所学的“xyz”模型，设想一下在未来一周，遇到你刚才讨论的场景时，你会怎样利用该模型表达抱怨？给大家4分钟的时间，稍后我们请一位小伙伴分享一下。\u003c/p>\u003cp>好的，时间到，我们请一位小伙伴分享一下。\u003cbr>\u003c/p>\u003cp>************************************************************\u003c/p>\u003cp>学习者分享记录：\u003c/p>\u003cp>目标：我会在下周和老公就寒假出行，都是我来订机票。订房间、规划路线这件事，利用XYZ模型和他沟通。\u003c/p>\u003cp>行动：我会表达的有技巧一点。我会这么和老公说：\u003c/p>\u003cp>每次我们准备旅行，你几乎什么也不管，一切都听从我安排（X），你知道我做旅行计划的能力很糟糕，结果每次我把我们的旅行计划都弄的乱七八糟，不是机票订的贵了，就是房间订的不满意。我们还为此吵过架，导致玩的都不愉快。（Y），这会让我感觉很迷茫也很委屈，（Z），所以我特别希望，这次旅行计划，我们一起来商量着做。\u003c/p>\u003cp>感谢小伙伴芒果的精彩分享，大家的现场学习力一级棒，我的拆书能帮助到大家，也给我带来了一份小骄傲。（感受）感谢大家的聆听，只有行动,才能决定价值!希望大家能主动应用今天学到的内容通过XYZ模型来表达抱怨，以此建立更多良好的连接。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1546468197000,"updated_at":1546468197000,"ria":true},{"id":6915,"topic":"得体的抱怨二","learn_goal":"自我管理和同他人一起工作的基本技能。","remark":"本书涉及七种基本管理技能：自我意识、问题解决、压力管理、沟通、团队管理、冲突管理和授权。这些技能是与人相处所必须掌握的自我管理和同他人一起工作的基本技能。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"野子","city":"宁波"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;大家好，我叫王文涛。大家可以叫我野子！\r\n下面我用2个标签介绍自己，让大家也了解一下我\r\n培训师：目前工作于 教育服务行业，是一名体验式培训师。大家比较熟悉的称呼叫 拓展培训师。目前已经有5年的从业经历了。\r\n远行人：对于山川大河/对于历史人文/对于行走万里 我内心总是有种抑制不住的冲动，我希望我拥有一个有趣的灵魂，也希望自己成为一个有故事的人。\r\n拆书小白：刚刚踏上升级打怪之路，希望各位拆书家们多多指教~ &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp> &nbsp;接下来回归主题，咱们聊聊“书”&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;一本书什么最重要，不是其本身载体，而是书内的知识。各位认同吧！\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;一本书对于我们而言如何收益最大化，是将书内的知识能够“学以致用”。各位认同吧！\u003c/p>\u003cp>所以“拆书”不是实际意义上去破坏它。而是将书内的知识使用最大化 把知识掰开了揉碎了 将自己所缺的/需要的知识提取出来 在生活与工作中真真正正加以运用。将知识转为成我们自己的能力。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>拆书帮则是一个由青年自发组织的公益性.学习.爱好者的.社群。运用RIA便签拆书法帮助不知道如何读书 如何看书 如何用书的伙伴们 如何去拆书。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;R（Reading）：阅读原文某个段落\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; I（Interpretation）：用自己的所理解的话重述\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; A（Appropriation）包含两部分：A1描述自己的相关经验，A2以后我怎么用。\u003c/p>\u003cp>它还能帮助我们的提升演讲力/沟通力/领导力。而因为这种学习的方法有效帮助了很多伙伴学习的提升，所有在各地有很多自发组织的拆书帮的社群 我们称之为拆书帮分舵\u003c/p>","ratings_count":1,"texts":[{"id":10279,"quote":"\u003cp>\u003cstrong>R: 《管理技能开发》\u003c/strong>\u003cstrong>-- \u003c/strong>得体的抱怨\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>戈登描述了一个帮你有效阐述你的问题的有用模型：&quot;我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。&quot;\u003c/p>\u003cp>第一，描述给你带来问题的\u003cstrong>具体行为（X）\u003c/strong>。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为\u003cstrong>详细的、可见的后果（Y）\u003c/strong>。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题\u003cstrong>结果的感受（Z）\u003c/strong>。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来\u003cstrong>影响\u003c/strong>你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>今天我拆的书叫管理技术开发中的一篇 我们称之为\u003cstrong>xyz得体的抱怨沟通技能 。\u003c/strong>\u003c/p>\u003cp>在我们对于某些人和某些事表达不满时可运用，这个技能最后达成的效果是既能让对方听我们的抱怨不会与我们对抗和反驳，也能够接受我们的抱怨并认真考虑我们的所讲述的事情。\u003c/p>\u003cp>我们怎么去运用，首先在原文中几个注意关键点划出便于大家理解\u003c/p>\u003cp>X--对方的曾做过的真实的、客观的事件或行为\u003c/p>\u003cp>Y--指这个行为造成的已经发生过的，是自然后果，绝对不是逻辑后果（假设事实的举例说明：嫁给这个男人，你会吃苦的！）\u003c/p>\u003cp>Z--&nbsp;这个感受对我造成不仅可以指自己的感受：“愤怒、焦虑、担忧”，还可以强调说这件事对于自己的工作和生活的影响。\u003c/p>\u003cp>最后总结&nbsp;得体的抱怨如何说：因为具体行为（x）（事实）。导致了详细的、可见的后果（y）（事实）。而我的感受（z）影响了我，干扰了我的工作。\u003c/p>\u003cp>我举例子比如：昨天说好今天早上赶九点的火车，你迟到了，导致火车也没有赶上，我等你等的很暴躁，耽误了我们的整个行程，我都不想和你说话了！\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; 曾经我就有过不得体抱怨的就经历：比如说&nbsp;上周我在头马俱乐部组织了一次圣诞趴的活动，因为涉及到大量道具需要补偿，负责采购和准备的伙伴到晚了，我们俱乐部7:00，他6：30才到； 真的是现场发飙啊！电话狂打好几个， 等他匆匆赶来，我说：“你到的怎么这么慢！现场还怎么搞” 他说：“如果你嫌弃我慢，下次就不要叫我做这个事你自己做好了”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我将运用 xyz模型再下一周解决我抱怨不得体的事件，我们公司小王 上个月交给他一个任务---为公司找到一间合适的办公室。但是至今还没有结果，下周我会对他说：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;X--小王，已经一个月过去 了，办公室寻找的结果你也没有和我们讲过，\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;y--导致我们也不知道现在的进展如何，现在老大就这件事责怪过培训部了\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; Z--我现在感觉很生气也很担心，这件事情结果不出来明天的休假就要泡汤了。\u003c/p>\u003cp>最后也多希望大家多去运用&nbsp;得体的抱怨xyz&nbsp;沟通模型！帮助自己与他人沟通时更有效的阐述自己的问题\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545959941000,"updated_at":1545960609000,"ria":true},{"id":6877,"topic":"如何正确表达抱怨","learn_goal":"通过xyz模式，学会正确表达抱怨。提升人际关系","remark":"通过xyz模式，学习正确表达抱怨，从而促进和对方的沟通交流，提升人际关系。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"王小七","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;拆动乾坤，赋能你我！大家好，我是小七，用3个标签来介绍一下我自己：一级拆书家、记者、思维导图讲师。很高兴有机会和大家共同学习，共同成长。在开始学习之前，我们先来分一下组。左右两边各一组。\r\n我今天拆解的主题——如何用正确的句式表达抱怨。&nbsp;\u003c/p>\u003cp>&nbsp;我先简单的介绍一下今天要拆的书——经典管理能力书籍《管理技能开发》。&nbsp;\u003c/p>\u003cp>【F（特征）】:\r\n书名：《管理技能开发》\r\n作者：美国著名学者大卫.A.惠顿和金.S.卡梅伦共同撰写，惠顿是杨百翰大学教授，康奈尔大学博士，卡梅伦是密歇根大学商学院教授，耶鲁大学博士。\r\n这本书并不是传统的管理理论或者是成功者和管理者的经验总结，是侧重于帮助学习者提高自己的个人管理能力，关注的是优秀的管理者如何去“做”。&nbsp;\u003c/p>\u003cp>【A（优势）】：和同类管理书籍相比， 这本书最大的特色在于其编排设计，兼顾了概念学习和行为练习，将重点放在了实践管理技能而不是阅读上。本书行文生动，可以让学习者一边学习一边拿来用，一点也不枯燥。作为经典书籍，《管理技能开发》多次被拆书帮的资深拆书家进行拆解和应用。\u003c/p>\u003cp>&nbsp;【B（利益）：】\r\n你了解自己的个性吗？在面对恼人的冲突时，你能用正确的控制情绪的方式吗？面对别人给你的负面反馈时，你能否平心静气的正确交流沟通？作为管理者，你在团队中能建立别人对你的信任，从而提高士气，增加效率吗？通过阅读这本《管理技能开发》，帮助你管理自己的生活和人际关系的很多方面，通过改变行为，从而提高能力。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":10238,"quote":"\u003cp>请大家先用2分钟时间快速阅读完片段。（最后30秒时）阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>【原文片段】拆解片段来自《管理技能开发》;P.282\u003c/p>\u003cp>戈登（Gordon，２０００）描述了一个帮助你有效陈述你的问题的有用模型：”我有一个问题，当你做X时，Y为结果，并且我感觉到了Z。”虽然我们不提议通过记忆公式来高内通技能，但是在你脑子里记住这个模型有助于你理解“问题陈述中的三个重要元素。\u003c/p>\u003cp>　　首先，描述给你带来特定问题的具体行为（X），这有助于你在急于给出反馈时给出一种评价性的或泛泛回答的倾向。一种方式是去违背具体化的期望和标准。例如，由于担心你可能在截止期限前不能完成指定的任务。你的老板将会慢慢地把工作交给别人去做而不通知你。\u003c/p>\u003cp>　　其次，强调这些行为详细的、可见的后果（Y），简单明自地叙述别人的行为给你带来了麻烦，通常是使他们作出改变的有效刺激。在快节秦的工作环境中，人们通常会意识不到自已行为的后果。他们并不想冒犯他人，但是他们经常要忙于应对有关“新产品推出”的截止日期，并且还要接收来自各方的负面反馈，当这种情况发生时，别人的注意力和他们行为的结果将会促使他们去改变。\u003c/p>\u003cp>　　不幸的是，不是所有的问题都能被这样简单地解决。经常是，冒犯者意识到了他们行为的消极结果，但仍然不改，在这种情况下，这种方法对引发问题解决的讨论时仍是有效的，因为它展示了一个在无威胁情况下的关注。很有可能，回应人的行为受到了他老板期望的影响，或者受到他所处的部门当前刚好人手不足的现实问题的影响。回应人可能无法改变这些情况，但是这种方法会鼓励他们和你讨论这些问题，从而你们可以一起解决问题。\u003c/p>\u003cp>　　最后，描述你对问题结果的感受（Z），重要的是要使回应人了解他的这些行为不仅仅是为你带来了不便，而且你需要向他们解释它如何通过带你挫折、愤怒或不安全等感受来影响你，解释这些感受是怎样干扰你的工作，这些行为可能使你更加难于集中注意力，或难于和消费者融洽相处，或无法获得老板的支待。或者不再愿意为了赶时间而做出个人牺牲。\u003c/p>","explains":"\u003cp>【what】很多时候，我们都会遇到这样的问题，对方教育孩子的方式让你感觉很不爽，朋友不考虑你的感受擅自做了主张，你的同事不了解的意图，做了错误决定。……这时候我们感觉很不满，很容易就出现“你怎么这么笨，这点事你还做不好。”、“你这么做会有很严重的后果，你不知道吗？”、“你为什么不听听我的意见就决定？”这样的话语很容易引起对方的不满。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我们本来是希望通过表达意见或者建议促使他人发生改变，但是结果却经常适得其反。而在这个片段中，给出了一个有效陈述陈述问题的有效模型“XYZ”模型，”我有一个问题，当你做X时，Y为结果，并且我感觉到了Z。”这个模型是非常清晰可操作的方法，能够较好的达到通过表达让对方改变的目的，避免常犯错误。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;通过使用本片段介绍的方法，可以让别人清晰的了解到自己的某些行为对我们产生的影响，让对方了解到，我们并不是指责和控诉，而是真心的希望对方了解到其行为给我们造成的结果和感受，从而共同的解决问题。\u003c/p>\u003cp>【why】当我们明明是提意见或者表达感受时，往往语气中透漏出指责、埋怨，猜测对方，甚至会夸大严重性。这样的方式，很容易引起对方的防卫甚至攻击，我们收到的反馈很可能是：“你才笨！”“明明是你自己说不清楚！”“你怀疑我！”\u003c/p>\u003cp>长此以往，人际关系会受到破坏，有可能对方从此就拒绝了和我们的沟通。\u003c/p>\u003cp>【how】如何改进这一问题？如何正确表达抱怨和意见？文中给出了具体步骤。\u003c/p>\u003cp>1.说行为。描述给你带来特定问题的具体行为（X）\u003c/p>\u003cp>2.说后果。强调这些行为带来的后果（Y）\u003c/p>\u003cp>3.说感受。描述你对问题结果的感受（Z），（例如生气、郁闷、伤心、委屈等）\u003c/p>\u003cp>\u003cstrong>[\u003c/strong>\u003cstrong>不这么做的坏处\u003c/strong>\u003cstrong>]\u003c/strong>如果不这么做的话，我们的表达很容易让对方误认为我们是在指责他，控诉他，从而扭曲了我们原本想表达的意见和建议，造成双方的隔阂，使矛盾激化。问题没解决还破坏了关系，得不偿失啊。\u003c/p>\u003cp>听完后，有没有人觉得这么做太麻烦了，之前虽然会吵架，但是把怨气说出来，一吐为快多舒服啊。事实上，不这么做，更麻烦。因为在类似情况下没用XYZ模型带来的问题更多，包括争吵、误解、冷战、憋屈……总之，“XYZ”模型虽然需要我们做些功课，但是值得。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>就比如说我和我老公吧。\u003c/p>\u003cp>这周一下午三点多，我临时接到一个紧急采访任务，晚上7点之前要交给市领导审稿。我给幼儿园老师发了信息，说晚半个小时去接孩子，随后我给我老公发信息，想让他4点30分去接孩子，结果他的电话一直无人接听，直到下午5点半才给我回消息。这期间，老师多次给我发信息催促我。\u003c/p>\u003cp>当他终于给我回电话的时候，我开始气急败坏了。我说，你这个人怎么这个样，发信息不回，电话给你打了800个了！你这是有多忙啊！你是不是故意的！我下午接到采访，要马上写稿子！孩子没人接！一个多小时了，孩子自己在幼儿园呢！老师总找我！你个破手机能不能调出声音。\u003c/p>\u003cp>听到我说了这些话，老公气急败坏，他说，你这个人真有意思了，你找不到我，不会找别人接孩子啊。你打不通我电话，不知道找我同事吗？你是不是死脑袋，不转个啊。我忙的提溜转，手机一直在办公室没拿出来，你都不听我说话，你凶什么凶！\u003c/p>\u003cp>结果我们闹的挂了对方电话，冷战到晚上。\u003c/p>\u003cp>【正例】\u003c/p>\u003cp>经过这个片段的学习，我在周五的时候遇到这样的情况时，利用了“XYZ”模型进行了表达，我说，亲爱的，下午我因为接不上孩子的事，给你发了信息，想问问你能否接孩子，结果一个多小时你都没有联系我（行为），我和老师商量，在幼儿园多等半个小时，到最后让老师等了一个小时，导致老师加班了。（后果）我感觉非常担心和着急（感受）。\u003c/p>\u003cp>当我说完这段话后，我老公说，奇，我今天下午很忙，我们单位水管破裂，我一直指挥工人在维修，手机在办公室充电没顾得上给你回消息。下次在遇到这样的事，你给维丽发信息，她一般都在。让她告诉我。\u003c/p>\u003cp>这样的沟通方式，不但没有引起矛盾，反而促进了我们相互的理解，增进了感情。\u003c/p>","interaction":"\u003cp>您有没有遇到过这样的情况：\u003c/p>\u003cp>工作一天，你拖着疲惫的身体回到家，一进屋，看到地上铺满了玩具，厨房里堆满了碗筷，孩子自己在看动画片，老公却在屋里玩着游戏，你看到这幅情景，你冲出脑海的第一个念头是什么？就算你想和老公好好沟通，但是脱口而出的会不会是指责？\u003c/p>\u003cp>在工作中，你和同事一起负责策划工作方案。明明都已经敲定了方案，但是同事却不经过你允许，自己擅自更改了。最后的结果差强人意。这样的结果你大为恼火。你会不会只是抱怨一下，或者只是自己吞下了这个苦果？\u003c/p>\u003cp>在和朋友相处中，你的好朋友把你的小秘密分享给很多人听，你发现原来在你不知情的情况下，大家都开始嘲笑你的小秘密。你心中不满，但为了顾及情面，只好自己忍受吗？\u003c/p>\u003cp>请大家回忆一下最近一次错误表达抱怨或者意见的经历，在小组内分享，3分钟时间，然后我们邀请1-2位小伙伴来分享一下。\u003c/p>\u003cp>芒果分享：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 上周三是家长开放日，我们正常下班时间是下午5点。周二需要老师们布置教室，打扫卫生。领导大约5点检查了卫生，已经达标。那天正好是我婆婆生日，我看到检查已经达标，我就准备走了，5点下班，我走的时候是6点半。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;然后我开车走到一半的时候，接到同事电话，被告知，展侧的东西没有标头，王副校长找我，让我赶紧想个标头出来。我说我20分钟回复你。等我到了生日聚会的地点，还没坐下来开始吃饭，这个副校长就给我打电话过来，说，张亚军你怎么走的这么早！明天家长开放日，你们就留了一个人在这里，那些不达标的事谁干！我说，王校长，那边有人。然后这个校长就开始吼叫了起来，并开始骂人。我非常不爽，挂了电话。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 周三，二年级的家长开放日非常成功，但是下了班以后，这个校长不依不饶，找了我又凶了一顿。我态度也非常不好，我和她说，我已经把活干完了，你们的检查也达标了。你要不满意，你爱找谁找谁，我辞职行了吧！别在这里挤兑我！\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;等到了周四，更高一层次的校长又找了我，说，王校长找你的时候，你态度不好，她让你给她道歉。我当时非常生气，我说，我不干了，你们要是这样的话，我就不干了！我内心充满了委屈和愤怒，我用很激烈的情绪和话语表达了不满。\u003c/p>\u003cp>那么现在我们掌握了正确表达抱怨的方法，如果时光可以倒流，回到上一次的情景，你会怎么做呢？在小组内讨论和分享，时间是4分钟。\u003c/p>\u003cp>&nbsp; &nbsp; 芒果分享：\u003c/p>\u003cp>&nbsp; &nbsp; 如果时光可以倒流，再次回到周三家长开放日结束后，副校长找我，指责我，我想我可以这么和她说：\u003c/p>\u003cp>王校长，周二晚上，你给我打电话，对我批评了教育，说我早走，没人干活。今天家长开放日结束，你就昨晚发生的事再次找我谈话（X）我真的很想立马辞职，离开学校。（Y），我感觉非常委屈，感觉很难过（Z），我想我们是不是可以心平气和的，再把当时周二晚上发生的事件捋一下，心情平和的交流一次。\u003c/p>\u003cp>非常感谢芒果的分享。\u003cstrong>看来大家已经学会正确使用\u003c/strong>\u003cstrong>“\u003c/strong>\u003cstrong>表达抱怨\u003c/strong>\u003cstrong>”\u003c/strong>\u003cstrong>了，\u003c/strong>希望大家能主动应用今天学到的内容通过表达感激来建立更多良好的连接。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545695278000,"updated_at":1546468737000,"ria":true},{"id":6252,"topic":"XYZ表达法帮您轻松实现建设性反馈","learn_goal":"学员掌握XYZ表达法的公式，能较好的达到目的，纠正错误","remark":"本书提供了大量的案例以及实践练习的方法，在学习管理技能与应用这些技能之间搭建了桥梁。作者基于在各类企业中对有效管理者的广泛研究，从个人、人际关系和团体三个方面对管理技能进行了全面的探讨。\r\n 　　本书以科学的实证方法提炼管理技能，通过精心设计的问卷和调查提取有关管理成功的关键技能，以大样本实证分析鉴别了十大管理技能——开发自我意识、个人压力管理、创造性和分析性地解决问题、通过支持性沟通建立关系、获得权力和影响力、激励他人、冲突管理、授权与委派、建设有效的团队与团队合作以及领导积极的变革。\r\n 　　本书可供工商管理类专业学生使用，对于公司管理者也有很强的参考价值。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"职场姜文","city":"太原"},"club":{"name":"太原黄河分舵","city":"太原"},"prologue":"分组\r\n拆书帮黄河分舵的各位小伙伴，大家下午好。\r\n首先请允许我做个自我介绍，我的名字叫姜文，姜文的姜，姜文的文，为了让大家更好的了解我，我自己总结了三个标签，标签1：世界500强企业内训师；标签2：拆书帮一级拆书家；标签3：未来的三级拆书家。\r\n为了我们接下来的活动更加高效，我们先分一下小组，在我左手边的两位小伙伴为一组，右手边的这位小伙伴为第二组，我们接下来的凡是以小组进行的活动就按照我们刚刚分好的组进行。\r\n一、学习目标：\r\n 学员在听完今天的内容后，能够掌握XYZ表达法的公式，从而当遇到对别人不满时，能用XYZ表达法替代批评或者指责。\r\n二、图书介绍（1-2分钟）\r\nF 特征（核心是“书”，用于满足好奇心）：\r\n 这本《管理技能开发》是全球最权威的管理技能开发经典著作，经理人员管理技能培养、开发提升的最佳读本。作者是大卫 惠顿，他是杨百翰大学教授，组织领导与战略学院中心主任，曾任学校管理学会主席，康奈尔大学博士。\r\nA 优势（重点是“比较”，用于建立安全感）：\r\n这本书最大的优势就是在书中提供了大量的实践练习，因此是很多MBA课的选修教材。 \r\nB 利益（强调的是“学习者”的利益，用于引发兴趣）\r\n B1: 这本书提供了大量的实践练习、案例以及最新的方法，在学习管理技能与应用这些技能之间搭建了桥梁。换句话说，授人以鱼的同时还能授人以渔。\r\nB2:今天的拆页会帮助我们能够掌握XYZ表达法的公式，从而当遇到对别人不满时，能用XYZ表达法替代批评或者指责。","ratings_count":1,"texts":[{"id":9537,"quote":"\u003cp>\u003cstrong>三、【\u003c/strong>\u003cstrong>R\u003c/strong>\u003cstrong>】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>选自《管理技能开发》P429~430\u003c/strong>\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z.”\u003c/p>\u003col>\u003cli>\u003cp>描述给你带来问题的具体行为（X）这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003c/li>\u003cli>\u003cp>列出这些行为详细的、可见的后果（Y），简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003c/li>\u003cli>\u003cp>描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>\u003c/li>\u003c/ol>","explains":"\u003cp>\u003cstrong>四、【\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】拆书家讲解引导\u003c/strong>（3-4分钟）\u003c/p>\u003cp>\u003cstrong>【WHAT】\u003c/strong>有很多时候，我们都希望通过表达意见或建议使他人发生改变。表达自己的不满是一种典型的情况，教育子女、指导需要改进的下属、开导沉浸在某些事情中无法自拔的朋友……都是如此。这种情况我们在培训中叫负反馈或建设性反馈。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>而当我们抱怨或者提意见的时候，往往会指责对方、揣测对方的意图、夸大严重性。这些表达方式都很难达到目的，甚至起到反作用，引发对方的戒备和反击。因为人在遇到指责的时候，本能反应通常都是自我防御-“我没错，你才错了，你们全家都错了……”\u003c/p>\u003cp>所以也有人因为害怕惹怒对方而不敢表达自己的不满。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>XYZ表达法是非常清晰可操作的方法，能够较好地达到通过表达让对方改变的目的，同时避免那些常犯的错误。具体公式由三部分组成：\u003c/p>\u003cp>1述行为-X\u003c/p>\u003cp>2列后果-Y\u003c/p>\u003cp>3表感受-Z\u003c/p>\u003cp>接下来详细细化一下每个步骤：\u003c/p>\u003cp>\u003cstrong>1述行为-\u003c/strong>\u003c/p>\u003cp>（1）找出对方令你不满的具体行为。\u003c/p>\u003cp>（2）用3W（时间、地点、具体行为）清晰的向对方描述是什么行为令你不满。就像是用摄像机为对方回放行为细节的镜头，而不适合贴标签，通俗的来讲就是把看到的告诉对方，\u003c/p>\u003cp>（3）举例：比如你是单位的领导，某员工经常迟到，你可以描述，你一周上班5天其中有4天都晚到半小时以上。而不是泛泛的说你就是个爱迟到的人。\u003c/p>\u003cp>\u003cstrong>2列后果-\u003c/strong>\u003c/p>\u003cp>（1）罗列出对方行为给你或你们带来的影响。\u003c/p>\u003cp>（2）将带来的影响告诉对方。\u003c/p>\u003cp>（3）举例：比如说你的迟到，导致我们小组在考评中不过关，影响了团队及个人的奖金，等等。\u003c/p>\u003cp>\u003cstrong>3表感受-\u003c/strong>\u003c/p>\u003cp>（1）就是用一些描述情绪的词汇来告诉对方，你此时此刻的感觉和情绪。\u003c/p>\u003cp>（2）我们经常用到表达情绪的词汇有：愤怒，焦虑、担心、着急、不舒服、失望……\u003c/p>\u003cp>其中，XYZ的顺序可依实际情况调整。\u003c/p>\u003cp>接下来给大家两个XYZ表达的例子：\u003c/p>\u003cp>案例1：你说6点钟到这里，却7点多钟才来【X-行为】，\u003c/p>\u003cp>晚饭泡汤了，我们看演出也迟到了【Y-后果】，\u003c/p>\u003cp>我感觉受到了伤害，觉着你不在乎我【Z-感受】\u003c/p>\u003cp>案例2：\u003c/p>\u003cp>我必须告诉你，当你在别人面前拿我的坏记性开玩笑时【X-行为】，\u003c/p>\u003cp>我是多么难堪【Z-感受】，\u003c/p>\u003cp>我气坏了，都想把你的缺点也说出来报复你【Y-后果】\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>适用于建设性反馈的所有情形，\u003c/p>\u003cp>\u003cstrong>【可能的异议】“\u003c/strong>如果我用XYZ方法表达了，对方仍然不认错怎么办？”第一，XYZ表达法的最终目的不是让对方认错，而是让对方愿意改变；第二，如果无效，那就重复使用这种方法直到对方理解。当然，不是说一样的话，而是用不同的XYZ来表达同一个意思。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】促动参与\u003c/strong>（10-15分钟）\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>情境：由于公司的需求发生了变化，原来王经理给下属小孙定义的工作内容不得不重新调整。\u003c/p>\u003cp>新的工作内容没有太大的技术挑战性，同时跟小孙的兴趣点相差比较大。所以小孙在做新安排的工作时抵触心理很强。它在邮件中说了很多抱怨的话。王经理几次分配给他工作，他都推三阻四的。\u003c/p>\u003cp>现在请两人一组进行演练。一个人扮演王经理，你主动找小孙谈话。你用XYZ来表达你对小王最近工作状态的不满。&nbsp;\u003c/p>\u003cp>另外一个人扮演小孙，你要用XYZ表达对王经理之前给你换工作内容的不满。\u003c/p>\u003cp>演练时间3分钟，现在开始。3分钟后，我会选择一位“王经理”和“小王”，大家一起听听他们XYZ是怎么说。\u003c/p>\u003cp>【如下是现场学员角色扮演对话】\u003c/p>\u003cp>王经理：小孙呀，最近工作内容有调整，几次分配给你的工作，你都推三阻四，表示有困难【行为】，我们的工作进展得不太顺利啊【后果】，我真是觉得挺着急的。\u003c/p>\u003cp>小孙：王经理，您看，我是学经济的，您这次调整我跑市场【行为】，就感觉您不重视我，让我觉得很不舒服【感受】，在这样的工作面前，我真是没有干劲【后果】。\u003c/p>\u003cp>通过大家的演练，会发现无论是王经理还是小孙，在刚才的表达中都尝试使用了我们XYZ的公式，大家觉得难不难？\u003c/p>\u003cp>学员：不难。\u003c/p>\u003cp>其实这部分内容表面上直接套公式，好像不难，但真正要用的好，表达效果佳，还需要不断的斟酌一些用词的。\u003c/p>\u003cp>简单总结一下，通过我们的学习，我们学习了XYZ表达法的公式，通过描述对方具体行为带来的后果，同时加上表达出你此时此刻的感受，就可以让对方更有机会接收你的建议。\u003c/p>\u003cp>希望大家在工作和生活中不断的练习，不断的精进，每个人都能成为沟通大师。\u003c/p>\u003cp>我今天的分享就到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1539758813000,"updated_at":1539758813000,"ria":true},{"id":6130,"topic":"用xyz法表达感受","learn_goal":"TF1-1过级","remark":"用xyz三步法表达正确表达感受。","level":"TF1-1","duration":12,"status":30,"type":0,"chaishujia":{"username":"刘犇","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;各位伙伴大家好，我是刘犇，刘是刘备的刘、刘邦的刘，犇是三个牛的犇，牛的勤奋、牛的踏实，犇向美好明天。是一名在教育系统工作8年，目前在机关工作，正走在成长为三级拆书家路上喜欢读书、实践、健身、修行的终身成长者。\r\n &nbsp; &nbsp; &nbsp; 今天我要跟大家拆的这本书叫《管理技能开发》。这本书的作者是大卫·A.惠顿。本书涉及七种基本管理技能：自我意识、问题解决、压力管理、沟通、团队管理、冲突管理和授权。这些技能中有的是职场人士所必须掌握的自我管理和同他人一起工作的基本技能，有的是作为一名合格管理者必须掌握的基本技能。\u003c/p>\u003cp>“拆书”是一种学习方法论，来源于一本书《这样读书就够了》，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心。“拆书学习法” 强调联系学习者的经验，解决学习者的问题，提升学习者的能力。拆书法有供个人学习的便签学习法和供组织学习的由拆书家带领现场学习两种实践形式。个人学习的应用是RIA便签法，R阅读原文，I重述知识，A联系过往经验和设想未来应用，让人读一本书，就能达到参加同主题培训的效果。组织学习的应用是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用，从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>&nbsp; &nbsp;“拆书帮&quot;是基于拆书法的公益性学习爱好者社群。拆书帮分舵的使命是帮助更多学习爱好者成长为拆书家，释放学习促进者的能量。\u003c/p>","ratings_count":1,"texts":[{"id":9390,"quote":"\u003cp>这次要拆的原文片段来自于《管理技能开发（第8版）》429-430页，刚才我已经把原文拆页发给大家了，现在请各位用3分钟的时间阅读一下原文片段。\u003c/p>\u003cp>原文片段：\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>有白天就会有黑夜，有晴朗就会有阴霾，有称赞亦会有抱怨。人际交往中，当别人的行为给自己带来困扰和问题时，就容易出现抱怨。而当我们不去关注客观事实，去评价性的批评与指责，甚至将其泛化到攻击对方的人格和品德时，这种抱怨就会变成情绪的发泄，让对方产生防卫心理或者出现反向抱怨，最终不仅不能使问题得到改善，反而产生更多新的问题。戈登给我们了一个XYZ模型可以帮助我们在表达抱怨时就事不就人，在不伤害别人的前提下，达到精准表达的目的，使问题得到改善。\u003c/p>\u003cp>XYZ模型中X表示行为，Y表示结果，Z表示感受。它的基本句式是：当你做X使得Y，我感到Z。（但是顺序不固定）\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;那么，我们具体该如何做呢？\u003c/p>\u003cp>第一，X描述行为\u003c/p>\u003cp>这要求我们就事不就人，不去评论对方的意图，而是去具体描述对方给你带来问题的行为。比如：你将我的毛巾扔到了地上，就是可能会带来问题的行为，仅去客观描述它就好了，而不要去说你是不是有病？你是不是找茬？\u003c/p>\u003cp>第二，Y列举后果\u003c/p>\u003cp>列举出对方的行为给自己带来的后果。毛巾沾满了灰尘，就是你仍我的毛巾带来的后果。仅说它就可以，而不是去说你不尊重我，你侮辱我。\u003c/p>\u003cp>第三、Z表达感受\u003c/p>\u003cp>向对方表达面对这些后果自己内心的感受。对于毛巾沾满了灰尘这个后果，我的感受是我很伤心。\u003c/p>\u003cp>所以这个完整的句式就是：你把我的毛巾仍到了地上，毛巾沾满了灰尘，我很伤心。\u003c/p>\u003cp>而没有应用XYZ模型的表达可能会是怎么样的呢？\u003c/p>\u003cp>同样看到仍毛巾的情形，可能会说：你是不是有病啊？你是在侮辱我吗？变态！这样的话很可能会因别人不经意的一个举动而爆发一场激烈的冲突。\u003c/p>","interaction":"\u003cp>A1：激活经验\u003c/p>\u003cp>上大学时我是六个人宿舍的宿舍长，我们宿舍有一舍友，他是我们一个系其他专业的，他有一个不好的习惯，就是每天晚上上厕所时都要用力咳嗽、拍手、跺脚，让楼道和厕所的灯保持照明状态。弄得我和宿舍其余4人经常是半夜惊醒，搞得大家怨声载道，大家一致要求我这个宿舍长管管这事。当又有一次我们大家被他惊醒时，我实在是忍无可忍，对着他大声说，你这人太自私了吧，自己胆子小，就搞得那么大声！……结果，之后他晚上的这种行为确实是少了，可是本来就有点内向，和我们沟通较少的他，同我们的隔阂更大了。\u003c/p>\u003cp>&nbsp;现在反思这件事，他确实做得不好，而我作为宿舍长去提醒他也是无可厚非的。但是我在向他表达抱怨时，没有就事论事，直接评价他的人格（胆小）和品德（自私），从而伤害了他的自尊，现在想来当时合适的表达应该是这样的：小双，你晚上去厕所咳嗽、拍手跺脚，大家休息被打搅来向我抱怨，我作为宿舍长真的很为难啊！\u003c/p>\u003cp>A2：催化应用\u003c/p>\u003cp>目标背景：楼上邻居李哥和他的孩子经常在晚上11点甚至12点左右跳绳、做运动，致使在楼下的我们听到“咚咚”的噪音，影响休息。\u003c/p>\u003cp>目标：\u003c/p>\u003cp>下周一周内，楼上邻居再出现“咚咚”的声音时，与其沟通解决。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>用XYZ模型与其沟通。\u003c/p>\u003cp>模拟句式：李哥您好，昨天晚上12点你们在楼上做运动，“咚咚”的声音让我和家人难以入睡，我们感到很烦躁啊！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1537798874000,"updated_at":1537798997000,"ria":true},{"id":6048,"topic":"如何清晰表达抱怨","learn_goal":"学会如何清晰的表达抱怨，让别人了解自己的感受，避免抱怨演变成","remark":"当我们想针对某件事情表达自己的抱怨时，大多数人一开口就是：你总是……,能不能不要总这样……。可想而知对方会怎么回应。本来只是想告诉对方自己很头痛他这样做，希望对方有所改观，结果一开口就变成了指责，对方不但不会改变，还有可能演变成互相指责，将问题复杂化，甚至还可能导致两人的感情破裂。今天教给大家一个表达抱怨的经典句式，让你轻松表达抱怨，增进默契。\r\n","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"七月","city":"昆明市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;各位小伙伴，大家晚上好，我是七月，很开心来到这里挑战二级拆书家。今天给大家带来的拆页选自《管理技能开发》，通过今天的学习，大家将学会如何清晰的表达抱怨，让别人了解自己的感受，避免抱怨演变成指责，影响人际关系。\r\n &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 为方便学习过程中讨论，我们沿用之前的分组。以我为中心，左手为一组，右手为一组。\r\n &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>--------------------------------我是分割线---------------------------------------------\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>首先来介绍一下这本书。\u003c/p>\u003cp>【F】这本书的作者有两位，分别是大卫·A.威坦（David A.Whetten）、金·S.卡梅伦（Kim S. Cameron），它从个人、人际关系和团体三个方面讲解了管理者需要具备的十大管理技能。 \u003c/p>\u003cp>【A】相比市场上大多数的管理类书籍，这本书采用了“评估一学习一分析一练习一应用”五步学习模型讲解每个知识点，通过大量的案例、练习，帮助读者在学习和应用之间搭建了一座桥梁。\u003c/p>\u003cp>【B】如果你已经是团队管理者，有没有这样的经历：一件事说了N遍，下属依然达不到你想要的效果？只是想告诉下属这样做会出问题，结果演变成了对下属的指责，双方很不愉快？如果你是领导重点培养的好苗子，领导是不是经常和你说要多提升管理能力，而你自己却不知道具体怎么做？这本书将会为你们指明方向，提供方法，帮助大家把高大上的管理理论落到实处，获得实在的技能提升。\u003c/p>","ratings_count":1,"texts":[{"id":9294,"quote":"\u003ch2>\u003cstrong>&nbsp; &nbsp; &nbsp; \u003c/strong>&nbsp;今天我分享的主题是：如何有效表达抱怨。来自这本书的第429-430页。请大家花2分钟阅读一下原文，完成后可以举手示意。\u003c/h2>\u003ch2>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;\u003c/strong>大家在阅读时可以想想自己在向别人表达抱怨、提意见时是怎么说的。\u003c/h2>\u003cp>【原文】\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>【简单解释原文】\u003c/p>\u003cp>这个片段给我们讲了一个清晰表达抱怨，避免冲突升级的方法。\u003c/p>\u003cp>【表达抱怨的常见做法】\u003c/p>\u003cp>当我们想针对某件事情表达自己的抱怨时，大多数人一开口就是：你总是……,能不能不要总这样……。可想而知对方会怎么回应。\u003c/p>\u003cp>【这样做的坏处】\u003c/p>\u003cp>本来只是想告诉对方自己很头痛他这样做，希望对方有所改观，结果一开口就变成了指责，对方不但不会改变，还有可能演变成互相指责，将问题复杂化，甚至还可能导致两人的感情破裂。\u003c/p>\u003cp>【拆页的建议How】\u003c/p>\u003cp>今天的片段给我们讲了一个表达抱怨的经典句式，我叫它XYZ模型。即“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。” 具体步骤是这样的：\u003c/p>\u003cp>1.对方做了什么，描述具体行为（X）。\u003c/p>\u003cp>2.你看到了什么，描述具体结果（Y）。\u003c/p>\u003cp>3.你感受到了什么，描述自己的感觉（Z）。\u003c/p>\u003cp>这个顺序是一般常用的步骤，我们也可以根据具体情况变换顺序。注意第1、2步一定要描述具体的行为和结果，避免使用评价性的语言。同时还要注意自己的情绪，不要带有明显的指责语气去抱怨。\u003c/p>\u003cp>【反例】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;举个最常见的夫妻沟通的例子。有一天，老婆想和老公说件事。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;老婆：“哎，我跟你说件事情，就是今天......”，(老公这时正在沙发上葛优躺着玩手机)\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;老婆：“你怎么总是这样，一跟你说话就玩游戏，真是受不了。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;老公 “你说嘛，我听着呢，什么大事”？（大家有没有感觉到老公的话里已经带有明显的不高兴了。）\u003c/p>\u003cp>【正面例子】\u003c/p>\u003cp>我们回到刚才那个例子，如果老婆运用XYZ模型这样说：\u003c/p>\u003cp>“老公，能不能不要每次跟你说话时，你都在玩游戏，这让我觉得，我都没有游戏重要。这让我很难过。如果你能放下手机，专心和我沟通，咱们这个氛围会更和谐。”\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;这样说是不是更好些？\u003c/p>","interaction":"\u003cp>【A1】激活经验（显像提问）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;现在大家了解了表达抱怨的XYZ模型。那么请大家回想一下，曾经你的朋友、同事、爱人有没有总是做什么事情让你很烦恼，你想告诉对方不要这样做了，结果说出来时却让对方觉得你在指责他，反而导致两人关系紧张，变得不愉快了。当时你是怎么和对方抱怨的呢？\u003c/p>\u003cp>我们花2分钟来回想一下，稍后我们请一位小伙伴分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>1.分享者：鹤哥\u003c/p>\u003cp>事件：我们的客户是修理厂，修理的问题一般都比较复杂，经常会有客户将车送来修理，过1-2天后，客户就打来电话来问：“我的车是怎么了，什么情况也没人告诉我？”当听到客户这样说时，我们就会产生抵触情绪，心里就会想这个车本来你就修了很久没有修好，交给我们修又不愿意等，这么不耐烦，要不就开走别修了，要修就摆在这里。\u003c/p>\u003cp>2.分享者：范姐\u003c/p>\u003cp>事件：在给其他单位做辅导时遇到的事情，音控师音乐出现问题，导致主持人要一遍一遍重复，主持人就直接说：”你是猪吗”，音控师就没说话，立马站起来就离开办公室了。当时自己就和主持人沟通了一下，说：”我看到你特别不客气的和别人说，看到你表情也不耐烦，你今天的状态是不是不好，如果继续这样，你和音控师之间产生问题，我们模拟就只能结束了，我们可能连中午饭也没得吃了，这样的状况我也觉得很无力，对于你们的辅导没有意义，你是不是不太想继续进行。\u003c/p>\u003cp>&nbsp; &nbsp; 感谢鹤哥、范姐精彩的分享。\u003c/p>\u003cp>-----------------------------------------------我是分割线----------------------------------------------------------\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>如果我们有大话西游中的月光宝盒，可以让时光倒流，再遇到这样的情况时，我们会如何处理呢？让我们用今天学到的方法，花2分钟时间为自己刚才想到的经历重新设计一套抱怨的说辞。稍后我们请小伙伴来分享一下。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者：范姐\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;如果我是主持人：你连续3次放错音乐，我嗓子不舒服，如果你继续放错音乐，可能我们中午吃饭的时间无法估计，这样的状况让我目前感觉到很烦躁，我现在很着急，我本身压力很大。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;如果我是音控师：你刚才说我是猪，让我觉得你对我意见特别大，我也觉得很不舒服，如果你继续还这样对我，我觉得我们没有办法合作，你可能要换人了，让我觉得合作过程中很压抑，本来很开心的事情现在我觉得很沮丧。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;非常感谢各位小伙伴的分享，今天关于如何清晰表达抱怨的方法，我们就分享到这里。希望接下来大家能够运用这个方法，清晰的说出抱怨，让别人了解我们的感受，增进彼此的默契。最后再次谢谢大家的参与，祝愿我们的拆书之路越走越远。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":9295,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1536720392000,"updated_at":1536720866000,"ria":true},{"id":6013,"topic":"得体表达抱怨或意见","learn_goal":"得体表达抱怨或意见，让对方容易接受","remark":"在我们的工作或生活中，通常我们的抱怨方式可能会是“XXX，你为什么总是这样？”或者“领导老是给我增加工作量，真是烦死了！”这些抱怨方式，很可能会引起对方反感，他也不会去改变原先不好的行为。为了改变这一现状，我们将一起探讨如何得体表达抱怨，让对方更容易接受抱怨或意见，并促使其改变不好的行为。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"苏武林","city":"深圳"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"【自我介绍+图书介绍】\r\n大家好，我叫苏武林，来自湖北荆州。用三个标签介绍我自己。\r\n第一个标签是终身学习者，愿意为了个人发展和适应社会的需要，持续地学习，不断精进。第二个标签是新晋拆书家，想要通过拆书提高自己的能力，目前也正在努力升级打怪中。第三个标签是麦霸，不管是老歌还是新歌，都会一些，所以经常是大家的伴唱。\r\n在我们的工作或生活中，通常我们的抱怨方式可能会是“XXX，你为什么总是这样？”或者“你这样无理取闹，真是烦死了！”这些抱怨方式，很可能会引起对方反感，他也不会去改变原先不好的行为。为了改变这一现状，我们将一起探讨如何得体表达抱怨，让对方更容易接受抱怨或意见，并促使其改变不好的行为。\r\n今天选拆的片段来自《管理技能开发》第八版，作者是大卫•A.惠顿和金•S.卡梅伦，全书主要从个人、人际关系和团队三个方面对管理技能进行了探讨，我们选拆的片段属于人际关系中的冲突管理。\r\n为了方便交流和讨论，我们分一下组，现场有六位学习者，分为两组，坐桌子这边的一组，坐桌子另外一边的一组。\r\n接下来，请大家阅读原文的片段，时间为1分钟，大家阅读完后请举手示意我一下。","ratings_count":1,"texts":[{"id":9253,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，&nbsp; 描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，&nbsp; 列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，&nbsp; 描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。\u003c/p>\u003cp>解释这些感受在怎样干扰你的工作。 我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>好的，因为片段比较简单，我看大家都差不多看完了。大家可以看到，本片段主要是讲述一个“XYZ”模型，该模型结构为“你的X行为，导致了结果Y，给我造成了Z的感觉”。\u003c/p>\u003cp>在我们的工作或生活中，在与家人、朋友、同事、下属等进行沟通时，我们提出我们的意见或抱怨，希望对方改变不好的行为。我们很可能会带着指责的语气，但结果很有可能适得其反，对方很有可能对你的抱怨无动于衷，甚至是反击。而我们今天的“XYZ”模型，一方面可以清楚阐述你的意见，另一方面还能卸下对方的防御心态，促使对方行为发生改变。\u003c/p>\u003cp>那么，我们将“XYZ”模型实际运用的步骤是怎样的呢？\u003c/p>\u003cp>第一，&nbsp; 描述对方的哪些具体行为给你带来了困扰。\u003c/p>\u003cp>第二，&nbsp; 明确告诉对方的这些行为会带来什么样的后果。\u003c/p>\u003cp>第三，&nbsp; 描述你对问题结果的感受。\u003c/p>\u003cp>我分享我的一个案例。上周三，我需要委托下面的技术员测试一些项目，因为那个案子很急，因为他没有及时帮我测试，导致我的任务完成时间延迟了半天，我当时就抱怨他“不是说好了早点完成的吗，怎么拖延那么久。”他当时也没说什么，后面对我的委托也是没有之前那么热心。我反思了一下，我只是表示他给我带来了困扰，既没有说他的行为，也没有说后果和感受。如果回到当时，我会用“XYZ”模型描述，“我委托你的测试项目，你都没有按照需求时间完成，导致我的案子延迟了，其他部门可能会向领导投诉我们，我也是很着急啊。”\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>环节】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>接下来，请大家回忆下，在最近的一周，我们的工作或生活中，你是否向你的家人、朋友、同事或下属，表达你的抱怨或意见？当时你是如何表达的，后面他有没有改变其不好的行为。现在给大家3分钟时间，3人为一组，以小组为单位，在组内分享下各自的经验，3分钟后我会请一位伙伴上台来分享。\u003c/p>\u003cp>\u003cstrong>学习者的分享：\u003c/strong>\u003c/p>\u003cp>我刚才在小组讨论中分享的是工作中的一件事情。在上周三，我想要那位同事周四过来和我见面。她说她没有时间，无法周四过来。后面我们商量了一下，确定是周五过来。到了周五下午三点钟，她还没有过来。我就打电话跟她确认具体几点钟过来。结果她说她忘记了，来不了了，我就感觉到自己没有被尊重。就抱怨她说：“早就跟你约定好的时间，为什么不能来，也不提前打声招呼？”后面她也是一直找借口，处于一种心理防御的姿态，对于后面我们合作也会产生阻碍。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>环节】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>感谢这位小伙伴的分享。\u003c/p>\u003cp>大家想下在未来的一周内，你向你的家人、朋友、同事或下属，表达你的抱怨或意见时，你又会如何应用我们今天分享的“XYZ”模型呢？请大家用1分钟的时间写下自己的目标和行动计划。并思考，你会在什么时间，向谁表达意见，如何用“XYZ”模型表述，达到改变对方行为的目的。3分钟后我会请一位伙伴上台来分享下。\u003c/p>\u003cp>\u003cstrong>学习者的分享：\u003c/strong>\u003c/p>\u003cp>我会用“XYZ”模型这样规划我的行动。因为我的先生颈椎有轻微的劳损，医生建议他每周可以打两次球，通过锻炼可以慢慢调理。我会在这周周日的时候，利用“XYZ”模型，跟他做一次沟通。我会这样跟他说：“从看完医生到今天已经一周了，我观察到你没有按照医生的建议，每周打两次球，你的行为让我担忧，这样会影响你的健康，也影响到我们彼此间的承诺，这可能让我们之间的信任大打折扣。这让我感到非常郁闷，也非常着急。”我也非常希望通过这个方法，得到我先生的正面反馈，让他可以慢慢运动起来。\u003c/p>\u003cp>今天我的拆书到此结束，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1536246821000,"updated_at":1536246821000,"ria":true},{"id":5813,"topic":"如何表达","learn_goal":"有效表达抱怨的方法","remark":" 在生活中，常常听到有人抱怨家庭，抱怨同事，然后抱怨除了给自己带来更大的烦恼外，并不能带来什么好，对解决问题、改善关系没有什么帮助，反而甚至会恶化。在《管理技能开发（第8版）》这本书中，就教给了我们一种有效表达抱怨的方法，谓之曰:“抱怨XYZ 模型”。运用该模型，一方面可以通过描述你在一件事情中做了什么和你的感受是什么来客观表达自己的观点，明确地阐述问题；另一方面也可以避免你自己的情绪过于激动，让事情更加恶化。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"方凯","city":"西安"},"club":{"name":"西安古城分舵","city":"西安"},"prologue":"各位伙伴们，大家好，我叫方凯。大家可以叫我小方，现在我的身份是一名准医生，我给自己的三个标签分别是：准医生，志愿者，拆书小白，准医生是自己将来要从事的职业方向；志愿者是自己在大学时光中一直扮演的角色，也期望以后能够在公益这方面有所建树；拆书小白是自己现阶段的状态。我希望通过这三个标签来提醒自己现在和未来将要做的事情，让自己成为一个更好的人。平时爱好读书、打球、跑步。向往的理想状态是：有三两好友，拼搏奋斗，一生足以。现目前最大的愿望是在不久的将来通过自己的努力成为一名三级拆书家。接下来就开始我们今天的拆书之旅了。","ratings_count":1,"texts":[{"id":9022,"quote":"\u003cp>接下来让我们阅读原文片段，这个片段选自《管理技能开发》，作者是大卫·A.威坦，原文片段：戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>　　我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语\u003c/p>","explains":"\u003cp>\u003cstrong>拆书和拆书帮介绍：\u003c/strong>在座的各位有第一次来参加拆书活动的吗？请举手！好，新来的伙伴，可能不了解拆书帮和拆书是什么，现在我给大家做一个简单的介绍。\u003c/p>\u003cp>首先我先来说下拆书，“拆书”是一套学习方法论，是一种以解决问题为导向的成人学习方式,强调以学习者为中心，一定要学以致用，改变行为。 拆书分为两种学习，个人学习拆书法和组织学习拆书法。 \u003c/p>\u003cp>第一种：个人拆书法主要是运用便签阅读法RIA，通过一本书的片段结合自身经验并落实到具体行之有效的行动中。\u003c/p>\u003cp>什么是RIA便签呢？\u003c/p>\u003cp>RIA便签法介绍：\u003c/p>\u003cp>这个读书发放分为三步，第一步R，也就是阅读原文，I是用自己的话对原文进行重述，第三步A，又分为A1和A2L两部分，A1是面向过去的经验，A2是面向未来的生活。以前我们在读书之后可能读过就忘记了，RIA便签法给我们提供一种“学以致用”的方法，，既联系过往生活经验，又探究书中知识能在未来给我们的具体帮助和应用，真正做到把书中知识拆为己用。在接下来的拆书中，我将运用RIA便签读书法给大家讲解原文拆页。\u003c/p>\u003cp>&nbsp; &nbsp;另一种是组织拆书，是由一位拆书家通过对一本书的拆解，引领大家共同学习、分享，化书本中知识为自己能力的过程。 拆书帮，是一个社群，一个开放的学习型组织，在全国各地以分舵的形式存在。这是一个互相尊重、互相支持、轻松愉悦的学习社群。拆书帮的成员都是爱学习、爱家人、爱朋友的充满活力一族。\u003c/p>\u003cp>\u003cstrong>I：\u003c/strong>&nbsp;在生活中，常常听到有人抱怨家庭，抱怨同事，然后抱怨除了给自己带来更大的烦恼外，并不能带来什么好，对解决问题、改善关系没有什么帮助，反而甚至会恶化。在《管理技能开发（第8版）》这本书中，就教给了我们一种有效表达抱怨的方法，谓之曰:“抱怨XYZ 模型”。运用该模型，一方面可以通过描述你在一件事情中做了什么和你的感受是什么来客观表达自己的观点，明确地阐述问题；另一方面也可以避免你自己的情绪过于激动，让事情更加恶化。该模型主要包括三步：\u003c/p>\u003cp>1.X（行为）:描述引起你抱怨的具体行为。尽量客观、具体，不要加入主观的评价或过于笼统，比如：“朋友，你在上班时间又在打游戏了并且发出很大的声音。”；\u003c/p>\u003cp>2.Y（后果):列出由于X 行为带来的后果。后果也尽量客观，但有时也可以是经过合理推测的可能结果，比如：“这样可能会打扰到正在工作的其他同事”；\u003c/p>\u003cp>3.Z（感受）:描述自己基于Y 结果而产生的负面感受。可以引申表达出这些负面的感受给自己的生活、工作带来的消极影响，比如：“我在听到你打游戏发出的声音的时候，会让我无法安心工作，从而导致我工作出现错误。”\u003c/p>\u003cp>当我们遇到别人的不当行为给我们带来情绪影响时，都可以运用“XYZ模型”来表达抱怨，但有三点请注意：一是三个顺序可以调换；二是要分清别人的行为是否“不当”，有时情绪是我们的误解所致；三是抱怨毕竟是一种非友好地沟通形式，所以还要慎用，否则容易给人留下“他是一个爱抱怨的人”的印象。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>上周周五在和同事交接工作的时候，我在很认真和缓慢地说工作的事情的时候，他在用手机查资料，在我说话的时候，他一边查资料一边回复我说嗯嗯，我知道了。我觉得他这种行为很不好，我们就产生了很不愉快的对话：\u003c/p>\u003cp>我：你为什么不听我说话\u003c/p>\u003cp>他：我在听呀\u003c/p>\u003cp>我：你明明就在忙你手头的事情，你没空你可以说呀，我可以等你呀，你这样是想干撒.\u003c/p>\u003cp>然后我就把交接的东西放他桌子上，我就走了。\u003c/p>\u003cp>&nbsp;\u003cstrong> A2：\u003c/strong>\u003c/p>\u003cp>1.目标： 今晚找同事说下我对这件事的感受以及以后怎么做。\u003c/p>\u003cp>2.行动\u003c/p>\u003cp>（１）先表达一下歉意：“我上周的事情做的很不对，我在此表示歉意，希望你不要介意。”\u003c/p>\u003cp>（２）然后描述事实：“在上周的这件事情里，在我和你交接工作的事情，你在忙你手头上的事情”\u003c/p>\u003cp>（３）表达感受：“我心里很不舒服，我觉得你这样是不尊重我。”\u003c/p>\u003cp>（４）阐述结果：“如果以后经常这样的话，我们彼此的工作可能就没法开展，我们的关系也会变得很差”\u003c/p>\u003cp>（５）说明需要：“在我和你交接工作的时候，希望你尊重我，能好好听我说话”\u003c/p>\u003cp>（６）提出请求：在下一次我讲话的时候，希望你能放下手头上的工作，一心听我说话，可以吗？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1534334749000,"updated_at":1534334749000,"ria":true},{"id":5484,"topic":"如何有效表达抱怨","learn_goal":"完成TF1-1拆书练级","remark":"当别人的行为给自己的情绪带来影响时，我们往往倾向于通过抱怨表达不满，本次拆页片段就向我们提出了一个有效表达抱怨的模型—“XYZ”模型。即：\r\nX：描述带来问题的具体行为；\r\nY：列出该行为带来的详细、可见的后果；\r\nZ：描述你对该结果的感受。","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"风清扬S","city":"大连"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好！我是郭峰。我来自一家从事海运物流行业的企业，从事人力资源管理工作。我的三个标签是：一名HR老兵，一个初级培训师，一位读书爱好者。今年初偶然的机会接触到《这样读书就够了》这本书，并连续参加了2期训练营，从今天开始正式向三级拆书家的目标进发。很高兴认识大家，希望与大家共同交流、进步，谢谢。\r\n下面我要先介绍一下拆书法和拆书帮。\r\n“拆书法”是著名的培训和教育专家，赵周老师在其著作《这样读书就够了》这本书中提出来的，是一套专门针对成人的拥有知识版权的学习方法论，其特点是以学习者为中心，而不是传统的以知识为中心。所谓“拆”，是指的转化和内化，即强调将书中的知识通过关联经验、规划应用转化为自己的能力。\r\n它包括个人学习的“RIA便签读书法”和组织学习的“现场学习法”。\r\n1、RIA便签读书法：所谓“R”就是仔细阅读所选取的片段；“I”是在一张便签上用你自己的语言写出对片段中知识点的理解；“A”分为“A1”和“A2”：“A1”是结合原文片段中的知识点，在便签上写出你以前的成功或失败的经历，具体描述时间、地点、起因、过程等要素，如能写出自己的感悟和反思就更好；“A2”便签用来根据片段知识点写出具体的行动计划，要包括具体的目标、时间节点、行动步骤、监督机制等等。同时，设定的目标一定要符合SMART原则。\r\n2、现场学习法。由拆书家带领大家就一本书进行现场学习，通过拆出知识点（I），和一系列引导技巧，促动大家将知识拆为己用。\r\n下面我来介绍一下拆书帮。\r\n“拆书帮”是一个由拆书法的爱好者组成的非盈利社群组织。总舵在北京，在全国各地建有40多个分舵和若干筹备分舵，是一个真正的成长型社群。我们大连的筹备分舵目前也正在积极筹建当中，相信通过我们的努力，大连分舵很快就会成立。","ratings_count":0,"texts":[{"id":8653,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>　　我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语\u003c/p>","explains":"\u003cp>生活中的抱怨比比皆是，可这些抱怨除了引起对方内心的反感和更强烈的反驳之外，对解决问题、改善关系有什么好处呢？答案是NO！那么难道我们有了不满情绪就不能抱怨了么？当然不是，在《管理技能开发（第8版）》这本书中，就教给了我们一种有效表达抱怨的方法，谓之曰:“抱怨XYZ 模型”。运用该模型，一方面可以通过描述行为而避免过度宣泄情绪，激发对方反感，造成双方对立，另一方面也可以让投诉更聚焦产生情绪的行为，从而以解决问题为导向。该模型主要包括三步（顺序可以变换）：\u003cbr>\u003c/p>\u003cp>1.X（行为）:描述引起你抱怨的具体行为。尽量客观、具体，不要加入主观的评价或过于笼统，比如：“宝贝，刚才你又在地板上‘咚咚咚’的来回跑了”；\u003c/p>\u003cp>2.Y（后果):列出由于X 行为带来的后果。后果也尽量客观，但有时也可以是经过合理推测的可能结果，比如：“待会楼下的邻居可能又要上来投诉了”；\u003c/p>\u003cp>3.Z（感受）:描述自己基于Y 结果而产生的负面感受。可以引申表达出这些负面的感受给自己的生活、工作带来的消极影响，比如：“邻居来投诉妈妈要一直说抱歉，而且已经不是第一次了，这真的让妈妈感到很尴尬和沮丧。”\u003c/p>\u003cp>当我们遇到别人的不当行为给我们带来情绪影响时，都可以运用“XYZ模型”来表达抱怨，但有三点请注意：一是三个顺序可以调换；二是要分清别人的行为是否“不当”，有时情绪是我们的误解所致；三是抱怨毕竟是一种非友好地沟通形式，所以还要慎用，否则容易给人留下“他是一个爱抱怨的人”的印象。\u003c/p>\u003cp>&nbsp; &nbsp; 同时，通过观察我们可以发现，“XYZ模型”与非暴力沟通四要素很相似，这源于抱怨也是沟通的一种，只不过“XYZ”仅相当于“观察、感受”两个要素。为了让抱怨产生积极作用，我们也可以继续运用后两个要素，即“需求、请求”，以期产生实质地改变。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>上周妻子给孩子买了几十本书籍，希望培养孩子阅读习惯，提高认字能力。昨晚看到这些书都没有拆封，我们的睡前谈话就这样开始了：\u003c/p>\u003cp>我：“那些书还没给孩子做阅读计划么?”\u003c/p>\u003cp>妻：“等你呢”\u003c/p>\u003cp>我：“我这一天这么忙，哪有时间啊，既然都是你买的，你就做一下呗，而且书都是你买的，你自然都是有计划和想法的”\u003c/p>\u003cp>妻：“我也忙啊，孩子也不是我自己的” \u003c/p>\u003cp>就这样，一场谈话演变成对抗，结果自然不欢而散，转头，背对背睡觉。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>1.目标： 今晚就昨天未达成共识的孩子读书计划一事再沟通一次，先有效表达抱怨，再寻求解决办法。\u003c/p>\u003cp>2.行动\u003c/p>\u003cp>（１）先表达一下赞扬：“亲爱的，前几天你给孩子买的书我都过了一遍，都不错，很适合她现在的成长阶段，而且对她养成习惯、增加认字水平也很有好处，你怎么想的？今天同事还聊孩子读书的事呢，明天我也跟他们说说”\u003c/p>\u003cp>（２）然后描述事实：“不过昨天咱俩也说过了，这书可放了好多天了，孩子还一本没打开看呢”\u003c/p>\u003cp>（３）表达感受：“我很担心”\u003c/p>\u003cp>（４）阐述结果：“这样下去，孩子就会觉得读书这事没那么重要，或者咱们给她做了一个拖沓、执行力差的示范，这样不是跟我们帮她养成好习惯的初衷背离了么，你说呢？”\u003c/p>\u003cp>（５）说明需要：“咱们还是应该用行动带动孩子去做对的事，帮助她养成及时行动、爱阅读的好习惯”\u003c/p>\u003cp>（６）提出请求：这样吧，咱俩今晚推掉所有事，晚饭收拾后，一起给他制订阅读计划，今晚就开始行动，怎么样？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1531113667000,"updated_at":1531113667000,"ria":true},{"id":5483,"topic":"如何有效表达抱怨（郭峰）","learn_goal":"完成TF1-1拆书过级练习","remark":"当别人的行为给自己的情绪带来影响时，我们往往倾向于通过抱怨表达不满，本次拆页片段就向我们提出了一个有效表达抱怨的模型—“XYZ”模型。即：\r\nX：描述带来问题的具体行为；\r\nY：列出该行为带来的详细、可见的后果；\r\nZ：描述你对该结果的感受。","level":"TF1-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"风清扬S","city":"大连"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>开场： 大家好！我是郭峰。我来自一家从事海运物流行业的企业，从事人力资源管理工作。我的三个标签是：一名HR老兵，一个初级培训师，一位读书爱好者。今年初偶然的机会接触到《这样读书就够了》这本书，并连续参加了2期训练营，从今天开始正式向三级拆书家的目标进发。很高兴认识大家，希望与大家共同交流、进步，谢谢。\u003cbr>下面我要先介绍一下拆书法和拆书帮。\u003cbr>“拆书法”是著名的培训和教育专家，赵周老师在其著作《这样读书就够了》这本书中提出来的，是一套专门针对成人的拥有知识版权的学习方法论，其特点是以学习者为中心，而不是传统的以知识为中心。所谓“拆”，是指的转化和内化，即强调将书中的知识通过关联经验、规划应用转化为自己的能力。\u003cbr>它包括个人学习的“RIA便签读书法”和组织学习的“现场学习法”。\u003cbr>1、RIA便签读书法：所谓“R”就是仔细阅读所选取的片段；“I”是在一张便签上用你自己的语言写出对片段中知识点的理解；“A”分为“A1”和“A2”：“A1”是结合原文片段中的知识点，在便签上写出你以前的成功或失败的经历，具体描述时间、地点、起因、过程等要素，如能写出自己的感悟和反思就更好；“A2”便签用来根据片段知识点写出具体的行动计划，要包括具体的目标、时间节点、行动步骤、监督机制等等。同时，设定的目标一定要符合SMART原则。\u003cbr>2、现场学习法。由拆书家带领大家就一本书进行现场学习，通过拆出知识点（I），和一系列引导技巧，促动大家将知识拆为己用。\u003cbr>下面我来介绍一下拆书帮。\u003cbr>“拆书帮”是一个由拆书法的爱好者组成的非盈利社群组织。总舵在北京，在全国各地建有40多个分舵和若干筹备分舵，是一个真正的成长型社群。我们大连的筹备分舵目前也正在积极筹建当中，相信通过我们的努力，大连分舵很快就会成立。\u003c/p>","ratings_count":1,"texts":[{"id":8654,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>　　我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语\u003c/p>","explains":"\u003cp>生活中的抱怨比比皆是，可这些抱怨除了引起对方内心的反感和更强烈的反驳之外，对解决问题、改善关系有什么好处呢？答案是NO！那么难道我们有了不满情绪就不能抱怨了么？当然不是，在《管理技能开发（第8版）》这本书中，就教给了我们一种有效表达抱怨的方法，谓之曰:“抱怨XYZ 模型”。运用该模型，一方面可以通过描述行为而避免过度宣泄情绪，激发对方反感，造成双方对立，另一方面也可以让投诉更聚焦产生情绪的行为，从而以解决问题为导向。该模型主要包括三步（顺序可以变换）：\u003cbr>\u003c/p>\u003cp>1.X（行为）:描述引起你抱怨的具体行为。尽量客观、具体，不要加入主观的评价或过于笼统，比如：“宝贝，刚才你又在地板上‘咚咚咚’的来回跑了”；\u003c/p>\u003cp>2.Y（后果):列出由于X 行为带来的后果。后果也尽量客观，但有时也可以是经过合理推测的可能结果，比如：“待会楼下的邻居可能又要上来投诉了”；\u003c/p>\u003cp>3.Z（感受）:描述自己基于Y 结果而产生的负面感受。可以引申表达出这些负面的感受给自己的生活、工作带来的消极影响，比如：“邻居来投诉妈妈要一直说抱歉，而且已经不是第一次了，这真的让妈妈感到很尴尬和沮丧。”\u003c/p>\u003cp>当我们遇到别人的不当行为给我们带来情绪影响时，都可以运用“XYZ模型”来表达抱怨，但有三点请注意：一是三个顺序可以调换；二是要分清别人的行为是否“不当”，有时情绪是我们的误解所致；三是抱怨毕竟是一种非友好地沟通形式，所以还要慎用，否则容易给人留下“他是一个爱抱怨的人”的印象。\u003c/p>\u003cp>&nbsp; &nbsp; 同时，通过观察我们可以发现，“XYZ模型”与非暴力沟通四要素很相似，这源于抱怨也是沟通的一种，只不过“XYZ”仅相当于“观察、感受”两个要素。为了让抱怨产生积极作用，我们也可以继续运用后两个要素，即“需求、请求”，以期产生实质地改变。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>\u003c/p>\u003cp>上周妻子给孩子买了几十本书籍，希望培养孩子阅读习惯，提高认字能力。昨晚看到这些书都没有拆封，我们的睡前谈话就这样开始了：\u003c/p>\u003cp>我：“那些书还没给孩子做阅读计划么?”\u003c/p>\u003cp>妻：“等你呢”\u003c/p>\u003cp>我：“我这一天这么忙，哪有时间啊，既然都是你买的，你就做一下呗，而且书都是你买的，你自然都是有计划和想法的”\u003c/p>\u003cp>妻：“我也忙啊，孩子也不是我自己的”\u003c/p>\u003cp>就这样，一场谈话演变成对抗，结果自然不欢而散，转头，背对背睡觉。\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp;\u003cstrong>A2：\u003c/strong>\u003c/p>\u003cp>1.目标： 今晚就昨天未达成共识的孩子读书计划一事再沟通一次，先有效表达抱怨，再寻求解决办法。\u003c/p>\u003cp>2.行动\u003c/p>\u003cp>（１）先表达一下赞扬：“亲爱的，前几天你给孩子买的书我都过了一遍，都不错，很适合她现在的成长阶段，而且对她养成习惯、增加认字水平也很有好处，你怎么想的？今天同事还聊孩子读书的事呢，明天我也跟他们说说”\u003c/p>\u003cp>（２）然后描述事实：“不过昨天咱俩也说过了，这书可放了好多天了，孩子还一本没打开看呢”\u003c/p>\u003cp>（３）表达感受：“我很担心”\u003c/p>\u003cp>（４）阐述结果：“这样下去，孩子就会觉得读书这事没那么重要，或者咱们给她做了一个拖沓、执行力差的示范，这样不是跟我们帮她养成好习惯的初衷背离了么，你说呢？”\u003c/p>\u003cp>（５）说明需要：“咱们还是应该用行动带动孩子去做对的事，帮助她养成及时行动、爱阅读的好习惯”\u003c/p>\u003cp>（６）提出请求：这样吧，咱俩今晚推掉所有事，晚饭收拾后，一起给他制订阅读计划，今晚就开始行动，怎么样？\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1531110050000,"updated_at":1531113914000,"ria":true},{"id":5068,"topic":"如何有效阐述你的问题","learn_goal":"学会使用XYZ表达法来表达自己的不满","remark":"","level":"TF1-1","duration":10,"status":0,"type":0,"chaishujia":{"username":"十八","city":"南宁"},"club":{"name":"南宁老友分舵","city":"南宁"},"prologue":"大家下午好，我叫做十八，欢迎大家来到我的TF1-1拆书练级现场，我用三个标签介绍自己：第一个标签是视觉笔记，相信大家入群的伙伴都看到元宝发的一张“老友新人入群流程”图，那个就是我画的，视觉笔记让我的记录更有趣更生动；第二个标签是尤克里里，虽然我目前只是一个会两首曲子的小白，但是我今年的目标就是学会尤克里里；第三个标签是马拉松，我是一位马拉松爱好者，在去年的时候参加了桂林龙脊的越野马拉松和南马的全马，马拉松让我的身体更健康～总之我是元气满满十八，很高兴认识大家。\r\n这一两年拆书帮在南宁兴起，我们老友分舵队伍也是日益壮大，很多新加入的朋友都会问：“拆书帮是什么？”其实拆书帮是成人自发学习组织，它是以学习者为中心，让学习者把知识拆为自己的能力。我们通过RIA拆书法把书本看到的觉得有用的知识联系自己过往的实际经验内化它（这就是A1便签），然后再用A2便签去应用它，A1/A2便签我们都提供了标准，让学习者更容易的去参考与学习。第二个方法就是组织学习法的应用，就是一位拆书家拿一本书加工出一场现场学习／引导和促进一群人把知识拆为己用，其实就像此刻大家来参加我的TF1-1拆书练级场一样。拆书帮有自","ratings_count":0,"texts":[{"id":8170,"quote":"\u003cp>《管理技能开发（第8版）》，摘录自429～430页\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我们在与他人沟通的时候，是否会存在这样的疑惑：为什么我说出来的话别人没法get到那个点？自己说的明明不是这个意思，却偏偏事与愿违，这往往会加剧我们人际关系的紧张，譬如当父母对我们说：“你怎么一点都不听话，我不喜欢你了！”当我们听到这样的话时候，我们会觉得父母真的不喜欢我们了；领导说：“这件事怎么做这么久？大学生这点执行力都没有吗？”当我们听到这样的话时候，我们会觉得自己很挫败，其实我们会发现这样的表达不利于事情的解决，而且容易激化矛盾。XYZ模型很有效的帮助我们解决这个问题：\u003c/p>\u003cp>X:先描述具体行为，比如你与一位朋友相约，你朋友迟到了，你可以先说出这一件事情的具体行为就是：你晚到了20分钟\u003c/p>\u003cp>Y:接下来讲述由X行为带来的结果：所以我们错过电影开场时间\u003c/p>\u003cp>Z：最后说由Y结果给我们带来的感受：错过了电影开场我觉得很遗憾。\u003c/p>\u003cp>所以XYZ模型可以帮助我们提供一个交流的模型／步骤，让我们更好的解决与他人的矛盾。\u003c/p>\u003cp>接下来我举一个工作中的例子来说明一下XYZ模型。\u003c/p>","interaction":"\u003cp>A1便签：\u003c/p>\u003cp>我是一名财务，与同事打交道最多的就是报账。本周2的时候同事A和我抱怨：“为什么报账流程这么繁杂！我就是想要把我自己垫付的钱报账拿回来而已，需要的手续流程和报账附件怎么会那么多！拿回自己的钱怎么就那么难！”\u003cbr>\u003c/p>\u003cp>我认为我的同事对于报账应该是很熟悉的了，因为报账是每个月都会做的事情，而且报账不通过时因为报账单据的错误才会导致报账钱款无法及时到账。同时，我听到这样的话语很生气，情绪立马上来，所以我就对同事说:“我也没求着你们报账啊，你可以不报账呀！”结果就是我同事生气的走掉，还说要和领导说我服务基层意识一点都不强！\u003c/p>\u003cp>在这段对话里，我没有描述具体行为X，具体行为X会带来的后果Y,以及感受Z，对话陷入了无意义的争吵。\u003c/p>\u003cp>A2便签：\u003c/p>\u003cp>接下来的一周，我知道同事A还会来报账，所以我打算运用XYZ模型主动解决我和同事A报账问题，我会这样说：\u003c/p>\u003cp>X是上周2的时候你和我抱怨说报账流程繁杂。\u003c/p>\u003cp>Y是我们两个都会因此无法很好的沟通，也没有能够很好的解决你的报账问题。\u003c/p>\u003cp>Z是因为你这样抱怨，我会很难受。\u003c/p>\u003cp>讲清楚事实和我们的个人感受，而不是一味的宣泄我们情绪和指责，能让我们更冷静的处理我们于他人的关系。\u003c/p>\u003cp>本片段虽然来自于是管理技能的片段，但是大家也可以运用到各种的沟通环境中，跟父母或者家人产生矛盾的时候，就可以实用XYZ的表达模型了，非常实用哦。谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8171,"quote":"\u003cp>《管理技能开发（第8版）》，摘录自429～430页\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我们在与他人沟通的时候，是否会存在这样的疑惑：为什么我说出来的话别人没法get到那个点？自己说的明明不是这个意思，却偏偏事与愿违，这往往会加剧我们人际关系的紧张，譬如当父母对我们说：“你怎么一点都不听话，我不喜欢你了！”当我们听到这样的话时候，我们会觉得父母真的不喜欢我们了；领导说：“这件事怎么做这么久？大学生这点执行力都没有吗？”当我们听到这样的话时候，我们会觉得自己很挫败，其实我们会发现这样的表达不利于事情的解决，而且容易激化矛盾。XYZ模型很有效的帮助我们解决这个问题：\u003c/p>\u003cp>X:先描述具体行为，比如你与一位朋友相约，你朋友迟到了，你可以先说出这一件事情的具体行为就是：你晚到了20分钟\u003c/p>\u003cp>Y:接下来讲述由X行为带来的结果：所以我们错过电影开场时间\u003c/p>\u003cp>Z：最后说由Y结果给我们带来的感受：错过了电影开场我觉得很遗憾。\u003c/p>\u003cp>所以XYZ模型可以帮助我们提供一个交流的模型／步骤，让我们更好的解决与他人的矛盾。\u003c/p>\u003cp>接下来我举一个工作中的例子来说明一下XYZ模型。\u003c/p>","interaction":"\u003cp>A1便签：\u003c/p>\u003cp>我是一名财务，与同事打交道最多的就是报账。本周2的时候同事A和我抱怨：“为什么报账流程这么繁杂！我就是想要把我自己垫付的钱报账拿回来而已，需要的手续流程和报账附件怎么会那么多！拿回自己的钱怎么就那么难！”\u003cbr>\u003c/p>\u003cp>我认为我的同事对于报账应该是很熟悉的了，因为报账是每个月都会做的事情，而且报账不通过时因为报账单据的错误才会导致报账钱款无法及时到账。同时，我听到这样的话语很生气，情绪立马上来，所以我就对同事说:“我也没求着你们报账啊，你可以不报账呀！”结果就是我同事生气的走掉，还说要和领导说我服务基层意识一点都不强！\u003c/p>\u003cp>在这段对话里，我没有描述具体行为X，具体行为X会带来的后果Y,以及感受Z，对话陷入了无意义的争吵。\u003c/p>\u003cp>A2便签：\u003c/p>\u003cp>接下来的一周，我知道同事A还会来报账，所以我打算运用XYZ模型主动解决我和同事A报账问题，我会这样说：\u003c/p>\u003cp>X是上周2的时候你和我抱怨说报账流程繁杂。\u003c/p>\u003cp>Y是我们两个都会因此无法很好的沟通，也没有能够很好的解决你的报账问题。\u003c/p>\u003cp>Z是因为你这样抱怨，我会很难受。\u003c/p>\u003cp>讲清楚事实和我们的个人感受，而不是一味的宣泄我们情绪和指责，能让我们更冷静的处理我们于他人的关系。\u003c/p>\u003cp>本片段虽然来自于是管理技能的片段，但是大家也可以运用到各种的沟通环境中，跟父母或者家人产生矛盾的时候，就可以实用XYZ的表达模型了，非常实用哦。谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8172,"quote":"\u003cp>《管理技能开发（第8版）》，摘录自429～430页\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我们在与他人沟通的时候，是否会存在这样的疑惑：为什么我说出来的话别人没法get到那个点？自己说的明明不是这个意思，却偏偏事与愿违，这往往会加剧我们人际关系的紧张，譬如当父母对我们说：“你怎么一点都不听话，我不喜欢你了！”当我们听到这样的话时候，我们会觉得父母真的不喜欢我们了；领导说：“这件事怎么做这么久？大学生这点执行力都没有吗？”当我们听到这样的话时候，我们会觉得自己很挫败，其实我们会发现这样的表达不利于事情的解决，而且容易激化矛盾。XYZ模型很有效的帮助我们解决这个问题：\u003c/p>\u003cp>X:先描述具体行为，比如你与一位朋友相约，你朋友迟到了，你可以先说出这一件事情的具体行为就是：你晚到了20分钟\u003c/p>\u003cp>Y:接下来讲述由X行为带来的结果：所以我们错过电影开场时间\u003c/p>\u003cp>Z：最后说由Y结果给我们带来的感受：错过了电影开场我觉得很遗憾。\u003c/p>\u003cp>所以XYZ模型可以帮助我们提供一个交流的模型／步骤，让我们更好的解决与他人的矛盾。\u003c/p>\u003cp>接下来我举一个工作中的例子来说明一下XYZ模型。\u003c/p>","interaction":"\u003cp>A1便签：\u003c/p>\u003cp>我是一名财务，与同事打交道最多的就是报账。本周2的时候同事A和我抱怨：“为什么报账流程这么繁杂！我就是想要把我自己垫付的钱报账拿回来而已，需要的手续流程和报账附件怎么会那么多！拿回自己的钱怎么就那么难！”\u003cbr>\u003c/p>\u003cp>我认为我的同事对于报账应该是很熟悉的了，因为报账是每个月都会做的事情，而且报账不通过时因为报账单据的错误才会导致报账钱款无法及时到账。同时，我听到这样的话语很生气，情绪立马上来，所以我就对同事说:“我也没求着你们报账啊，你可以不报账呀！”结果就是我同事生气的走掉，还说要和领导说我服务基层意识一点都不强！\u003c/p>\u003cp>在这段对话里，我没有描述具体行为X，具体行为X会带来的后果Y,以及感受Z，对话陷入了无意义的争吵。\u003c/p>\u003cp>A2便签：\u003c/p>\u003cp>接下来的一周，我知道同事A还会来报账，所以我打算运用XYZ模型主动解决我和同事A报账问题，我会这样说：\u003c/p>\u003cp>X是上周2的时候你和我抱怨说报账流程繁杂。\u003c/p>\u003cp>Y是我们两个都会因此无法很好的沟通，也没有能够很好的解决你的报账问题。\u003c/p>\u003cp>Z是因为你这样抱怨，我会很难受。\u003c/p>\u003cp>讲清楚事实和我们的个人感受，而不是一味的宣泄我们情绪和指责，能让我们更冷静的处理我们于他人的关系。\u003c/p>\u003cp>本片段虽然来自于是管理技能的片段，但是大家也可以运用到各种的沟通环境中，跟父母或者家人产生矛盾的时候，就可以实用XYZ的表达模型了，非常实用哦。谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1525185340000,"updated_at":1525185367000,"ria":true},{"id":5063,"topic":"运用XYZ模型快速有效沟通","learn_goal":"现场学习后，学习者能够运用XYZ模型在任何场景进行有效沟通","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"唐思","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"自我介绍 \r\n大家好，我叫唐思，大家可以叫我七七，因为在武汉话中”七“跟”吃“同音，所以可以看出我是一名吃货。我是在商业地产行业做招商工作的，经常需要跟人打交道，良好的沟通的技巧可以帮助我的工作，而且拆书帮致用的读书方法可以让我在繁忙工作中迅速get到一个技巧，团体的拆书氛围让我学会更深入的聆听和观察。个人对心理学书籍、培训技巧感兴趣，未来将读更多此类书籍，希望能拆为己用，也能帮到他人。\r\n拆书帮介绍 \r\n拆书帮是一个自学习的公益性组织，其使命是帮助更多学习爱好者成为拆书家，目前全国有55个分舵，我们所在的分舵就是武汉珞珈分舵。\r\n所谓拆书法就是RIA便签读书法，适用于提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验，规划具体的运用。RIA分别代表三个英文单词，R代表阅读，即阅读的原文拆页内容，I代表拆书家对原文知识的拆解和对现场人员的引导，A代表拆为己用，有三种作为，A1激活学习者过去的经验，A2催化学习者运用，A3是现场演练，分别指向过去和未来及当下，在每一场拆书活动中，大家都可以通过以上三个步骤完成一场对自己的主题培训，也可以进","ratings_count":1,"texts":[{"id":8165,"quote":"\u003cp>《管理技能开发（第8版）》，摘录自429~430页，第三章第二节：问题解决的原理和方法\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>有时候我们在跟他人沟通的时候，有时出于不同立场，有可能带会产生争吵，常常会指责别人或者发泄情绪，比如我们经常听到父母这样说“你怎么这么不听话，我不喜欢你了……”，或者领导说“他做事太拖沓，一点执行力都没有！“这样的表达往往容易挑起对方的反击，不仅不利于事情解决，而且容易激化矛盾。\u003c/p>\u003cp>XYZ模型，很有效地帮我们解决了这个问题：\u003c/p>\u003cp>1.首先描述X，指描述带来问题的具体行为，比如“变天了，你没有适时的加衣服”的行为，基于客观、具体的描述；\u003c/p>\u003cp>2.接下来讲述Y，指这些行为带来的后果，接上面：“结果你感冒了”，这是直观的后果；\u003c/p>\u003cp>3.最后表明你的感受Z，指因以上的后果产生的感受，如你感冒了“这件事让我很担心”，是基于以发生的事实而产生的感受，有事实依据。\u003c/p>\u003cp>接下来我举一个工作中的例子来说明一下XYZ模型。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>领导A跟我的私人关系很不错，但是呢又经常因为工作上的问题控制不住脾气而发货，每次都导致我很郁闷，上个月，领导A因为我没有给她的材料走审批流程对我突然发难，所以我也一如往常的想表达我的想法。\u003c/p>\u003cp>领导A：为什么不帮我走协议签批流程？……（噼里啪啦说了一堆）\u003c/p>\u003cp>我也有点火：能不能先别激动，协议需要先过会，但这份协议没有上会审批，就直接走流程肯定的是有问题的……\u003c/p>\u003cp>她转头很生气的走了，而我也没把话说完。\u003c/p>\u003cp>在这段对话里，我描述了具体行为X仅仅是你太激动了，协议是要先上会的，但是没有表述后果Y和感受Z，对话集中在发生的事情本身，没有讲清楚事情她发火和我的感受的关系。\u003c/p>\u003cp>A1+: 如果下次碰到类似领导突然发火，我会运用XYZ法则这样沟通：\u003c/p>\u003cp>我：X是你突然生气，Y是导致我都不知道到底发生了什么事情，也不知道接下来怎么处理和推进，Z是其实我也有点懵，你这样对我发火我感到有点伤心。\u003c/p>\u003cp>通过层层递进讲清楚前因后果，而且是基于事实的说法，相信她可以因此了解我的想法和感受，从而理性沟通。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>接下来的一周，我打算运营XYZ法则，解决我和朋友的沟通，我有一个很好的朋友，突然发现看不到她的朋友圈了，发现原来是她把我给屏蔽了，但其他的朋友却没有，我可以用XYZ原则给朋友打一个电话：\u003c/p>\u003cp>X是我发现你朋友圈把我屏蔽了；\u003c/p>\u003cp>Y是我没办法了解你的近况；\u003c/p>\u003cp>Z是我其实很关心你，但你这样做让我很难过。\u003c/p>\u003cp>讲清楚事实和我的感受，而不是一味地指责，会更冷静的处理好我们的关系。\u003c/p>\u003cp>本片段虽然来自于是管理技能的片段，但是大家也可以运用到各种的沟通环境中，跟父母或者家人产生矛盾的时候，就可以实用XYZ的表达模型了，非常实用哦。谢谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1524968753000,"updated_at":1524968753000,"ria":true},{"id":4916,"topic":"  如何做才能让忠言不再逆耳","learn_goal":"掌握描述性沟通的三个步骤，让忠言不再逆耳","remark":"","level":"TF2-3","duration":20,"status":29,"type":0,"chaishujia":{"username":"宋福珍（豆豆）","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"各位小伙伴，早上好，我是你的老朋友，致力于终身学习，但又有点小拖延的豆豆。这一年，我致力于拆书练级，拆出自己的管理技能，拆出新的竞争力，感谢大家来到今天的拆书现场，接下来我们采用分组方式学习，请大家按照就近原则，4人一组。好的，谢谢大家。通过今天的学习，大家在今后遇见需要给别人进行负面反馈或者提建议的时候，能够遵循和按照描述性沟通方式，分三个步骤提出建议，增进彼此之间的关系。","ratings_count":2,"texts":[{"id":7994,"quote":"\u003cp>《管理技能开发》第九版第216页\u003c/p>\u003cp>描述性沟通涉及三个步骤：\u003c/p>\u003cp>第一，尽可能客观地描述发生的事件或需要改正的行为。尽量客观、不带倾向性地谈论所发生的一切而不是所涉及的人。这个描述应该确认具体的行为要素，在其他人看来这些行为应该是可以被证实的。行为应该与大家都接受的标准进行比较，而不是与个人的观点或偏好进行比较。应避免对其他人的动机的主观印象和归因。诸如“这个月你比同一个部门中其他人完成的项目少”的描述，就能够被证实（可以利用客观的记录），他们与观察到的行为或客观标准相关，而不是人们的动机或个人特点有关。由于对行为没有评价式的标签，也没有针对人的攻击，其他人感到被不公平对待的可能性就很小，与评价一个人行为相比，描述一个行为的做法是相对中立的。\u003c/p>\u003cp>第二，描述你自己或其他人对行为或其结果的反应。与其把问题的缘由投射到别人，不如将焦点放在行为产生的反应和后果上。这要求沟通的人要意识到自己的反应，还要能描述这些反应。用一个词对情绪进行描述，常常是最好的方法：“我很担心你的生产效率。”“你的业绩水平使我失望。”同样也可以指出行为的结果：“这个月的利润没有达标部门的质量评定很低”或“你的意见导致其他人停工了”。\u003c/p>\u003cp>由于对问题的描述是建立在你的感受或客观结果的框架中，而不是在其他人特性的框架中，描述感受和结果也可以降低防御的可能性。如果那些感受和结果不是一种谴责的方式进行描述的，沟通的主要精力就能放在问题的解决上，而非对评价的防御上。也就是说，如果 &nbsp; “我”非常关心，那么“你”就更不应该觉得受到了冒犯。\u003c/p>\u003cp>第三，提出一个更容易被接受的选择。即关注对所提方案，而不是对个人的讨论，由于个体与行为分割开来，这有助于保留别人的面子，让对方觉得人格没有受到诋毁。人的自尊受到了保护，因为需要改变的是某些可以控制的事情，而不是整个人。\u003c/p>","explains":"\u003cp>【F】首先，我来介绍一下管理技能开发这本书，这是一本工商管理专业的本科或MBA教材。作者是两位美国人，他们调研了世界上400多位卓有成效的领导者，采用科学实证分析方法，甄选出了10大管理技能，覆盖个人、人际关系和团体三个方面，包括了沟通、时间和压力管理，个体决策管理，发现、界定和解决问题；激励和影响他人；授权目标设置和阐明愿景；自我意识；团队建设以及冲突管理等，普遍适用的技能。\u003c/p>\u003cp>【A】这本书是迄今为止最全面最系统的一本介绍和教授管理技能的书籍，全书600多页，跟砖头一样厚，很多人都难以耐心读下去，但这本书兼顾了理论和实操，而且更注重教会读者学会书中所给出的管理技能，在每章中作者都是遵循五步骤的学习模型，帮助读者进行管理/领导技能的评估、学习、分析、练习与应用。除了上述特点，这本书还区别了管理技能和领导技能，管理不只是对组织或机构的管理，还是对行为的管理，包括对自己的时间、压力、人际关系等，由此作者说这本书也可以改名为生活技能开发。\u003c/p>\u003cp>【B】B1虽然读起来费劲，但学习并掌握其中的技能，能够帮助大家更好的提升自己的沟通能力，管理自己的人际关系，帮助自己更好的经营事业，更好的经营友情，亲情，爱情，收获更加美好的人生。B2通过学习并掌握描述性沟通，让大家在今后遇见需要给别人进行负面反馈或者提建议，在给别人指出缺点的时候，遵照描述性沟通的三个步骤进行反馈，能大家更好的维护你们之间的关系。\u003c/p>\u003cp>\u003cstrong>【常见错误及后果】\u003c/strong>首先请大家来回忆一下，在自己以往的经历中，有没有需要向别人反馈对方有不良业绩、否决对方的提议或要求，或者纠正问题行为、接受别人的批评，或者面对其他消极的相互交流的时候，就我自己而言，前几天我跟闺女一大早就吵架了，当时是我早上我正坐在凳子上穿鞋子，我闺女着急上学，一把就把我薅起来了。我当时可恼火了：你怎么这么粗鲁？你不能好好跟我说话啊？真没礼貌，不讲文明！结果呢，我闺女粗声粗气的回我：你自己迟到了也要害我迟到吗？我赶时间。然后我们就陷入了你赶时间你可以跟我说，你赶时间你就可以不礼貌不尊重妈妈的死循环了。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>学习了这个片段之后，我总算明白了，为什么以前我的做法会让我们进入僵局，是因为我一张口就是评价，给她的行为贴上了不好的标签，这让闺女感觉到了被指责，所以她本能的进入了防御，为自己的行为进行辩解，导致了更多的争执、不满和消极应付，最终结果是母慈子孝瞬间碎成了渣。\u003cstrong>【适用边界】\u003c/strong>所以作者提出了在需要向对方反馈负面信息，否定对方意见或拒绝要求，或者是纠正对方行为及其他消极的沟通时，我们要采用描述性沟通的方式进行。原文拆页里面第一步和第二步共同点都是客观的描述，第一是描述客观事实，第二部是描述自己的反应或者行为可能的后果，原文拆页里面说的比较清晰，在这里我重点来给大家强调一下第三步，关注问题的解决方案。这一步是经常会被大家忽略，不知道怎么做才能提出更容易接受的建议，\u003cstrong>【细化原文第三步的行动步骤】\u003c/strong>其实要做到给出对方能够接受的建议，我们可以通过以下3个小步骤来实现：首先，要有意识的提醒自己避免陷入谁对谁错的争执，争执会引发防御和冲突，这一步是帮助自己整理思路，明确沟通目的；其次，提帮助对方发现效解决问题的资源或者理清障碍建议；最后，鼓励对方提出更多的解决办法。举个例子，用描述性沟通的方法来纠正孩子冲我吼叫，第一步描述事实是：我正穿鞋，你不打招呼就拉我；第二部描述反应和可能的后果：我被吓了一条，脱口就会指责你，这样下去我们两个肯定会吵架；第三步，关注问题解决方案：你想要我给你让位的话，你可以如果你赶时间的话，你可以请我站起来或者去拿另外一个凳子，或者你也可以想想其他办法。昨天我在练习的时候呢，我跟孩子这么一说，孩子立马回复了我一句，对啊，我还可以去其他地方穿鞋子啊，真不知道我当时就犯什么傻。\u003c/p>\u003cp>\u003cstrong>【适用范围】\u003c/strong>描述性沟通不仅适用于片段中所指的工作环境，也适用于我们的一般生活中，需要指出对方缺点或者作出负向反馈的时候。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>即便我按照上面的描述性沟通的步骤做了，对方一定会改善吗？不一定。这个时候，撕逼死路一条，我们继续用描述性沟通就是：1、陈述事实——听到你这么说，我很意外；2、描述可能的后果：我担心我自己会控制不住我自己，我们两个冲突会升级；3、提出建议：我建议我们在晚上你放学后找个时间深入的聊一聊。只要你是真诚的来鼓励对方发展与改进，很少人会不接受这种真诚、和谐的措辞。相对于因为评价而导致关系决裂，描述性沟通帮我们指出了一条既能给出负面反馈，又能表达我们对对方的关心，有利于双方关系发展的模式。\u003c/p>\u003cp>为了帮助大家更好的牢记三个步骤，我总结了三个步骤以及几个要点，请看\u003c/p>","interaction":"\u003cp>刚刚，我们学习了描述性沟通的三个步骤，了解了什么时候可以用描述性沟通，以及描述性沟通会对我们关系改善带来的好处，我给大家一个场景，我们现场练习用描述性沟通的步骤与对方进行沟通。\u003c/p>\u003cp>周五下午，你收到学校校讯通短信，你发现本周末孩子的作业比平时多了2份卷子，平时孩子作业用一个半小时就能完成，今天加上卷子至少需要两个半小时。6点多晚饭的时候你跟孩子约好了晚上七点开始写作业，这样就能在十点前写完，不影响明天早点出发带孩子去看动物园。现在已经是晚上七点半了，孩子爸爸催促了孩子好几次，孩子现在很烦躁，爸爸又提醒孩子作业的时候，孩子冲爸爸发火：你烦不烦，是你写作业还是我写作业？大不了我明天不去了。然后摔门回房了，孩子爸爸也很生气。现在，请作为妈妈的你，采用描述性沟通的方式，与孩子进行沟通，想一想按照三个步骤你要如何措辞。请大家在小组内进行讨论，时间5分钟。稍后我们会选择两位小伙伴，现场分别扮演妈妈和孩子，展示他们用描述性沟通的步骤来进行沟通的过程。\u003c/p>\u003cp>【讨论中的互动】深入一组有新学员的小组，在他们讨论的过程中，对第三步提出建议的部分，进行了深度互动，这里面要明确自己的沟通目的，是关注孩子的作业，还是关注孩子对爸爸的态度，或者是都有。\u003c/p>\u003cp>案例，针对作业\u003c/p>\u003cp>妈妈：儿子，咱们说好是7点开始写作业，现在是七点半了\u003cstrong>（描述事实）\u003c/strong>，我担心影响作业太晚你起不来影响明天去动物园\u003cstrong>（描述行为的后果）\u003c/strong>。你明天还想不想去动物园呢？\u003c/p>\u003cp>儿子：想。\u003c/p>\u003cp>妈妈：那我们现在要不要今天晚上把作业写完呢？\u003cstrong>（提出建议）\u003c/strong>\u003c/p>\u003cp>儿子：可是作业有点多，我害怕写不完\u003c/p>\u003cp>妈妈：就是因为作业多，才要早点开始写啊，那你是现在开始写呢，还是明天早上起来再写呢？\u003cstrong>（再次提出建议）\u003c/strong>\u003c/p>\u003cp>儿子：那我还是现在开始写吧。\u003cbr>\u003c/p>\u003cp>案例，针对态度（小组讨论中，未进行现场演示）\u003c/p>\u003cp>妈妈：我看到爸爸催你了好几次，你刚刚很大声的冲爸爸喊叫，还很大声的关上门，你生气了，爸爸在沙发上也很生气\u003cstrong>（描述事实）\u003c/strong>\u003c/p>\u003cp>妈妈：我看到你冲爸爸喊叫，你们两个都很生气，我觉得很难过，也很着急\u003cstrong>（描述孩子行为给自己带来的感受）\u003c/strong>。我希望你知道爸爸催促你是因为爱你，即便你不高兴，但是也不可以用这样的方式来表达，我建议等你平静的时候，出去给爸爸道歉。\u003cstrong>（提出建议）\u003c/strong>\u003cbr>\u003c/p>\u003cp>结尾：描述性沟通最重要的是在给出负向反馈的时候，既能让我们不违心，又不至于损害彼此之间的关系，希望大家在今后的工作和生活中，多多练习，熟练运用，让我们的人际关系变得越来越和谐，祝大家的工作、生活顺心如意。今天的拆书到到此结束，感谢大家的参与。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522222464000,"updated_at":1525503474000,"ria":true},{"id":4457,"topic":"有效阐述问题的XYZ模型","learn_goal":"通过本次学习，学员能够使用XYZ模型表达不满、意愿和期望等。","remark":"很多时候，我们会表达自己的不满、意愿和期望等，希望对方能够理解我们，或者按照我们所希望的去做某项行为动作。比如说，老板天天下班前交给你任务，然后要求第二天早上就要给他。老公天天在外应酬，很晚回家。孩子在你忙着处理工作邮件的时候突然跑进来，非要你给他买个和隔壁邻居家小孩一样的玩具。生活中会出现各种各样的问题，你会怎么应对呢？你会直接对老板说，天天加班累死了，老子不干了么？你会在老公回家的时候不给好脸色，甚至数落他不顾家里，然后独自抹眼泪么？你会不耐烦地吼小孩，让他晚点再来找你么？\r\n这个拆页告诉我们，遇到这样的问题后，如何有效阐述？","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"彭丽娟","city":"广州"},"club":{"name":"广州零角度分舵","city":"广州"},"prologue":"很多时候，我们会表达自己的不满、意愿和期望等，希望对方能够理解我们，或者按照我们所希望的去做某项行为动作。比如说，老板天天下班前交给你任务，然后要求第二天早上就要给他。老公天天在外应酬，很晚回家。孩子在你忙着处理工作邮件的时候突然跑进来，非要你给他买个和隔壁邻居家小孩一样的玩具。生活中会出现各种各样的问题，你会怎么应对呢？你会直接对老板说，天天加班累死了，老子不干了么？你会在老公回家的时候不给好脸色，甚至数落他不顾家里，然后独自抹眼泪么？你会不耐烦地吼小孩，让他晚点再来找你么？\r\n这个拆页告诉我们，遇到这样的问题后，如何有效阐述？","ratings_count":0,"texts":[{"id":7470,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>这个拆页描述了一个帮我们有效阐述问题的模型。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 很多时候，我们会表达自己的不满、意愿和期望等，希望对方能够理解我们，或者按照我们所希望的去做某项行为动作。比如说，老板天天下班前交给你任务，然后要求第二天早上就要给他。老公天天在外应酬，很晚回家。孩子在你忙着处理工作邮件的时候突然跑进来，非要你给他买个和隔壁邻居家小孩一样的玩具。生活中会出现各种各样的问题，你会怎么应对呢？你会直接对老板说，天天加班累死了，老子不干了么？你会在老公回家的时候不给好脸色，甚至数落他不顾家里，然后独自抹眼泪么？你会不耐烦地吼小孩，让他晚点再来找你么？\u003c/p>\u003cp>这个拆页告诉我们，遇到这样的问题后，如何有效阐述？\u003c/p>\u003cp>第一，客观具体描述是什么样的行为导致了问题，这个是X。以第一个例子来讲，是老板每天在快下班的时候交给你任务，要求第二天早上给他。\u003c/p>\u003cp>第二，这些行为导致了什么样的后果，列出来，简单明白告诉对方，这个是Y。还是以第一个例子来讲，老板的行为让你每天都需要加班加点干活，精力耗费多，晚上睡眠少，身心俱疲。\u003c/p>\u003cp>第三，对于这个后果，也是问题，你有什么样的感受，描述出来，这个是Z，让对方不仅仅是了解他的哪些行为给你造成了困扰，而且要让他明白，这些行为给你带来了怎样的挫败感、愤怒感或者不安全感等不良情绪。以第一个例子来讲，是你觉得深深的无力感，对生活和工作都没有了兴趣和信心。\u003c/p>\u003cp>XYZ的表达方式连起来就是：&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>老板，你每天在快下班的时候交给我任务，并要求我第二天就给你，我需要每天都加班加点干活，这导致我身心俱疲，感觉到了深深的无力感，对生活和工作都失去了兴趣和信心。\u003c/p>\u003cp>当然，XYZ表达法可以适当调整顺序，也可以先说Z，再说XY。比如，我最近感觉到了深深的无力感，对生活和工作都失去了兴趣和信心。这是因为，老板你每天到了快下班的时候交给我任务，并要求我第二天早上就给你。我只好每天都加班加点干活，这导致我身心俱疲。\u003c/p>","interaction":"\u003cp>A1：现在和大家分享一下我过往的相关经历。\u003c/p>\u003cp>昨天和男朋友闹矛盾。不知道什么缘故，他两天都没有给我打电话，我给他发的消息也是简单回答“恩”“哦”，我很委屈，忍不住给他打了一个电话，开口就是：“你是不是都把我忘记了？你一点都不关心我。”他急切反问，我怎么不关心你？我最近这不是忙么。你的消息我还是有回啊，怎么算把你忘记呢。”我还是很生气，一场吵架开始了。\u003c/p>\u003cp>A2：现在和大家分享一下我的未来行动计划。\u003c/p>\u003cp>（1）今晚，和男朋友打电话，使用XYZ的方式再重述一遍问题：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 亲爱的，你这两天都没有给打电话，我发消息给你也只是简单的“恩”，“哦”，我老忍不住想你到底在做什么，这让我有点心思不宁，感觉到你好忙，似乎没有多少时间和我沟通，我有点失落。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; （2）同时，在本周，遇到因为对方的缘故导致的问题或情绪时，我用XYZ的方法阐述问题。记录至少两次使用情境，并且用不同的顺序去改写。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515837952000,"updated_at":1515837952000,"ria":true},{"id":4219,"topic":"XYZ模型减少沟通冲突","learn_goal":"学会模型解决实际的问题","remark":"","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"张文静（天后）","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"大家好，我是天后。我是一个拆书新手，也是一个心理学爱好者，我希望我可以用拆书的方式去求知，用读心的态度去生活。\r\n今天我给大家分享的片段来源于《管理技能开发》这本书。这本书讲述了十大通过科学的实证方法得出来的管理技能，比如开发自我意识、压力管理和幸福管理、创造性和分析性地解决问题、通过支持性沟通建立关系、激励他人等等。我选的这个片段，在第九版《管理技能开发》的第351-352页。现在我们就一起学习一下这个用于沟通的XYZ模型。\r\n学习之前我们先进行一下分组，左边一组，右边一组。","ratings_count":0,"texts":[{"id":7202,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 现在请大家用1min时间阅读原文拆页。\u003c/p>\u003cp>\u003cstrong>&nbsp;XYZ模型\u003c/strong>\u003cbr>\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果丫，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）。重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我看大家已经都阅读完毕了。\u003c/p>\u003cp>XYZ模型是个阐述问题的模型。当我们需要给别人反馈，或者向别人提出建议时，就可以运用XYZ模型去表达我们的观点，这样做的好处是可以有效的避免我们带着一种批判、质疑、评价的态度去沟通，可以减少我们去别人发生语言冲突的概率。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;现在我们来看一下这个模型。\u003c/p>\u003cp>X:描述问题的具体行为。在这一步要注意事实的描述不可泛泛而谈，要有具体行为描述做支撑。\u003c/p>\u003cp>Y:列出详细的可见的后果。就是这个问题给你带来的后果是什么？\u003c/p>\u003cp>Z:描述你对问题结果的感受。这里要强调一点，我们要表达的是感受，那什么是感受呢？比如，你不爱我了，这是感受吗？不是，这是你对事情的一个看法、对别人做法的一种判断，你不爱我，我很痛苦，痛苦是一种感受。兴奋、欣慰、幸福、悲伤、沮丧、愤怒，这些词是感受。所以我们在表达是要想一下，你说的是感受还是看法。\u003c/p>\u003cp>那这个模型一定要按XYZ的顺序来描述吗？不一定吧，模型的顺序变化是可以调整的，比如：先讲感受，然后再说具体的事情和后果。而且根据我们谈话的对象不同，可以着重强调其中一个部分。如果对象是领导，我们可能会倾向于说后果，如果对象是家人，可以多说一下感受。\u003c/p>\u003cp>举个例子。我做了一个工程，因为电缆井、电缆沟等问题，施工方反复提了三次变更，到最后自己都说不清楚他们要哪个版本的变更。这种反复的无效工作，我其实挺生气。那按照这个XYZ模型，我怎么表达呢。\u003c/p>\u003cp>&nbsp; &nbsp; 我会说这个工程因为电缆沟的问题改了一次图，因为排管无法施工改了第二次图，又因为电缆沟尺寸改了第三次图，这其中还有推翻之前材料量改的其他部分。这是我对事实的描述，也是具体的问题。然后我开始讲后果，这个工程反复改图，改到最后我们双方都做了很多无用的工作，耗费时间和精力，技经也很反感我不停的修改概算，以后的工作会更不好推进，影响项目整体进度。最后描述我对问题的感受，这让我觉得很心烦，很郁闷。\u003c/p>","interaction":"\u003cp>我对拆页的讲解就先到这里。现在请大家想一想有没有过类似的经历，比如，领导给你安排了一项工作，做完以后，因为方案调整，你白忙活了，而这已经不是第一次。你很想就这个问题去找领导谈谈。比如，你在家打扫卫生，刚收拾完，你老公随手又把遥控器不知道扔到哪里了，你顿时火冒三丈，想把此刻的情绪表达出来。现在给大家5分钟的时间，请大家回想一下，在工作或者生活中，有没有在表述问题的时候因为方式或者情绪不得当，导致沟通失败了。然后按照刚才的分组，小组内讨论，最后推选一位小伙伴跟大家分享他的经历。\u003c/p>\u003cp>学习者分享经验：\u003c/p>\u003cp>鱼小刺：老公每天一回到家，就是躺在沙发上扣手机，我都快要生了，还要打扫卫生、做饭，他说他每天下班按时回家带孩子，也很尽职了。我就很生气，跟他吵，这种陪孩子的方式是低质量的。\u003c/p>\u003cp>豆豆：我妈妈生病住院，我们商量以后只有我大姐有时间全天陪护。大姐本来是同意的，但是来了以后，三番五次找各种理由要回去，我一听就跟她吵起来了，“这都是说好的事，你怎么说变就变”，结果我说完我姐就哭了。\u003c/p>\u003cp>谢谢鱼小刺和豆豆的分享。\u003c/p>\u003cp>现在请大家回顾一下刚才所讲的XYZ模型的三个步骤：描述问题的具体行为、列出详细的可见的后果、描述你对问题结果的感受。再想一想，未来一周或者一个月以内，在生活或者工作中，你有没有需要跟别人主动沟通的问题。然后按照这三个步骤，在便签纸上写下你的XYZ。要注意不要写成泛泛而谈，要具体可行。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>豆小燃：在工作中，我有个下属提交文章总是达不到我的要求，下周又要提交文章了，我需要找他谈谈。我会这么说：“你的文章写的不符合我们公司的模板要求，校核那边不会通过，需要重写，而且发布的时间会推迟，我很担心。”\u003c/p>\u003cp>&nbsp; &nbsp; 我们总是说纸上得来终觉浅，绝知此事要A2。希望大家以后遇到需要沟通的问题时可以想到并运用XYZ模型。以上就是今天我为大家分享的内容，谢谢大家的参与和支持。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1512977267000,"updated_at":1512977267000,"ria":true},{"id":3704,"topic":"通过拆书家，学习者将了解如何使用有效的问题阐述模","learn_goal":"解如何使用有效的问题阐述模型","remark":"本书以科学的实证方法提炼管理技能，通过精心设计的问卷和调查提取有关管理成功的关键技能，以大样本实证分析鉴别了十大管理技能。本书从个人、人际关系和团体技能三个方面对管理技能进行了全面的探讨。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"微粒","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"Hello，大家好。我是微粒，今天我们来拆解的片段来选自于《管理技能开发》这本书。在开始之前，为了加深大家对我的了解，我来做一个自我介绍。\r\n【自我介绍】\r\n三个标签： \r\n1.拆书帮追随者，我从去年有幸加入拆书帮就对他痴迷，一发不可收拾。\r\n2.狮子座，狮子座有一个特点，就是热情与执着，正是因为这个特点，让我对于拆书帮的爱绵延不绝。\r\n3.保险，我从事的行业是保险行业，一个富于责任与大爱的行业。","ratings_count":0,"texts":[{"id":6615,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时导致结果Y，而我的感觉是Z。”\u003c/p>\u003cp>第一，描述你带来问题的具体行为（X）。这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的、可见的后果（Y）。简单明白地告诉对方，其行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受（Z）重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或者不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>（\u003cstrong>假设情景- Why\u003c/strong>）\u003c/p>\u003cp>好的，感谢大家的积极配合。刚刚大家阅读了原文片段，文中提到一个有效阐述问题的模型。而在我们日常生活、工作当中，当我们遇到问题需要与别人进行沟通时，是不是时常会出现这样的场景对话：“喂，你怎么这样，因为你，现在成了这样了局面……”或者是“都怪XX，要不是他，也不会成这样……”等诸如此类满腹抱怨的对话，不仅不能解决问题，反而会让双方关系变得紧张，问题的解决形成僵局。那我们该如何有效阐述我们的问题，使得双方沟通更加畅通，并且能把事件陈述清楚呢？\u003c/p>\u003cp>（\u003cstrong>How\u003c/strong>）\u003c/p>\u003cp>文中给大家提供了有效阐述问题模型即“当你做了X时导致结果Y，而我的感觉是Z。”为了方便大家理解，我们可以分步来实施：\u003c/p>\u003cp>首先：“当你做了X时”即阐述造成问题的\u003cstrong>行为\u003c/strong>，以事实为依据，提升事实可信度。（比如我在上周打扫家中卫生的时候，不小心打破了窗台的花瓶。打破花瓶这是一个以事实为依据的行为。）\u003c/p>\u003cp>其次：“导致结果Y”则是列出因上述行为所造成的详尽的后果，这个后果是直观的，可以见到的。（就如我打破了花瓶这一行为直接后果造成花瓶碎了，家中少了一个美观的装饰品。） \u003c/p>\u003cp>第三：“我的感受Z”即说出因此结果导致的自己情绪变化，而这些情绪对自己的影响。（打破花瓶这件事让我心情很沮丧，甚至一整天心情都很低落。）\u003c/p>\u003cp>通过以上阐述问题模型，可以让双方在问题事实的基础上展开有效沟通，运用此方法将减少因模糊事实与评价性反馈所带来的激烈情绪。\u003c/p>\u003cp>同时需要说明此有效阐述问题模型我们在运用过程中可以根据所在环境与情况调整沟通顺序，以适应真实场景的不同需求。\u003c/p>","interaction":"\u003cp>为了大家更好的理解此模型的运用，接下来我给大家举个自己的案例：\u003c/p>\u003cp>\u003cstrong>A1\u003c/strong>\u003cstrong>：\u003c/strong>一个半月前，事件的起因源于一次我与B部门甲同事共同处理一个合规问题件。我作为责任方需要提供相关涉及销售误导人员的入职及销售资料，甲同事负责整理、并按照文件要求对资料进行系统录入以便合规部门后续处理。但因这位同事疏忽，造成我部收集的材料原件被这位同事遗失。对此我十分生气，对他说“你这么不用心，做什么合规管理员”。说完后感觉很后悔，因为这样并不能解决问题，还使得双方处于了僵持，不利于工作开展。\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>：运用上述方法，对于甲的工作失误我可以这样阐述：\u003c/p>\u003cp>目前状况是这样的，由于你将违规者唯一一份销售资料丢失，使得我们失去了一份对于此合规件非常有利的证明材料\u003cstrong>（行为）\u003c/strong>，目前其他材料对于此违规者的证明力度大大减弱，造成涉嫌销售误导行为可能不成立。\u003cstrong>（结果）\u003c/strong>这样的结果令我们感到很遗憾， 不能将其绳之以法。\u003cstrong>（感受）\u003c/strong>\u003c/p>\u003cp>这样表述的语气更为平和，陈述事实也会让对方直观感受到影响程度。\u003c/p>\u003cp>【A2】接下来我的行动目标\u003c/p>\u003cp>\u003cstrong>行动时间\u003c/strong>：一个月\u003c/p>\u003cp>\u003cstrong>行动目的\u003c/strong>：运用此方法陈述问题\u003c/p>\u003cp>\u003cstrong>行动内容\u003c/strong>：背景：6月12日，按照公司规定时间，我将培训回执上报给负责的老师。但是当参训人员去培训的时候发现没有他的名字。因为培训负责老师的疏忽，造成参训人员没有被安排住宿，桌牌，参训工牌也都没有准备。参训人员对我说他很失望。\u003c/p>\u003cp>运用阐述问题模型将此问题与培训负责老师进行沟通：\u003c/p>\u003cp>我有一件事情想跟您沟通下，在6月12日的培训中，我们有一名新人参训时没有工牌与胸牌，也没有拿到新人培训资料，我在给您报送的培训名单中是有这个新人，但经查阅当时的培训交接表却没有此人。\u003cstrong>（行为）\u003c/strong>新人回来告诉我们他很失望，感到没有受重视，于是离开了这里。\u003cstrong>（结果）\u003c/strong>这个结果让我很痛心，尤其在现在留人难的阶段，由于工作中失误，让我们失去了一名新人。\u003cstrong>（感受）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>行动监督\u003c/strong>：在工作和生活中分别记录出现问题后，运用此方法并记录使用频次与效果。\u003c/p>\u003cp>将阐述的效果根据表达进行评估，并总结改进进而进一步提高自身表达能力和沟通能力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1505835398000,"updated_at":1505835398000,"ria":true},{"id":2975,"topic":"树安二次拆书","learn_goal":"通过1-2","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"谦谦有理","city":"重庆市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是谦谦有理，巩树安。一个新手拆书家。目前是一家金融公司HR，今天给大家带来的书籍是《管理技能开发》。这本书是工商管理经典译丛里面的其中一本书，这本书更多的是以科学的实证方法体验管理技能。调查了400多位有经验的高校管理者，通过问卷调查中间的关于成功的关键技能。中间抽出了很多实用性的技能来提升阅读者，这本书对于咱们个人的成长和学习有很大的一个帮助。我今天拆解的是这本书第429-430页。如何表达抱怨，这个事情是如何表达的更好一些的。","ratings_count":0,"texts":[{"id":5776,"quote":"\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时,导致的结果Y，而我的感觉是Z”\u003c/p>\u003cp>第一，描述给你带来问题的具体行为“X”，这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答的倾向。\u003c/p>\u003cp>第二，列出这些行为详细的可见的后果“Y”。简单明白的告诉对方，即行为给你带来的问题，通常是使他们发生改变的有效刺激。\u003c/p>\u003cp>第三，描述你对问题结果的感受最“Z”。最重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释他如何通过给你带来挫折、愤怒或不安全等感受来影响你。解释这些感受是怎样干扰你的工作。\u003c/p>\u003cp>我们建议你把这三部模型作为一般性的指导来使用，每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003c/p>","explains":"\u003cp>我们在正常与他人沟通的时候经常会有自己的情绪需要表达，比如抱怨，比如气愤，比如开心。很多人是直接把情绪抒发出来，引得很多人不满。作者给大家提供了一些好的方法。我先带大家来看一下原文：作者给了一个模型，这个模型就是：我有一个问题，当你去做X的时候，产生的结果Y,而给我这边的影响和感受是Z。第一描述给你带来问题的一个具体的行为，有助于你在给予反馈的时候避免直接评价，因为很少有人能直接安之若素的接受其他人的指责。跟一个人去沟通，或者抱怨的时候，你直接说出你的一个观点或者直接将自己的回答抛出。给人的一个感觉就是他可能会有抵触的情绪。很难再进行下一步的沟通。\u003c/p>\u003cp>明白而详细的描述后果Y。直接告诉他，他做的这件事情导致了一个什么样的结果。或者说他造成了一个什么样的刺激。最后是给你什么样的感受“z”。重要的不是说对方的哪个行为妨碍了你。而是他做这件事情给你产生了一个什么样的一个情绪。比如说他给你带来一个挫折，愤怒或者不安的情绪可能会干扰你。\u003c/p>\u003cp>当然，我们并不是建议，就是三个非得按照一样的顺序来，你也可以通过其它地方法顺序来沟通。\u003c/p>\u003cp>我举个简单的小例子，以我个人为例：昨天，我回家之后一直在玩手机，我女朋友直接抱怨我，就说我你都看了一天手机了。我直接回答就类似于反抗，直接说我看了没有一天，也就两个小时左右。我觉得这个抱怨就没有产生很好的互动。她要是说你看你一直看手机，没有理我，老娘很不开心。让我感到很痛苦，我很生气。她如果用上面XYZ流程给我说的话，可能我会及时反馈，去劝慰她，而不是直接反驳自己看了多久的手机。\u003c/p>\u003cp>自己在与同事，同学，好友，家人沟通的过程当中去表达自己的一些情绪。不管是抱怨也好，还是一个提出观点也好。有没有对于这个XYZ三个步骤的运用。或者哪个地方有一些欠缺，没有达成一个很好的一个结果，大家可以思考一下。我们差不多思考三分钟左右，然后大家简单说一下。\u003c/p>","interaction":"\u003cp>所以说我觉得这是一个简单的一个小例子，大家也可以再回想一下，自己在与同事，同学，好友，家人沟通的过程当中去表达自己的一些情绪。不管是抱怨也好，还是一个提出观点也好。有没有对于这个XYZ三个步骤的运用。或者哪个地方有一些欠缺，没有达成一个很好的一个结果，大家可以思考一下。我们差不多思考三分钟左右，然后大家简单说一下。\u003c/p>\u003cp>大家介意互相聊一下，看自己在平常工作生活中有没有遇到类似情况。\u003c/p>\u003cp>药山：你的迟到让我感到非常的生气，你的迟到影响了我的正常的工作安排，所以我感到非常生气。XYZ\u003c/p>\u003cp>比如你的部门负责人去沟通的时候，比如你以前仅仅是抱怨的话，你可以尝试用XYZ的方法告诉他，本来我们原定计划周六之前你们要上报离职人员数据，以便我们回收电脑。那么我知道这周有两人离职，但是你没有报。导致我们的下一步的预算出现了问题，因此对于我的职务来说给我造成很大的困扰。\u003c/p>\u003cp>这个不一定非得按照这个顺序来，比如可以先x再z再y。\u003c/p>\u003cp>千尘：现在天已经下雨了，然后你下班的时候没有提醒我要带伞，我很生气，我感觉我被忽略了。\u003c/p>\u003cp>可以了解到大家的沟通，比如沟通的方式，我真的觉得不要跟女朋友讲理，这个就是坏情绪的表达。咱们可以考虑在接下来的跟别人的一个互动中，也可以说说跟同事或者朋友的一个交流中可以通过这个xyz，或者是xzy这种不同的表达顺序。通过这个步骤或者说方法来表达自己的情绪。接下来大家可以在咱们便签纸上写一下自己下一步的一个小计划。比如说遇到同样的事情或者有情绪需要传达会做什么样的一个表达方式。\u003c/p>\u003cp>好的今天的拆书就到此结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497886875000,"updated_at":1497886875000,"ria":true},{"id":2897,"topic":"小量成功策略减轻压力","learn_goal":"学习者帮别人或者自己制定出小量成功目标，消除压力","remark":"有的人可能面对的是时间的压力，你需要在很短的时间里去完成很多任务，所以你不得不加班到深夜；有的人可能面临的是人际关系的压力，你觉得最近上司好像对你有一些看法，让你惴惴不安；有的人可能面临着换工作或者晋升的压力，你有一些预期，但是不知道会不会能够达成心中的目标。 当我们和这些压力共舞的时候，可能会出现焦虑，疲惫甚至抑郁，当然，这样的情况也干扰了你的生活工作，让你感觉到这个世界满满的恶意。过大的压力也阻碍了你进一步行动。\r\n我们每个人都讨厌压力，但是我们又不得不面对压力，所以很多人在寻求解决压力的办法，而这本《管理技能开发》就专门用一章来告诉我们如何提高压力管理的技巧，我们今天主要来学","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"norman","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"【学习目标】让学习者能够根据小量成功的策略，帮别人或者自己制定出小量成功目标，消除压力，迈出行动的第一步【自我介绍】大家好，我叫王冠华，是今天的拆书家。首先我用三个标签来介绍一下自己。第一个标签是跨界；第二个标签是成长，我的信条是人生时候都不能停止成长；第三个标签是拆书爱好者。【图书介绍】提问：请问大家在深圳这样一个快节奏的城市里，有没有时常感觉到非常有压力？事件：有的人可能面对的是时间的压力，你需要在很短的时间里去完成很多任务，所以你不得不加班到深夜；有的人可能面临的是人际关系的压力，你觉得最近上司好像对你有一些看法，让你惴惴不安；有的人可能面临着换工作或者晋升的压力，你有一些预期，但是不知道会不会能够达成心中的目标。 影响：当我们和这些压力共舞的时候，可能会出现焦虑，疲惫甚至抑郁，当然，这样的情况也干扰了你的生活工作，让你感觉到这个世界满满的恶意。过大的压力也阻碍了你进一步行动。解决：我们每个人都讨厌压力，但是我们又不得不面对压力，所以很多人在寻求解决压力的办法，而这本《管理技能开发》就专门用一章来告诉我们如何提高压力管理的技巧，我们今天主要来学习如何消除预期性压力的方法和技巧。","ratings_count":0,"texts":[{"id":5680,"quote":"\u003cp>小量成功\u003c/p>\u003cp>另一种与消除预期性压力有关的策略是小量成功策略（weick，1984)。我们说的“小量成功”，是指向预计的目标方向的微小但明确的变化。一个人可以首先改变一些相对容易改变的事，接着完成剩下的相对容易的事，依此类推。虽然孤立地看，每一个成功都是相对微小的，但这些小的成功积来可以产生一种动力感，给人一种正在向期望中的目际实质性地前进的印象。这种动力帮助我们同时也帮助其他人树立对自己具有达到目标的能力的信心。我们通过小量成功树立了信心，从而消除了与期望的变化相关的恐惧。当其他人看到我们取得进展时，我们也能获得他们的支持。\u003c/p>","explains":"\u003cp>&nbsp;这个片段看起来非常简单，主要讲的是小量成功策略如何减轻压力。\u003c/p>\u003cp>【what】那什么是小量成功策略呢？它主要指通过把大的任务分解成不同的小任务，取得每一个小任务的成功来达到实现最终的目标，从而减轻压力。\u003c/p>\u003cp>【why】我们为什么要用小量成功策略来达到减轻压力的目的呢？因为人总是喜欢做比较容易的事情，所以当我们把他们化解成一个个小的任务，会比较轻松的迈开实践的步伐，给自己和他人以信心。\u003c/p>\u003cp>【预防意义】大家可能觉得小量成功策略很简单，表面上看来确实如此，但是如何做到却不事那么容易。因为这需要大量的实践。\u003c/p>\u003cp>【对比说明】小量成功策略和另一个名词很像，就是微习惯。两者有一些相同点，但是也有很多不同。首先，小量成功策略主要解决的是压力过大的问题；而微习惯要解决的是养成习惯的问题；其次，小量成功策略在你的压力得到解决后，这个行为就结束了。但是微习惯，可以一直持续下去，成为你生活中的一部分；\u003c/p>\u003cp>【案例】比如，我想在一年内要有八块腹肌，很有压力，一下实现这个大目标很难，我会把任务分解成几个容易实现的任务，比如饮食结构要改变，每天健身计划等，每一个任务完成，就可以促进我最后目标的完成；但是微习惯就不同了，我为了身体健康，想养成健身的习惯，所以我把每天的运动量化为15分钟，这样就觉得很轻松，逐渐的就养成了健身的习惯。\u003c/p>\u003cp>【细化步骤】那么如何做到一个成功的小量成功策略呢?最关键的一点就是找到一个可以控制的小目标，什么是最小呢？原则是你可以掌控的，相对容易的任务，目的是让你快速行动起来；但是其实找到这个小目标并不容易，因为你要明确你的压力是什么？这个压力来自于你的什么目标？这个大目标必须是可以衡量的，才能分解成小的目标。第二，小量成功策略，是向预计的目标方向的微小但明确的变化，怎么样才能知道你的变化呢？那就需要追踪记录。因为只有追踪记录，你才能知道自己是不是朝着目标前进了；追踪记录的方法很多，比如做了一个墙面日历，每天完成就check。比如每晚睡前发一条微博或者微信等。第三，小量成功策略是目的是通过小任务，建立起自己和别人的信心，所以你要建立起奖惩反馈机制，你需要奖励提升自己的信心，同时也需要其他人给你反馈，让你看到自己的进步，给别人信心。这就是小量成功的三个步骤，即确定可以控制的目标，记录跟踪以及奖惩反馈。\u003c/p>","interaction":"\u003cp>A2：所以现在就要我们自己来实践一下，请问大家你或者你周围的朋友近有没有什么特别感觉压力山大的事情呢？比如要参加一个重要的考试，或者是要减肥重塑体型，也有可能是追求一个女神男神。请你用今天所学的知识来制定一个小量成功策略来，帮自己或者朋友减轻这份压力。具体的方法就是编写出一个有情景，人物、对话的剧本来，如果是解决自己的问题，所以你需要一人分饰两角，自己和自己对话，在对话的过程中，你分解了大目标，也确定了如何记录，如何反馈和奖励。下面就请大家花五分钟时间来写一下吧，五分钟后请大家分享。\u003c/p>\u003cp>学习者分享：\u003c/p>\u003cp>故事起因/背景： 我最近的事情特别多，感觉压力山大。\u003c/p>\u003cp>经过: 自我对话来减轻压力。\u003c/p>\u003cp>对话：\u003c/p>\u003cp>抱怨的我：哎呀，最近压力山大啊，好多事情堆积如山。\u003c/p>\u003cp>理性的我：每个人都有压力，现在的压力导致你有什么不好的事情发生吗？你的目标是什么啊？\u003c/p>\u003cp>抱怨的我：我的目标就是完成这个项目，按时交工，但是千头万绪啊。领导整天在催，烦死了。\u003c/p>\u003cp>理性的我：那这个事情可以分为哪些方面呢？\u003c/p>\u003cp>抱怨的我：谈判、审合同、确认工期、采购，产品设计修改等。\u003c/p>\u003cp>理性的我：那能不能想找一个比较容易做的事情呢？\u003c/p>\u003cp>抱怨的我：嗯，找一个比较容易的事情，貌似审合同比较容易一些，我可以先审合同。\u003c/p>\u003cp>理性的我：那很好，那为了让事情进展，你还可以做一个项目记录。\u003c/p>\u003cp>抱怨的我：好方法，我先了一个清单吧。\u003c/p>\u003cp>理性的我：嗯，完成一个任务就及时向领导汇报。有了阶段性成果就请自己吃顿好的。\u003c/p>\u003cp>抱怨的我：恩恩，我这周就把合同完成，然后再去做别的事情。做完了就去吃大餐，吼吼。\u003c/p>\u003cp>结果：压力减少，开始行动。\u003c/p>\u003cp>结尾：感谢小伙伴，这事一个非常完整地小量成功策略的制定，找到了最容易开始的事情，从而减轻了压力，希望大家能有所收获。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1497239659000,"updated_at":1497239744000,"ria":true},{"id":2246,"topic":"得体表达问题","learn_goal":"掌握用XYZ方式表达问题的方法","remark":"","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"封超","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家好，我叫封超，我的三个标签是读书，培训和运动。很高兴带领大家进行本次拆书活动。\r\n【学习目标】在跟随我完成本次RIA现场学习后，大家可以学到当我们的利益收到了侵害，我们如何使用XYZ方法表达我们的不满。\r\n【图书介绍】（F）本书的作者分别是美国杨百翰大学和密歇根大学的管理学教授，主要讲授了十大管理技能的内容和运用。(A)这本书与以往同类书不同的是在扎实的理论基础之上采用了调查等实证的方式，同时辅以案例和练习，让书中内容具有很强的实用性。(B)如果熟读此书，不仅可以帮助我们系统学习管理知识，还可以将之应用于工作，从而增强我们实际的管理能力。","ratings_count":0,"texts":[{"id":4915,"quote":"\u003cp>&nbsp; 下面请大家花两分钟时间阅读以下片段。\u003c/p>\u003cp>&nbsp; 戈登（Gordon，2000）描述了一个帮助你有效陈述你的问题的有用模型：“我有一个问题，当你做X时，Y为结果，并且我感觉到了Z。”虽然我们不提议通过记忆公式来提高沟通技能，但是在你脑子里记住这个模型有助于你理解“问题陈述”中的三个重要元素。\u003c/p>\u003cp>&nbsp;&nbsp; 首先，描述给你带来特定问题的具体行为（X）。这有助于你在急于给出反馈时给出一种评价性的或泛泛回答的倾向。\u003c/p>\u003cp>&nbsp;&nbsp; 其次，强调这些行为详细的、可见的后果（Y）。简单明白地叙述别人的行为给你带来了麻烦，通常是使他们做出改变的有效刺激。在快节奏的工作环境中，人们通常会意识不到自己行为的后果。他们并不想冒犯他人，但是他们经常要忙于应对有关“新产品推出”的截止日期，并且还要接收来自各方的负面反馈，当这种情况发生时，别人的注意力和他们行为的结果将会促使他们去改变。\u003c/p>\u003cp>&nbsp;&nbsp; 最后，描述你对问题结果的感受（Z）。重要的是要使回应人了解他的这些行为不仅仅是为你带来了不便，而且你需要向他们解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受是怎样干扰你的工作，这些行为可能使你更加难于集中注意力，或难于和消费者融洽相处，或无法获得老板的支持，或者不再愿意为了赶时间而做出个人牺牲。&quot;\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;&nbsp;很多情况，当我们的利益受到了侵犯，我们往往很难让侵犯我们的人改善他的行为，从而合理的维护自身利益。这种情况的原因在于，我们没有有效的向对方传达我们的遇到的问题，因此就造成侵犯我们的人实际上可能并没有意识到他的行为已经给别人造成了不便。因此为了有效表达我们的不满，我们可以运用三个步骤来加以改善，这三个步骤我们可以把它称作XYZ方法，这里的XYZ分别指代三个步骤，第一步为描述行为（用X指代），即将给你造成困扰的具体行为表达出来，第二步为强调后果（用Y指代），我们成为即重点强调这个行为给你造成了什么样的困扰。第三步为表达感受（用Z指代），即表达这个后果或问题给你带来了怎么的内心的负面感受。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;【强调不那么做的坏处】如果面对利益侵犯，我们没有用到XYZ方法来合理表示自己的不满，那么就有可能出现几种情况：要么是对方不知道他的行为已经冒犯了我；要么是对方即使知道他的行为冒犯了我，但是没有料想可能的后果；要么是对方即使知道他的行为已经对我产生了影响，也不会觉察这个影响给我造成的情感伤害。这样就根本无助于事情的解决，换句话说，侵害行为还会继续，对方会觉得理所应当，而我们将长期遭受痛苦的折磨。比如，老板无故让你加班一个星期，你身心俱疲，如果你选择沉默，那么你会痛苦，而老板可能还以为你完全没有问题。这个时候如果你用XYZ的方法，告诉老板你加班一个星期的事实，说明这个事情让你疲惫，影响工作也影响了家庭关系，你觉得非常痛苦和无助。那么事情很有可能得到更好的解决。\u003c/p>\u003cp>&nbsp; &nbsp;【举例】再举个例子，最近，每到晚上，我们家楼上都会发出很大的响声，影响家里安静，后来我妈妈忍无可忍上去找他，但因为当时情绪不好，以质问的方式和对方沟通，所以导致不欢而散，问题也没有得到根本解决。最近一次，因为声音又比较大，我上去找到他进行了再次沟通，我在谈话中没有发泄情绪，只是说明了几个点，第一，声音比较大（行为）第二，家里有老人，这个声音影响老人休息，第三，感觉比较吵闹，有些烦躁。对方听完有些歉意，至少表面说一定调整，后来声音有所改善。\u003c/p>","interaction":"\u003cp>拆书家提问设计：\u003c/p>\u003cp>【A1】激活经验（显像提问）\u003c/p>\u003cp>请各位回顾一下，在我们的生活中，过去有没有遇到过因为某人的不合适的行为，让你十分不爽，至今还难以释怀的事情？如果有，请自己先思考30秒，再在小组内讨论下，最后请小组派代表分享下。\u003cbr>\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者1：\u003c/p>\u003cp>我遇到了一个让我很郁闷的男同事，平时我们的工作是要相互协调，再和领导沟通要互相交流才能进行下一步的工作。但有的时候那位同事会主动私自去找领导沟通，沟通的内容却不和我讲。就会让我很被动，比如提交一个报告，那个同事和领导沟通后没有告诉我领导有在催我交报告。我就没有交，后来领导就直接来催我。我非常郁闷，就想找他发飙。\u003c/p>\u003cp>分享者2：\u003c/p>\u003cp>我的一个离职的同事，以前是我的领导，他以前说话很难听，一般第一句话都是针对人，就说你怎么怎么样，有一次开会的时候，他的第一句话就是点名批评我，说不知道我脑子里装的是什么，我就说了一句，我脑袋里装的豆渣，我就起身走了。\u003c/p>\u003cp>拆书家提问设计：&nbsp;\u003c/p>\u003cp>【A1+】（反思加工）\u003c/p>\u003cp>接下来请大家思考，假如上帝再给你一次机会的话，回到过去的相同的场景，学了今天采用以上的三步法，我们应该如何去做呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>分享者1：\u003c/p>\u003cp>我会和他讲，在我们两需要共同完成工作的时候，领导给了你反馈，你没有及时和我沟通，这样会让我们的工作有拖延，工作不能及时的完成，也会给领导造成一种误会就是我们没有认真工作，而且办事能力不足，这种做法让我感觉非常的郁闷，也非常的烦躁。\u003c/p>\u003cp>分享者2：\u003c/p>\u003cp>我会说，开会的时候你对我发火，说我脑子里装的什么，这样的批评造成了一种人身攻击，在这么多人面前说这样的话，会影响你在工作中的形象，也影响你和团队的关系，我觉得非常的愤怒，非常生气。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1490609459000,"updated_at":1490609718000,"ria":true},{"id":1555,"topic":"如何结构化表达自己的意见和不满，改变对方的行为？","learn_goal":"如何结构化表达自己的意见和不满，改变对方的行为？","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"丁华平","city":"成都"},"club":{"name":"成都蜀汉分舵","city":"成都"},"prologue":"大家上午好！欢迎大家参加我今天TF1-2的分享，首先自我介绍，我叫丁华平，目前从事的是通信行业，我的三个标签是：学习，自律，运动；为了一会儿沟通和讨论方便，我们现在分为三个组。。。","ratings_count":0,"texts":[{"id":4088,"quote":"\u003cp>那么今天给大家分享的这个段子，是希望通过学习这个段子，可以让大家熟悉和运用XYZ法有效的表达我们的意见、不满和建议使他人发生改变。\u003c/p>\u003cp>F:这个段子选择自大卫.A金S卡梅伦的《管理者技能开发》,《 管理者技能开发》是一本基于在各类企业中对有效管理者的广泛研究，从个人、人际关系和团队三个方面对管理技能进行了全面的探讨，是全球最权威、最全面的管理技能开发经典著作。\u003c/p>\u003cp>A:它通过“评估-学习-分析-练习-应用”的完整链条，为管理者的能力提升提供了坚实的结构性支撑。\u003c/p>\u003cp>B:通过阅读这本书并实践书中的方法可以有效开发和提升经理人的管理技能。同时，有效的管理与有效的从事其它活动并无太大差异，通过运用这本书上的技能，对我们幸福成功的生活一样有很大的指导意义。\u003c/p>\u003cp>下面给大家2分钟时间阅读手中的段子，阅读完毕，请举手示意我。\u003c/p>\u003cp>戈登描述了一个帮你有效阐述你的问题的有用模型：“我有一个问题，当你做X时，导致了结果Y,而我的感觉是Z\u003cbr>第一：描述给你带来问题的具体行为(X).这有助于你在急于给出反馈时避免给出一种评价性的或者泛泛的回答倾向。\u003cbr>第二：列出这些行为详细的，可见的后果（Y），简单明白的告诉对方，其行为给你带来的问题，通常是使他们改变的有效刺激。\u003cbr>第三：描述你对问题结果的感受（Z），重要的是不仅要使对方了解哪些行为妨碍了你，而且要解释它如何通过带给你挫折、愤怒或不安全等感受来影响你。解释这些感受在怎样干扰你的工作。\u003cbr>我们建议你把这个三步模型作为一般性的指导来使用。每个部分的顺序可能会有变化，而且你不要总是使用相同的词语。\u003cbr>\u003c/p>","explains":"\u003cp>好，我看大部分人都已经阅读完毕。\u003c/p>\u003cp>有些时候，我们会因为别人的行为导致了我们的不满，我们需要向别人表达我们的意见和情绪，大部分的做法是通过指责或揣测对方动机的表过方式，而这样往往会起到反作用，达不到我们想要的结果，如何解决这个问题呢，今天大家读的这个段子就告诉我们一个有效阐述问题的模型：XYZ法，通过这个模型来结构化表达我们的意见和不满，从而使他人发生改变。\u003c/p>\u003cp>具体分为三步:\u003c/p>\u003cp>第一步（X）：描述对方给你带来问题的具体行为。\u003c/p>\u003cp>第二步（Y）：列出这些行为带来的问题和后果。\u003c/p>\u003cp>第三步（Z）：描述你对产生问题的感受。当然这三个部分的顺序可以有变化。\u003c/p>\u003cp>通过这三步法可以让我们以事实为依据有效表达我们的感受和不满，而不是通过指责对方或揣测对方动机的表达方式，从而有效避免引发对方的戒备和反击，从而达到我们所想要的结果。\u003c/p>\u003cp>有一次，我们一个区域的综合支撑由于工作不力，一直与施工方没核对好设备损耗，导至我们与移动公司的帐务无法核算。我有些着急，我与他沟通时说：你怎么回事，和施工方核对多久了，怎么还没弄好？对方一听到我在责备她，找很多借口来反驳我，我一听到她找借口，更是有些生气，最后沟通效果可想而知。那运用XYZ法的模型来表达：X(具体行为）：你从两个月以前就在和施工方核对设备损耗的事，到现在一直没有核对出来，Y（结果）：这样我们与移动公司的帐务就无法核算清楚，马上又到年底了，我们今年的款有可能结算不回来呀，Z（感受）：我真有点担心和着急呀！ &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","interaction":"\u003cp>A1:激活经验\u003c/p>\u003cp>我们今天读了这段拆页，学习了有效表达我们的意见和不满的XYZ三步法。那么，现在请在座的各位想一下，在你工作中的上下级，或是生活中身边最亲近的人，比如父母，儿女，配偶，朋友，他们一定有让你不满的事情，现在请你写下来并在小组内分享，一会我们请其中一组选出一个人来表达出自己的案例，时间5分钟。\u003c/p>\u003cp>现场案例1：\u003c/p>\u003cp>A1：我是管单位行政的，每个月20号需要下边各部门交工作报表，然后25号汇总给单位领导。每个月都有某几个部门迟迟交不上来，我以前的沟通方式是：“你们怎么回事，让你们20号交就是交不上来，你们领导是怎么当的，这个工作还要不要做，你再不交上来，到时候直接和你的分管领导投诉，到时候看你们怎么办”。沟通结果和效果不好。\u003c/p>\u003cp>现场案例2：\u003c/p>\u003cp>A1：女儿喜欢看电视，但我又担心看电视影响学习和视力，于是在家里每次我只让她看半小时，可是每次到了半小时，女儿还想看，根本不愿意关。我以前的做法是粗暴的直接关掉。\u003c/p>\u003cp>A2:催化应用\u003c/p>\u003cp>那相信大家已经都结合自己的经验写出了过往的经历，那现在请大家运用今天这段内容学到的三步法：对方的行为，产生的结果，我的感受，加工出你的案例，来有效表达自己的意见和不满。希望大家2分钟之内完成，并把这个内容反馈给我。今天我的分享结束，谢谢大家。\u003c/p>\u003cp>现场案例1\u003c/p>\u003cp>A2：（X）今天都21号了，你们部门的工作报表还没有交上来，（Y）导致我们整个单位的工作报表都没办法上交，本月各个部门的绩效都有可能受影响，（Z）我真有点担心和着急啊。\u003cbr>\u003c/p>\u003cp>现场案例2\u003c/p>\u003cp>A2：（X）你已经看电视半小时了，再继续看的话，（Y）会影响你的学习，还会影响你的视力，(Z)我真是有些担心你呀。然后再关掉电视。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481111899000,"updated_at":1481112789000,"ria":true},{"id":1053,"topic":"· 这样抱怨就对了","learn_goal":"想抱怨时，学习者能用XYZ表达法，让对方容易理解和接受","remark":"想表达不满，却担心引起冲突；想抱怨，可除了情绪，似乎啥都木有改变……该怎样说才好呢？","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"八爪鱼","city":"宁波"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是园芳，在群里叫八爪鱼。今天我带拆的书目是《管理技能开发》。F：本书通过调查400多位有经验的高效管理者，提炼出了构成有效管理实践的10项技能，包括个人技能、人际关系技能和团体技能。A：这本书是清华大学管理系列教材，由清华大学出版社出版。作者大卫·A.惠顿(David A.Whetten) ， 金·S.卡梅伦(Kim S.Cameron) 都是名校的大学教授。在网上有读者这样评价：相比国内的书，有更多结合实例的分析，语言也不是八股文，让人很有读下去的感觉。B：“我怎样才能让别人接受我的想法？”“我该怎样激励那些受挫后，感觉很糟糕的人？”“我可以怎样帮助负责不同事项并且具有不同价值观的人一起共事，尤其是在面对压力的时候？”不管是组织各种活动，完成临期的各项工作任务，还是开导身边的朋友，处理与伴侣的情感问题，都可以从本书中得到一些启发。","ratings_count":0,"texts":[{"id":3243,"quote":"\u003cp>《管理技能开发（第9版）》，摘录自352页\u003c/p>\u003cp>模型：\u003c/p>\u003cp>“我有一个问题，当你做X时导致了结果Y，而我的感觉是Z。”\u003c/p>\u003cp>实例：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;我必须告诉你，当你在别人面前拿我的坏记性开玩笑时【行为】，我是多么难堪【感受】，我气坏了，都想把你的缺点也说出来报复你【后果】。\u003c/p>\u003cp>你说6点钟到这里，却7点多钟才来【行为】，晚饭泡汤了，我们看演出也迟到了【后果】，我感觉受到了伤害，觉着你不在乎我【感受】。\u003c/p>\u003cp>雇员想让管理层知道，不事先通知就要求我们加班，我们的工作一直很辛苦【行为】。这大概就是你提到的怨言和缺乏合作的原因【结果】。无论如何，我们希望让你知道这一政策已引起许多工人的憎恨【感受】。\u003c/p>","explains":"\u003cp>What：\u003c/p>\u003cp>生活中，我们总会遇到问题，想表达不满，可有时候又担心引起冲突，不敢说；想发牢骚，可除了抒发情绪，似乎什么都没有改变，说了也没用......\u003c/p>\u003cp>该怎么说才好呢？这时候，我们意识到，只有把“你的问题”说清楚，才可以让对方理解和接受，并且愿意去做出改变。\u003c/p>\u003cp>Why：\u003c/p>\u003cp>但往往很多时候，我们说不清楚我们的问题。特别是在情绪的引导下，一开口就会变成指责或者抱怨。要么就是“你怎么样怎么样”，要么就是“我怎么了怎么了”，这样的表达方式难免会让对方觉得反感，一开始就不想应答，听不下去的时候甚至会反过头来指责你，“你说我错了，你才错了呢，你看你怎么样怎么样...”进而演变成双方的争吵。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;How：\u003c/p>\u003cp>通过XYZ表达法，也就是行为-结果-感受，就可以把问题说清楚。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;1、描述给你带来问题的具体行为（X）。也就是对方做了什么事，找到让你不满的起因。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;2、列出已经发生的或者可预见的结果（Y）。描述这个结果给你带来的消极影响。行为和结果要以事实的形式表达，比如，领导对下属说：“你最近工作懒散，影响了工作进度。”这个其实是领导观察到的现象，属于个人观点，下属可能会反驳说；“没有啊，我觉得自己状态挺好的。”所以，不如直接说“本来下午4点要交的工作，你拖到第二天中午才完成，导致同事来投诉你。”这个才是明确的事实。\u003c/p>\u003cp>3、描述行为和结果带给你的感受（Z）。Z表达的要是自己的真实感受。“我觉得你可能会对这件事有看法”，这是个人的臆断，不是感受，应该换成“我觉得挺失望的”“我也不想看到这样的事情发生”。\u003c/p>\u003cp>4、想要解决问题的话，光陈述问题是不够的，还需要双方协商。所以，在对方对自己的问题表示理解和认同之后，提出合理的请求，希望对方做出一些好的改变。比如第二个实例中，迟到的一方主动道歉和说明缘由之后，另一方可以说，如果你下次有事要忙的话可以早点跟我说，那我就不用傻等了。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp; 好，我们刚刚学习了用XYZ表达法来陈述问题，在适当的时候提出合理的请求促使对方积极改变。现在让我们来做一个现场演练。现在我们分成三组，每组选择一个场景，设计一段对话，给大家8分钟的时间。\u003c/p>\u003cp>【场景一】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;小谢是一名大学新生，男朋友刚进了一个律师事务所实习。这段时间两个人都忙于各自的事情，很少见面。有一天，小谢给男朋友发了很多信息，男朋友正在工作没有及时回复，小谢就直接打电话过去，结果吵了一架，两个人冷战了好几天。\u003c/p>\u003cp>今天晚上，小谢主动约男朋友见面。\u003c/p>\u003cp>【场景二】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;小李刚进单位没几天，就负责策划一个重要的活动，为此小李天天熬夜写稿子做方案。但在活动开始当天，领导却不让她监场，派她去做别的事情。她不情愿地去了。后来领导每次找她去做不属于她分内的事的时候，她就会找一堆理由推脱。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;今天下午，领导主动找小李谈话。 &nbsp;\u003c/p>\u003cp>【场景三】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;小越剪了个新发型，回家后妈妈觉得不好看，这时候有个阿姨来她家，她妈妈就问阿姨：“你觉得小越这个发型怎样，是不是不如之前的？”小越一听，就气得跑回房间去了，关门的时候还把门重重地摔了一下。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;现在，小越的妈妈来到小越的房间找她聊聊。\u003c/p>\u003cp>(8分钟后)\u003c/p>\u003cp>&nbsp; &nbsp; 好，现在请第一组成员来演练，大家欢迎。\u003cbr>\u003c/p>\u003cp>第一组：场景三\u003c/p>\u003cp>小越（琳琳种种）：妈妈，你刚才在隔壁邻居阿姨的面前说我的发型不好看，我感觉很尴尬，很伤心。\u003c/p>\u003cp>小越妈妈（非常不着调）：这样啊。\u003c/p>\u003cp>小越：恩，我觉得心里很不爽。\u003c/p>\u003cp>小越妈妈：那我看到觉得不好看就直接说了，不知道你心里会不舒服。\u003c/p>\u003cp>小越：实际上很不舒服的，你这样说的话我都想当着阿姨的面，报复一下你，说你的衣服不好看。\u003c/p>\u003cp>小越妈妈：那我下次注意一下，不说了。\u003c/p>\u003cp>小越：我的发型真的不好看吗？怎么样改一下呢？\u003c/p>\u003cp>小越妈妈：我觉得可以再短一点，精神一点。\u003c/p>\u003cp>小越：好吧。\u003c/p>\u003cp>第二组：场景二\u003c/p>\u003cp>领导（庆银）：小李啊，来公司几天了，感觉怎么样？\u003c/p>\u003cp>小李（米莉丽）：领导啊，谢谢你前几天让我策划一个这么重要的活动，当时我也非常开心，也加班熬夜收集了很多资料，也花了很多心血。但是后来可惜的是，我没有机会在现场参加这个活动。那时我挺失落的，觉得是不是自己的能力得不到领导您的认可。所以最近这段时间，在工作上比较松懈。\u003c/p>\u003cp>领导：没事没事，你再努力努力，下次再给你个机会。\u003c/p>\u003cp>第三组：场景一\u003cbr>\u003c/p>\u003cp>小谢男朋友（野人大叔）：啥事啊？\u003c/p>\u003cp>小谢（红妹）：自从上次我们吵完架之后，这几天你也没有来找我，我发了朋友圈你也没给我点赞，我觉得很伤心，很害怕，是不是我们就这样了？就要分开了是吗？\u003c/p>\u003cp>小谢男朋友：那也不是，不是这个意思。\u003c/p>\u003cp>小谢：我觉得如果以后我们吵架的话，当天就要解决。\u003c/p>\u003cp>小谢男朋友：其实那次啊，我的工作正好非常忙。我看到了你的信息，然后我就想忙过这一阵，等我晚上闲下来，可以专心致志地给你回短信。没想到还没到晚上，你就劈里啪啦骂了我一通，正好呢我手上事也不顺，老板又批了我一通，搞的我心烦气躁的，不想跟你解释。后来在电话里面，你又一个劲说我不对，更让我觉得受不了，所以才会这样。这两天我也一直在调整自己的状态。是这样的情况。\u003c/p>\u003cp>小谢：那我们...\u003c/p>\u003cp>小谢男朋友：好了好了，别说了，走，看电影去。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475920100000,"updated_at":1475920100000,"ria":true}]};